if (!marked || !target || !resourceTarget) { $done({}); } else { $done({ body: "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\n9901803\n00:00:16.190 --> 00:00:18.270 align:middle line:85%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:00:18.350 --> 00:00:21.300\n本故事取材于实际犯罪档案\n\n2\n00:00:45.660 --> 00:00:50.450\n1969年7月4日 加州 瓦列霍市\n\n3\n00:01:04.980 --> 00:01:07.050\n你去哪了？我从七点等到现在\n\n4\n00:01:07.270 --> 00:01:09.640\n我去买烟火，上车吧\n\n5\n00:01:09.860 --> 00:01:14.430\n-让我来开\n-快上车，我一整天没吃东西了\n\n6\n00:01:16.450 --> 00:01:18.480\n你到底来不来？\n\n7\n00:01:28.250 --> 00:01:30.200\n艾德汉堡薯条餐馆\n\n8\n00:01:31.630 --> 00:01:35.790\n整个下星期在圣雷法第四街\n1017号的钢索里珠宝店\n\n9\n00:01:36.010 --> 00:01:38.250\n3直到星期五都营业至九点\n\n10\n00:01:38.680 --> 00:01:40.460\n这里人太多了\n\n11\n00:01:40.840 --> 00:01:42.840\n你不是很饿吗？\n\n12\n00:01:44.520 --> 00:01:46.840\n我们去安静一点的地方\n\n13\n00:01:48.140 --> 00:01:49.760\n好吧\n\n14\n00:02:00.860 --> 00:02:02.360\n我们来这里干嘛？\n\n15\n00:02:04.160 --> 00:02:08.530\n坐着、听听音乐、聊聊天\n\n16\n00:02:09.410 --> 00:02:11.530\n你有点怪怪的，你还好吧？\n\n17\n00:02:11.750 --> 00:02:13.740\n没事，很好啊\n\n18\n00:02:21.090 --> 00:02:23.750\n七月天耶，干嘛穿这么多？\n\n19\n00:02:23.970 --> 00:02:27.090\n-我会冷\n-都美国国庆日了你还会冷？\n\n20\n00:02:31.600 --> 00:02:33.970\n去死吧！\n\n21\n00:02:39.860 --> 00:02:41.150\n干嘛？\n\n22\n00:02:41.360 --> 00:02:43.020\n“去死吧” ？\n\n23\n00:02:44.490 --> 00:02:46.280\n闭嘴\n\n24\n00:03:11.060 --> 00:03:13.590\n那辆车有在露天戏院吗？\n\n25\n00:03:15.810 --> 00:03:18.560\n我在艾德餐馆有看到这辆车\n\n26\n00:03:24.450 --> 00:03:27.940\n-要我叫他开走吗？\n-留在车里\n\n27\n00:03:43.260 --> 00:03:45.790\n-那是你老公吗？\n-不是\n\n28\n00:03:49.350 --> 00:03:50.630\n黛玲，那是谁？\n\n29\n00:03:52.140 --> 00:03:54.050\n不要担心\n\n30\n00:03:54.270 --> 00:03:56.050\n别叫我不要担心，到底是谁？\n\n31\n00:03:56.270 --> 00:03:57.850\n没事啦\n\n32\n00:04:17.710 --> 00:04:19.580\n糟了 ！\n\n33\n00:04:22.300 --> 00:04:24.040\n快走吧\n\n34\n00:04:27.050 --> 00:04:28.710\n快走啊，小黛！\n\n35\n00:04:40.730 --> 00:04:42.310\n证件拿出来\n\n36\n00:04:50.580 --> 00:04:52.570\n老兄，你差点吓死我们\n\n37\n00:05:55.100 --> 00:05:58.130\n-瓦列霍警局\n-我要举报一起双尸命案\n\n38\n00:05:58.350 --> 00:06:01.050\n-你的姓名、地点？\n-哥伦布省道往东一英里的停车场\n\n39\n00:06:01.270 --> 00:06:05.810\n一辆咖啡色车上有两具尸体\n\n40\n00:06:06.030 --> 00:06:10.100\n他们被9毫米口径鲁格手枪射杀\n\n41\n00:06:10.320 --> 00:06:13.110\n去年那两个小鬼也是我杀的\n\n42\n00:06:13.660 --> 00:06:15.980\n再见\n\n43\n00:06:18.620 --> 00:06:22.780\n四星期后 加州 旧金山\n\n44\n00:06:33.680 --> 00:06:35.300\n吐出来\n\n45\n00:06:35.600 --> 00:06:37.210\n快点，儿子\n\n46\n00:06:37.470 --> 00:06:38.840\n我吞下去了\n\n47\n00:06:39.060 --> 00:06:40.300\n为什么？\n\n48\n00:06:40.520 --> 00:06:42.470\n因为是薄荷口味\n\n49\n00:06:42.850 --> 00:06:44.890\n不可以这样，对身体不好\n\n50\n00:06:46.150 --> 00:06:47.180\n午餐盒别忘了\n\n51\n00:06:47.900 --> 00:06:50.980\n-为什么不让我搭校车？\n-因为我们迟到了\n\n52\n00:06:52.950 --> 00:06:56.150\n听着,晚上你住妈妈和艾伦那里\n\n53\n00:06:56.870 --> 00:06:58.990\n你不喜欢有个新弟弟？\n\n54\n00:06:59.200 --> 00:07:01.110\n不喜欢\n\n55\n00:07:01.330 --> 00:07:03.120\n很诚实\n\n56\n00:07:04.920 --> 00:07:05.990\n认真学习\n\n57\n00:07:06.250 --> 00:07:07.790\n十二宫杀手\n\n58\n00:07:09.550 --> 00:07:12.000\n晚上我会考你喔\n\n59\n00:07:12.680 --> 00:07:15.210\n附带Gerrard唱机和\nPioneer音响，仅需188美元\n\n60\n00:07:15.430 --> 00:07:17.130\n十点以前到曼尼的店\n行动要快！\n\n61\n00:07:17.350 --> 00:07:19.510\n重建街64号\n在山丘上与86街的交叉口\n\n62\n00:07:19.770 --> 00:07:21.220\n《旧金山纪事报》\n\n63\n00:07:46.750 --> 00:07:48.200\n早安\n\n64\n00:07:48.960 --> 00:07:50.830\n-很好，你今天早啊！\n-早安\n\n65\n00:07:51.050 --> 00:07:52.330\n-大家早安\n-早安\n\n66\n00:07:53.220 --> 00:07:54.540\n慢慢来\n\n67\n00:08:02.180 --> 00:08:05.300\n提醒你明天是申请截止的期限\n\n68\n00:08:05.520 --> 00:08:08.100\n第十五届青年摇滚大赛\n\n69\n00:08:08.320 --> 00:08:12.480\n申请表可以在湾区\n各学校和图书馆索取\n\n70\n00:08:13.240 --> 00:08:15.060\n矮子，今天的咖啡如何？\n\n71\n00:08:15.320 --> 00:08:17.360\n今天的咖啡特别好喝！\n\n72\n00:08:36.010 --> 00:08:37.960\n编辑\n\n73\n00:09:01.540 --> 00:09:03.110\n两分钟后开编辑会议\n\n74\n00:09:11.630 --> 00:09:12.990\n请速交编辑部！\n\n75\n00:09:33.320 --> 00:09:35.810\n-大家早安\n-早安\n\n76\n00:09:36.030 --> 00:09:40.940\n史坦登，告诉浩尔先生\n那篇兵役委员会的报导棒呆了\n\n77\n00:09:41.450 --> 00:09:43.190\n葛雷史密斯先生\n\n78\n00:09:44.620 --> 00:09:47.070\n不行 不行\n\n79\n00:09:47.290 --> 00:09:49.320\n尚可接受\n\n80\n00:09:49.540 --> 00:09:51.990\n不行。就用这张尚可接受的吧\n\n81\n00:09:55.210 --> 00:09:57.710\n保罗，社会版有什么？\n\n82\n00:09:57.920 --> 00:10:01.840\n洁妮丝在大家脱光光之前\n就离开瑞士小火锅派对\n\n83\n00:10:02.050 --> 00:10:03.750\n的确是个重罪\n\n84\n00:10:03.970 --> 00:10:05.880\n不是盖的，你们见过她吗？\n\n85\n00:10:06.100 --> 00:10:08.510\n她会引起一连串犯罪事件\n\n86\n00:10:09.350 --> 00:10:11.430\n你得看看这个\n\n87\n00:10:16.610 --> 00:10:18.230\n去把发行人找来\n\n88\n00:10:18.490 --> 00:10:19.600\n亲爱的编辑\n\n89\n00:10:19.820 --> 00:10:23.110\n我去年圣诞节在赫曼河\n\n90\n00:10:23.330 --> 00:10:26.440\n和七月四日在瓦列霍附近\n谋杀两名青少年\n\n91\n00:10:26.660 --> 00:10:29.240\n为了证明我杀了他们，我将举出\n\n92\n00:10:29.460 --> 00:10:31.070\n只有警方和我自己才知道的细节\n\n93\n00:10:31.250 --> 00:10:35.290\n圣诞节。弹药品牌：Super-X\n\n94\n00:10:35.500 --> 00:10:37.040\n一共射出十枪\n\n95\n00:10:37.260 --> 00:10:39.710\n男孩倒在地上，双脚伸直\n\n96\n00:10:39.920 --> 00:10:41.540\n女孩…\n\n97\n00:10:43.510 --> 00:10:46.500\n麻烦你接着念\n\n98\n00:10:47.770 --> 00:10:50.470\n女孩向右倒，双脚朝西\n\n99\n00:10:50.690 --> 00:10:55.060\n七月四日。一位女孩穿着花纹套装\n\n100\n00:10:55.270 --> 00:11:00.140\n男孩膝盖也中弹。\n子弹品牌是韦斯顿\n\n101\n00:11:00.360 --> 00:11:01.900\n附上部分的密码\n\n102\n00:11:02.110 --> 00:11:04.150\n其余的两份密码\n\n103\n00:11:04.370 --> 00:11:08.570\n分别寄给了 《瓦列霍时报》\n以及《旧金山观察家报》的编辑\n\n104\n00:11:08.790 --> 00:11:12.410\n我要你将密码刊于贵报头版\n\n105\n00:11:12.620 --> 00:11:15.080\n密码将揭露我的身分\n\n106\n00:11:15.290 --> 00:11:17.950\n如果八月一日星期五前没登出\n\n107\n00:11:18.170 --> 00:11:23.750\n也就是69年8月1日周五，\n我就会在周五晚大开杀戒\n\n108\n00:11:23.970 --> 00:11:27.960\n我整个周末会猎杀落单的路人\n\n109\n00:11:28.180 --> 00:11:33.430\n直到我凑齐了一打尸体为止\n\n110\n00:11:33.650 --> 00:11:35.550\n没有署名，只有一个记号\n\n111\n00:11:37.190 --> 00:11:41.180\n看起来像是枪的瞄准器\n\n112\n00:11:42.110 --> 00:11:45.440\n今天就是八月一日\n他要我们刊在今天的晚报\n\n113\n00:11:45.660 --> 00:11:48.940\n《旧金山观察家报》没种刊登，\n我们就拿到湾区的独家报导\n\n114\n00:11:49.160 --> 00:11:52.360\n-这家伙扬言要杀害12人\n-不刊登，他就会犯案\n\n115\n00:11:52.580 --> 00:11:55.200\n刊登了，就会创下危险的先例\n\n116\n00:11:55.420 --> 00:11:56.450\n拜托，这很有新闻价值\n\n117\n00:11:56.670 --> 00:12:00.370\n那大众又将怎么看待我们报社？\n\n118\n00:12:00.590 --> 00:12:03.040\n等等，我们知道这谋杀案是真的吗？\n\n119\n00:12:03.260 --> 00:12:06.500\n-保罗？\n-干嘛，要我采访瓦列霍案件吗？\n\n120\n00:12:08.010 --> 00:12:12.050\n-好吧，给我十分钟\n-拍下密码交给旧金山警局\n\n121\n00:12:12.270 --> 00:12:15.590\n假设这是真的\n至少原稿在我们手上\n\n122\n00:12:16.230 --> 00:12:17.600\n好吧\n\n123\n00:12:18.480 --> 00:12:20.770\n小葛，你不是还有漫画要画？\n\n124\n00:12:20.980 --> 00:12:22.180\n对喔\n\n125\n00:12:28.410 --> 00:12:30.860\n我是《旧金山纪事报》记者保罗艾瑞\n\n126\n00:12:31.080 --> 00:12:34.320\n我有收到信，希望有人协助理清\n\n127\n00:12:34.960 --> 00:12:36.870\n-谢谢\n-穆拉斯警官\n\n128\n00:12:37.080 --> 00:12:39.700\n我是《旧金山纪事报》的保罗艾瑞\n\n129\n00:12:39.920 --> 00:12:43.290\n贵警局是否有未破解的枪击命案\n\n130\n00:12:43.510 --> 00:12:45.330\n发生于圣诞节或七月四日？\n\n131\n00:12:45.550 --> 00:12:48.590\n妈的，你们也收到了吗？\n\n132\n00:12:49.850 --> 00:12:52.460\n有了 ，瓦列霍警方证实了枪杀案\n\n133\n00:12:52.680 --> 00:12:55.630\n艾尔打给《观察家报》\n他们收到不同密码的信\n\n134\n00:12:55.850 --> 00:12:58.640\n所以《瓦列霍时报》圣诞节\n两名青少年被发现陈尸情人巷\n\n135\n00:12:58.860 --> 00:13:00.720\n受害者均在送达医院前死亡。\n大卫法瑞戴以及贝蒂珍森\n\n136\n00:13:00.940 --> 00:13:04.350\n七月四日 ，黛琳费伦和麦克梅\n我想是梅休\n\n137\n00:13:04.570 --> 00:13:06.850\n-他没死，她挂了\n-凶枪呢？\n\n138\n00:13:07.070 --> 00:13:09.520\n弹道检验符合信上提到的细节\n\n139\n00:13:09.740 --> 00:13:12.480\n我猜《瓦列霍时报》会刊登\n\n140\n00:13:12.700 --> 00:13:15.610\n《观察家报》要登，但不是头版\n\n141\n00:13:15.830 --> 00:13:17.110\n我说我们应该上头版\n\n142\n00:13:17.330 --> 00:13:20.030\n他要杀一打人也不是我们的错\n\n143\n00:13:20.250 --> 00:13:21.700\n罗伯\n\n144\n00:13:21.920 --> 00:13:23.790\n我们要那张漫画\n\n145\n00:13:25.420 --> 00:13:28.250\n-你还没划完？\n-我划完了啦，凯萝\n\n146\n00:13:28.470 --> 00:13:30.040\n发行人还在这里\n\n147\n00:13:30.260 --> 00:13:31.670\n真的？\n\n148\n00:13:32.310 --> 00:13:35.220\n查尔斯，初版十分钟后印刷\n\n149\n00:13:38.350 --> 00:13:40.050\n等我们一下\n\n150\n00:13:42.900 --> 00:13:44.270\n好，重新排版\n\n151\n00:13:44.860 --> 00:13:48.350\n把它刊在第四页\n\n152\n00:13:49.280 --> 00:13:52.400\n悬赏20元给破解密码的人如何？\n\n153\n00:13:52.620 --> 00:13:54.530\n他不会透露他的名字\n\n154\n00:13:55.620 --> 00:13:57.530\n摩迪酒吧？谁要一起去？\n\n155\n00:13:57.750 --> 00:13:59.860\n-我要去\n-好吧\n\n156\n00:14:03.750 --> 00:14:05.700\n摩迪酒吧\n\n157\n00:14:26.360 --> 00:14:29.270\n课本放在书桌上，灯打开\n\n158\n00:14:40.420 --> 00:14:41.910\n把你的书拿着\n\n159\n00:14:42.170 --> 00:14:43.450\n《解码专家》\n\n160\n00:14:44.540 --> 00:14:46.790\n去换睡衣\n\n161\n00:14:49.510 --> 00:14:50.920\n好了 ，大家听着\n\n162\n00:14:51.130 --> 00:14:53.210\n密码划分成三区块\n\n163\n00:14:53.430 --> 00:14:54.420\n12小时后 加州 索诺犸郡\n史凯格岛 海军情报中心\n\n164\n00:14:54.640 --> 00:14:56.630\n每区块有八行，十七个符号\n\n165\n00:14:56.850 --> 00:14:58.590\n符号间没有空格划分字句\n\n166\n00:14:58.810 --> 00:14:59.800\n6小时后 加州 旧金山 联邦调查局\n\n167\n00:15:00.020 --> 00:15:01.890\n没有数字、任何线索代换\n\n168\n00:15:02.100 --> 00:15:04.970\n符号至少有七种不同密码\n\n169\n00:15:05.190 --> 00:15:06.180\n5小时后 维吉尼亚州 兰利 中央情报局\n\n170\n00:15:06.400 --> 00:15:09.930\n希腊字母、摩斯密码、海军旗语\n气象符号、占星记号\n\n171\n00:15:10.190 --> 00:15:13.810\n瓦列霍大屠杀虚惊一场\n\n172\n00:15:15.700 --> 00:15:19.400\n-来看看这些密码\n-好\n\n173\n00:15:19.620 --> 00:15:23.070\n12小时后 加州 萨里纳斯\n哈顿夫妻家早餐时刻\n\n174\n00:15:24.000 --> 00:15:25.660\n要试试看吗？\n\n175\n00:15:27.000 --> 00:15:27.990\n3天后 加州 旧金山\n\n176\n00:15:28.210 --> 00:15:31.040\n以前坐这里的是个好漫画家\n鲍伯巴斯恩\n\n177\n00:15:31.260 --> 00:15:35.040\n突然就跳槽到电视公司\n\n178\n00:15:35.800 --> 00:15:37.500\n保罗艾瑞\n\n179\n00:15:38.560 --> 00:15:41.550\n罗伯葛雷史密斯，我来九个月了\n\n180\n00:15:44.480 --> 00:15:46.930\n你说对了 ，他没透露他的名字\n\n181\n00:15:47.150 --> 00:15:50.180\n-谁破解的？\n-沙利纳斯市的历史老师和他老婆\n\n182\n00:15:50.400 --> 00:15:53.520\n我热爱杀人因为很好玩\n\n183\n00:15:53.740 --> 00:15:57.360\n比猎杀危险动物更有快感\n\n184\n00:15:57.580 --> 00:16:01.610\n因为人类比任何猛兽更危险\n\n185\n00:16:01.830 --> 00:16:04.950\n杀人过程让我感到兴奋\n\n186\n00:16:05.170 --> 00:16:09.040\n甚至比性爱高潮更有快感\n\n187\n00:16:09.250 --> 00:16:12.870\n更棒的是当我死后\n\n188\n00:16:13.090 --> 00:16:16.330\n我会在天堂重生\n\n189\n00:16:16.550 --> 00:16:19.380\n我杀死的人会成为我的奴隶\n\n190\n00:16:19.600 --> 00:16:23.090\n我不会公布我的名字，因为\n\n191\n00:16:23.310 --> 00:16:26.510\n你们会阻碍我死后收藏奴隶\n\n192\n00:16:26.730 --> 00:16:29.220\n我认为这家伙头脑烧坏了\n\n193\n00:16:29.440 --> 00:16:32.680\n听说他还给了瓦列霍一个代码来提示我们\n\n194\n00:16:32.900 --> 00:16:34.940\n-底下那些是什么？\n-没意义的符号\n\n195\n00:16:35.150 --> 00:16:36.520\n或许是字谜\n\n196\n00:16:46.210 --> 00:16:48.280\n罗伯汉普\n\n197\n00:16:53.340 --> 00:16:56.540\n你怎么会猜字谜？\n\n198\n00:16:56.760 --> 00:16:58.460\n我喜欢猜字谜，我常玩\n\n199\n00:16:58.720 --> 00:17:00.090\n嬉皮\n\n200\n00:17:00.260 --> 00:17:03.010\n你怎么晓得他不会透露姓名？\n\n201\n00:17:03.980 --> 00:17:05.880\n“危险动物”\n\n202\n00:17:06.440 --> 00:17:08.260\n危险动物\n\n203\n00:17:08.900 --> 00:17:12.020\n危险动物？\n怎么听起来很耳熟？\n\n204\n00:17:19.280 --> 00:17:20.770\n-保罗\n-怎么，丹波顿？\n\n205\n00:17:20.990 --> 00:17:23.230\n-要开编辑会议\n-好吧\n\n206\n00:17:25.160 --> 00:17:26.570\n又来了一封信\n\n207\n00:17:26.790 --> 00:17:28.360\n内容差不多\n\n208\n00:17:28.580 --> 00:17:30.490\n描述杀人犯的各种细节\n\n209\n00:17:31.380 --> 00:17:34.950\n他在枪上装上手电筒\n所以才能在黑暗中行凶\n\n210\n00:17:35.170 --> 00:17:37.250\n他还自封了一个名号\n\n211\n00:17:41.050 --> 00:17:43.000\n亲爱的编辑，我是十二宫杀手\n\n212\n00:17:47.100 --> 00:17:51.390\n一个半月后 加州 那帕\n1969年9月27日\n\n213\n00:17:58.320 --> 00:18:00.860\n你晓得这里原本是蒙地舍罗镇？\n\n214\n00:18:01.660 --> 00:18:04.360\n后来郡政府认为这块土地\n改成一座湖比较有用\n\n215\n00:18:04.580 --> 00:18:08.150\n所以就把它淹没了\n\n216\n00:18:09.370 --> 00:18:13.160\n-一整座城镇\n-就这样沉在水底\n\n217\n00:18:13.380 --> 00:18:16.450\n-我们去年春天来过，记得吗？\n-对哦\n\n218\n00:18:23.100 --> 00:18:26.380\n-那里有个人\n-这是座公共公园啊\n\n219\n00:18:29.230 --> 00:18:31.340\n我觉得他在看我们\n\n220\n00:18:31.560 --> 00:18:33.680\n因为我们很好看\n\n221\n00:18:39.570 --> 00:18:41.350\n他到哪里去了？\n\n222\n00:18:43.990 --> 00:18:47.900\n-躲在树后面\n-好，他只是在撇尿\n\n223\n00:18:54.710 --> 00:18:56.910\n他走过来了\n\n224\n00:18:58.840 --> 00:19:00.370\n老天，他手上有枪\n\n225\n00:19:01.550 --> 00:19:03.080\n别动\n\n226\n00:19:03.300 --> 00:19:06.170\n-把钱和车钥匙交出来\n-没问题\n\n227\n00:19:06.640 --> 00:19:08.260\n我们不会怎么样的\n\n228\n00:19:08.470 --> 00:19:11.550\n我们不会反抗，告诉\n我们该怎么做就行\n\n229\n00:19:15.730 --> 00:19:17.220\n拿去\n\n230\n00:19:19.150 --> 00:19:21.600\n你可以拿走我所有的东西\n\n231\n00:19:25.160 --> 00:19:27.730\n你还想要什么东西？\n\n232\n00:19:27.950 --> 00:19:29.900\n好比说开张支票给你\n\n233\n00:19:32.670 --> 00:19:34.740\n我可以给你我的电话号码\n\n234\n00:19:35.960 --> 00:19:38.120\n或许我可以帮助你\n\n235\n00:19:39.210 --> 00:19:43.080\n-我可以帮你很多忙\n-他主修社会学\n\n236\n00:19:44.550 --> 00:19:47.920\n其实我念法律预科\n\n237\n00:19:49.140 --> 00:19:52.800\n车钥匙。我不知道钥匙放哪里了\n\n238\n00:19:53.020 --> 00:19:55.890\n可能在毯子底下，可以吗？\n\n239\n00:20:00.820 --> 00:20:02.190\n钥匙在这里\n\n240\n00:20:03.860 --> 00:20:07.320\n别站起来，我要她绑住你\n\n241\n00:20:11.750 --> 00:20:13.320\n好吧\n\n242\n00:20:32.680 --> 00:20:35.800\n他再靠近一点我可能抢得到枪\n\n243\n00:20:36.020 --> 00:20:38.050\n-别想乱来\n-没有\n\n244\n00:20:38.270 --> 00:20:40.810\n我从蒙大拿州越狱时杀了警卫\n\n245\n00:20:41.030 --> 00:20:42.810\n我不会乱来，好吗？\n\n246\n00:20:43.030 --> 00:20:44.810\n我不怕多杀一个人\n\n247\n00:20:46.820 --> 00:20:48.400\n别看我\n\n248\n00:20:55.120 --> 00:20:57.200\n那所监狱叫什么名字？\n\n249\n00:21:01.550 --> 00:21:03.870\n你说监狱在蒙大拿州对吧？\n\n250\n00:21:05.050 --> 00:21:08.830\n我要开走你的车去墨西哥\n\n251\n00:21:09.050 --> 00:21:11.050\n你绑住我们，我们没抱怨\n\n252\n00:21:11.260 --> 00:21:12.960\n你要什么我们也给了你\n\n253\n00:21:13.180 --> 00:21:15.170\n一点都不剩\n\n254\n00:21:15.890 --> 00:21:17.260\n没事的，没事的\n\n255\n00:21:17.480 --> 00:21:19.850\n她没有绑紧你，对吧？\n\n256\n00:21:22.820 --> 00:21:25.100\n躺下来让我绑住你的脚\n\n257\n00:21:25.320 --> 00:21:29.730\n这里晚上很冷，我们会冻死\n\n258\n00:21:37.830 --> 00:21:39.200\n好了吗？\n\n259\n00:21:41.590 --> 00:21:45.450\n有人会问我，枪有上膛吗？\n\n260\n00:21:56.270 --> 00:21:59.090\n没事，一切都会没事\n\n261\n00:22:29.260 --> 00:22:32.750\n43L2号警车前往南向奈斯谷街\n\n262\n00:22:32.970 --> 00:22:35.420\n找到一辆遗弃的\n白色大众Karmann Ghia汽车\n\n263\n00:22:43.020 --> 00:22:44.970\n瓦列霍 2-20-68 7-4-69\n\n264\n00:22:45.190 --> 00:22:47.180\n9-27-69 6:30\n刀杀\n\n265\n00:22:50.990 --> 00:22:52.770\n那帕市警察局\n\n266\n00:22:52.990 --> 00:22:58.070\n我要举报一起命案，是双尸命案\n\n267\n00:22:58.750 --> 00:23:02.070\n地点在公园总部以北两英里的\n\n268\n00:23:02.290 --> 00:23:06.330\n一辆白色大众Karmann Ghia汽车内\n\n269\n00:23:07.340 --> 00:23:09.250\n人是我杀的\n\n270\n00:23:09.510 --> 00:23:14.130\n43L2警车发现男性被害人\n救护车正前往现场\n\n271\n00:23:15.180 --> 00:23:17.250\n一样，男的没死，女的挂了\n\n272\n00:23:17.520 --> 00:23:21.010\n老天，很难想像经历者的感受\n还在车的侧面写上日期\n\n273\n00:23:21.230 --> 00:23:24.640\n瓦列霍两起凶杀案，那帕一起\n为什么在那帕？\n\n274\n00:23:24.860 --> 00:23:27.970\n他为什么在瓦列霍以外的地方做案？\n我的老天\n\n275\n00:23:28.190 --> 00:23:29.980\n你在划什么？\n\n276\n00:23:30.190 --> 00:23:33.230\n湖边的大学生\n这是他描述十二宫杀手的打扮\n\n277\n00:23:33.450 --> 00:23:35.980\n-天哪，果然是怪里怪气的\n-保罗，你在做什么？\n\n278\n00:23:36.200 --> 00:23:39.110\n海曼，我写完了\n我现在要把它打出来\n\n279\n00:23:39.330 --> 00:23:42.360\n没打完不算，我们还要审稿\n\n280\n00:23:45.540 --> 00:23:48.040\n-那是什么？\n-湖边的十二宫杀手\n\n281\n00:23:48.250 --> 00:23:52.210\n那小子是什么来头？\n他怪怪的，好像嗑了药\n\n282\n00:23:52.420 --> 00:23:54.670\n-小葛吗？他是个童子军一样的人物\n-是啊\n\n283\n00:23:54.890 --> 00:23:57.500\n不抽烟、不喝酒、不讲脏话\n\n284\n00:23:57.720 --> 00:24:00.510\n-他回来了\n-“人类比任何猛兽更危险”\n\n285\n00:24:00.720 --> 00:24:03.930\n我听过这句话在\n《最危险的游戏》里\n\n286\n00:24:04.150 --> 00:24:06.800\n某公爵把猎杀人类当运动的电影\n\n287\n00:24:07.020 --> 00:24:09.600\n猎杀人类，最危险的游戏\n\n288\n00:24:10.990 --> 00:24:13.480\n-那是谁？\n-瑟若夫公爵\n\n289\n00:24:13.700 --> 00:24:16.650\n瑟若夫？字头是Z？\n\n290\n00:24:18.330 --> 00:24:19.900\n这是新闻快报\n\n291\n00:24:20.120 --> 00:24:22.570\n以下的地区将进行宵禁\n\n292\n00:24:22.790 --> 00:24:25.610\n那帕、索拉诺、康特拉卡斯塔\n阿拉米达、马林、圣马刁\n\n293\n00:24:25.830 --> 00:24:26.820\n两星期后 加州 旧金山\n1969年10月11日\n\n294\n00:24:27.040 --> 00:24:28.830\n请大家注意自身安全\n\n295\n00:24:29.040 --> 00:24:32.540\n旧金山的维克叩应\n你不怕十二宫杀手？\n\n296\n00:24:32.760 --> 00:24:35.370\n谁会怕他，他只杀乡下小孩\n\n297\n00:24:35.590 --> 00:24:38.040\n我怕的是穿着奇装异服\n\n298\n00:24:38.260 --> 00:24:40.210\n只会乱搞杂交的嬉皮\n\n299\n00:24:40.430 --> 00:24:42.300\n-出租车\n-来自华卡维尔市的艾菲瑞叩应\n\n300\n00:24:42.520 --> 00:24:46.340\n刚才那位先生在做人身攻击\n死者不只是乡下小孩\n\n301\n00:24:46.560 --> 00:24:48.100\n他们是品行优良的年轻人\n\n302\n00:24:48.310 --> 00:24:50.850\n没人贬低这些人的性命\n\n303\n00:24:51.070 --> 00:24:52.890\n上一个家伙就这么想\n\n304\n00:24:53.110 --> 00:24:55.940\n我们北湾是个优良的社区\n\n305\n00:24:56.160 --> 00:24:59.690\n不像那些充斥撒旦崇拜者的城市\n\n306\n00:24:59.910 --> 00:25:02.900\n说得好，十二宫杀手崇拜撒旦吗？\n\n307\n00:25:03.120 --> 00:25:05.030\n奥克兰的安柏，你认为呢？\n\n308\n00:25:05.250 --> 00:25:08.910\n不晓得，不过印在报上的密码\n不像是基督教符号\n\n309\n00:25:09.130 --> 00:25:11.120\n我认为报社不该刊登\n\n310\n00:25:11.340 --> 00:25:14.040\n任何关于十二宫杀手做的事\n\n311\n00:25:14.260 --> 00:25:17.210\n他们只是为了增加发行量\n\n312\n00:25:17.470 --> 00:25:21.250\n不过十二宫杀手也说不刊登的话\n他就会杀更多人\n\n313\n00:25:21.470 --> 00:25:24.510\n登不登他照样会杀人\n至少我个人认为是这样\n\n314\n00:25:24.730 --> 00:25:28.010\n很有趣的观点\n你认为接下来他会怎么做？\n\n315\n00:25:48.790 --> 00:25:51.950\n-旧金山警局\n-有人在计程车里打架\n\n316\n00:25:52.290 --> 00:25:53.410\n你在哪里？\n\n317\n00:25:53.630 --> 00:25:56.540\n华盛顿街3398号，樱桃街转角\n\n318\n00:25:56.760 --> 00:25:58.710\n有人喝醉了 ，他好像在抢劫\n\n319\n00:25:58.930 --> 00:26:02.340\n-歹徒还在犯案吗？\n-是的，拜托你们快点\n\n320\n00:26:03.350 --> 00:26:05.340\n天哪，你看！\n\n321\n00:26:28.160 --> 00:26:29.570\n可恶！\n\n322\n00:26:32.250 --> 00:26:34.200\n不管你是谁，你欠我一座新台灯\n\n323\n00:26:34.420 --> 00:26:36.950\n计程车司机在普西迪区遭枪杀\n\n324\n00:26:37.170 --> 00:26:40.040\n凶手又不是我\n我老婆可以担保我整晚都陪着她\n\n325\n00:26:40.260 --> 00:26:42.290\n去煮咖啡\n\n326\n00:26:42.510 --> 00:26:43.840\n你会来接我？\n\n327\n00:26:44.050 --> 00:26:46.550\n我先说你要赔我哪种台灯\n\n328\n00:26:54.610 --> 00:26:57.680\n-我才刚上床耶\n-嫌犯是个黑人男性\n\n329\n00:26:57.900 --> 00:27:00.270\n华特封锁现场，维持秩序\n\n330\n00:27:00.490 --> 00:27:03.150\n说真的，我已经睡到手都麻了\n\n331\n00:27:03.370 --> 00:27:04.900\n要吃饼干吗？\n\n332\n00:27:08.410 --> 00:27:10.240\n你吃过日本料理吗？\n\n333\n00:27:10.460 --> 00:27:13.070\n-什么意思，像是照烧吗？\n-不，像是生海胆？\n\n334\n00:27:13.290 --> 00:27:15.780\n-生鱼片？\n-我正在吃东西耶\n\n335\n00:27:17.130 --> 00:27:20.000\n-我一直想试试看\n-那你为什么不试？\n\n336\n00:27:20.220 --> 00:27:21.710\n没时间\n\n337\n00:27:37.860 --> 00:27:40.810\n晚安两位\n今晚真是笨贼一箩筐\n\n338\n00:27:41.030 --> 00:27:43.480\n这礼拜第三起\n一定是趁收假前捞一笔\n\n339\n00:27:43.700 --> 00:27:46.820\n我派人带了警犬巡逻公园\n\n340\n00:27:47.030 --> 00:27:51.070\n被害人是保罗史坦\n死亡时间是十点十分\n\n341\n00:27:51.290 --> 00:27:55.240\n嫌犯朝后脑勺开了一枪\n司机的钱包、钥匙不见了\n\n342\n00:27:55.460 --> 00:27:57.410\n-你怎么知道被害人的名字？\n-计程车行来的\n\n343\n00:27:57.630 --> 00:27:59.410\n李洛指认他\n\n344\n00:27:59.630 --> 00:28:03.420\n这社区很注重治安\n我已经叫拖车过来了\n\n345\n00:28:03.630 --> 00:28:05.130\n-验尸官来了\n-有任何目击者吗？\n\n346\n00:28:05.340 --> 00:28:08.300\n小孩从那扇窗看见嫌犯\n\n347\n00:28:08.970 --> 00:28:10.260\n-他们有听见枪声吗？\n-没有\n\n348\n00:28:10.470 --> 00:28:13.260\n他们以为嫌犯喝醉\n跑到前座去殴打驾驶\n\n349\n00:28:13.480 --> 00:28:16.220\n大的那个孩子跑到楼下看清楚\n\n350\n00:28:16.440 --> 00:28:18.390\n她形容嫌犯为男性白人、戴眼镜\n\n351\n00:28:18.610 --> 00:28:20.680\n平头、健壮结实、穿深色夹克\n\n352\n00:28:20.900 --> 00:28:24.600\n-等等，不是说嫌犯是黑人吗？\n-那是无线电传送的报告\n\n353\n00:28:24.820 --> 00:28:27.440\n-我们已经更正了\n-那好\n\n354\n00:28:27.660 --> 00:28:30.070\n-你们还需要帮忙吗？\n-不了，走吧\n\n355\n00:28:30.290 --> 00:28:31.940\n谢啦，生日快乐\n\n356\n00:28:32.160 --> 00:28:34.110\n今天你生日？\n\n357\n00:28:34.330 --> 00:28:35.950\n-是啊\n-棒呆了 ，生日快乐！\n\n358\n00:28:36.170 --> 00:28:39.950\n-谢了 ，尸体还是现场？\n-今天你生日 ，尸体交给我\n\n359\n00:28:40.170 --> 00:28:44.250\n大卫，他把车里擦得很干净\n这里有些血迹\n\n360\n00:28:44.470 --> 00:28:46.750\n-指纹呢？\n-可能有，回局里再采指纹\n\n361\n00:28:46.970 --> 00:28:49.590\n奇怪的是，还找到手套\n\n362\n00:28:49.810 --> 00:28:52.840\n-嫌犯的吗？\n-手套上有血迹\n\n363\n00:28:53.640 --> 00:28:56.220\n彼得，好了吗？我能进去吗？\n\n364\n00:28:56.440 --> 00:28:57.430\n嗯，好了\n\n365\n00:28:59.020 --> 00:29:01.310\n-谁动了他？\n-史都华\n\n366\n00:29:07.910 --> 00:29:10.650\n我找到一枚9毫米弹壳\n\n367\n00:29:14.540 --> 00:29:16.240\n是啊，鲁格手枪\n\n368\n00:29:16.460 --> 00:29:18.530\n围观者没有任何线索\n\n369\n00:29:18.750 --> 00:29:21.120\n假设我是黑人男性嫌犯\n\n370\n00:29:21.340 --> 00:29:24.160\n其实是健壮结实的平头白人\n\n371\n00:29:24.420 --> 00:29:26.790\n我叫了车子，给他这个住址\n\n372\n00:29:27.050 --> 00:29:29.880\n我有给他住址吗？车资记录呢？\n\n373\n00:29:30.100 --> 00:29:31.300\n在这里\n\n374\n00:29:33.890 --> 00:29:37.760\n华盛顿和枫树街口\n东边的那条街口\n\n375\n00:29:57.920 --> 00:30:01.280\n光线和这边差不多\n假设我看见有人正在遛狗\n\n376\n00:30:01.500 --> 00:30:05.540\n你不希望有任何目击者\n所以叫他多开一条街再停车\n\n377\n00:30:05.760 --> 00:30:07.710\n我很聪明，等他排到停车挡\n\n378\n00:30:07.930 --> 00:30:10.380\n以免下手的时候他踩油门\n\n379\n00:30:10.590 --> 00:30:12.750\n他停下来了，把车停到公园里\n\n380\n00:30:12.970 --> 00:30:15.260\n我从右边开枪，他倒向右边？\n\n381\n00:30:15.470 --> 00:30:18.010\n也许你边开枪边抓他的衣领\n\n382\n00:30:18.230 --> 00:30:20.890\n不管怎样，我在前座\n留下了大量血迹\n\n383\n00:30:21.100 --> 00:30:23.930\n-你为什么要到前座？\n-为了拿钱\n\n384\n00:30:24.150 --> 00:30:27.100\n他挂了，你只要伸手拿钱包就行\n\n385\n00:30:27.320 --> 00:30:29.770\n这样根本不用担心沾到血迹\n\n386\n00:30:29.990 --> 00:30:31.770\n你为什么要走到前座？\n\n387\n00:30:32.620 --> 00:30:34.020\n-因为我是个笨蛋\n-但你不是笨蛋\n\n388\n00:30:34.240 --> 00:30:35.940\n你等他排档了\n\n389\n00:30:36.160 --> 00:30:38.400\n-谢了\n-不客气\n\n390\n00:30:40.120 --> 00:30:42.200\n-我能看看吗？\n-可以\n\n391\n00:30:42.420 --> 00:30:45.490\n我真笨，为了8块2毛5杀人\n\n392\n00:30:45.710 --> 00:30:50.040\n他是今晚第三名乘客\n谁有卡通动物饼干？\n\n393\n00:30:50.630 --> 00:30:52.920\n-卡通动物饼干？\n-在车上\n\n394\n00:30:53.140 --> 00:30:55.050\n我留着等会儿吃\n\n395\n00:30:55.260 --> 00:30:56.880\n好吧\n\n396\n00:31:00.890 --> 00:31:04.430\n-你是记者吗？\n-不是，我是旧金山警局的陶希警探\n\n397\n00:31:04.650 --> 00:31:08.310\n我能不能分别向您的小孩问话\n\n398\n00:31:08.530 --> 00:31:11.230\n-最好是单独问话？\n-他们才刚看到一个人被杀\n\n399\n00:31:11.860 --> 00:31:13.230\n我了解\n\n400\n00:31:13.450 --> 00:31:16.280\n-他们看起来像喝醉在打架\n-对啊，他拿了一块破布\n\n401\n00:31:16.490 --> 00:31:18.780\n走到车子旁边擦什么东西\n\n402\n00:31:19.000 --> 00:31:20.780\n你有看到他的脸吗？\n\n403\n00:31:21.000 --> 00:31:24.200\n我有，算是有吧\n\n404\n00:31:25.420 --> 00:31:27.700\n你记得他长什么样吗？\n\n405\n00:31:29.340 --> 00:31:30.620\n很普通\n\n406\n00:31:30.840 --> 00:31:32.710\n-是啊\n-很普通？\n\n407\n00:31:37.310 --> 00:31:40.550\n《旧金山纪事报》 请速交编辑部\n\n408\n00:31:40.770 --> 00:31:42.340\n速交编辑部\n\n409\n00:31:45.440 --> 00:31:48.810\n三天后 加州旧金山\n\n410\n00:31:55.530 --> 00:31:59.190\n我是十二宫杀手，昨晚在华盛顿街\n\n411\n00:31:59.410 --> 00:32:02.780\n枫树街口杀害计程车司机的凶手\n\n412\n00:32:03.000 --> 00:32:05.780\n附上被害人一块血衣做为证据\n\n413\n00:32:06.000 --> 00:32:10.540\n我也是北湾区命案的凶手\n\n414\n00:32:10.760 --> 00:32:15.080\n旧金山警方昨晚本来能抓到我\n\n415\n00:32:15.300 --> 00:32:18.170\n如果他们仔细搜查公园\n而不是骑着摩托车到处乱飙\n\n416\n00:32:18.390 --> 00:32:19.800\n-各位\n-大卫\n\n417\n00:32:20.020 --> 00:32:22.260\n保罗，衬衫在哪里？\n\n418\n00:32:23.390 --> 00:32:24.930\n在这里，老大\n\n419\n00:32:26.190 --> 00:32:29.720\n这就是小孩说的那块破布\n他走到前座撕下衬衫一角\n\n420\n00:32:29.940 --> 00:32:32.180\n-这算正式记录吗？\n-你认为呢？\n\n421\n00:32:32.400 --> 00:32:34.520\n他证实了瓦列霍及那帕的命案\n\n422\n00:32:34.740 --> 00:32:37.270\n-情况还会更糟\n-罗伯，你不用截稿吗？\n\n423\n00:32:38.580 --> 00:32:40.150\n情况还会更糟是啥意思？\n\n424\n00:32:40.580 --> 00:32:41.860\n念念最后的部分\n\n425\n00:32:42.080 --> 00:32:44.280\n小学生是很好的目标\n\n426\n00:32:44.500 --> 00:32:46.570\n我要在早上毁掉一辆校车\n\n427\n00:32:46.790 --> 00:32:48.240\n先把前轮射穿\n\n428\n00:32:48.460 --> 00:32:51.040\n然后一个一个把他们干掉\n\n429\n00:32:51.250 --> 00:32:53.370\n我的天，谁负责管校车？\n交通部吗？\n\n430\n00:32:53.590 --> 00:32:55.420\n-校委会\n-好\n\n431\n00:32:55.630 --> 00:32:57.920\n我要采集每位员工的指纹\n\n432\n00:32:58.140 --> 00:33:00.710\n有谁没碰过这封信？\n\n433\n00:33:05.020 --> 00:33:07.220\n回到我办公桌前去\n如果你需要的话我还能提供电话\n\n434\n00:33:07.440 --> 00:33:09.180\n我们要比对血迹及布料\n\n435\n00:33:09.400 --> 00:33:12.140\n我会连络那帕和瓦列霍警局\n将信交给沙加缅度警局进行检验\n\n436\n00:33:12.360 --> 00:33:15.560\n大卫，真的有在车上采到指纹吗？\n\n437\n00:33:15.780 --> 00:33:18.400\n没错，沾到血的部分指纹\n\n438\n00:33:18.950 --> 00:33:21.440\n-这条线索不准刊登\n-不会吧，干嘛这样？\n\n439\n00:33:22.290 --> 00:33:24.400\n连我也不准吗？\n\n440\n00:33:24.620 --> 00:33:26.410\n他说有采到指纹？\n\n441\n00:33:27.750 --> 00:33:29.120\n一部分\n\n442\n00:33:32.340 --> 00:33:36.370\n-他佩枪的方式跟史帝夫麦昆一样\n-是史帝夫麦昆抄袭陶希警探的\n\n443\n00:33:36.590 --> 00:33:40.000\n他觉得十二宫杀手会再寄密码吗？\n我觉得他会再寄密码\n\n444\n00:33:40.220 --> 00:33:43.130\n我的老天，你到底在做什么？\n\n445\n00:33:43.350 --> 00:33:46.470\n你又在干我说过的那档\n我不喜欢你干的事\n\n446\n00:33:46.690 --> 00:33:48.090\n-在我背后偷瞄\n-喔，穿帮了\n\n447\n00:33:48.310 --> 00:33:49.300\n没错\n\n448\n00:33:49.520 --> 00:33:51.260\n为了和旧金山警方配合\n\n449\n00:33:51.480 --> 00:33:55.020\n我们将刊登十二宫杀手的信件\n去掉威胁杀伤学童的那一段\n\n450\n00:33:55.240 --> 00:33:57.100\n我们不希望造成市民恐慌\n\n451\n00:33:57.320 --> 00:34:00.310\n所以我要请你们保密\n\n452\n00:34:00.530 --> 00:34:04.570\n回去继续工作吧，谢谢\n\n453\n00:34:20.010 --> 00:34:22.960\n餐盒中有汽水、红萝卜和花生酱\n\n454\n00:34:23.180 --> 00:34:26.300\n-爸，你不用陪我等\n-我知道\n\n455\n00:34:27.350 --> 00:34:29.220\n嗨，雪莉\n\n456\n00:34:33.520 --> 00:34:37.640\n等一下，今天我送他上学，好吗？\n\n457\n00:34:37.860 --> 00:34:39.190\n来吧\n\n458\n00:34:41.490 --> 00:34:46.400\n十小时后 加州 沙加缅度 犯罪鉴定与调查局\n\n459\n00:34:56.960 --> 00:34:58.210\n那是什么？\n\n460\n00:34:58.590 --> 00:35:01.670\n与小写的r有类似之处\n\n461\n00:35:10.520 --> 00:35:12.720\n-那个呢？\n-再说一个字\n\n462\n00:35:12.940 --> 00:35:15.810\n就请你到走廊上等。我得集中注意力\n\n463\n00:35:16.020 --> 00:35:19.520\n-抱歉\n-抱歉也是字\n\n464\n00:35:30.000 --> 00:35:32.700\n小写的r有类似之处\n\n465\n00:35:37.250 --> 00:35:39.200\n我们得发布校车恐吓的消息\n\n466\n00:35:39.840 --> 00:35:42.790\n-一发布我们就完了\n-早就完了\n\n467\n00:35:43.010 --> 00:35:45.040\n我们只是把计程车命案\n\n468\n00:35:45.260 --> 00:35:47.090\n改为校园大屠杀\n\n469\n00:35:48.470 --> 00:35:50.720\n首席审核官\n\n470\n00:35:53.850 --> 00:35:55.100\n问题文档处理办公室\n\n471\n00:35:55.270 --> 00:35:58.010\n十二宫杀手来到了旧金山\n\n472\n00:35:58.230 --> 00:36:01.180\n旧金山警方今晚发布声明\n\n473\n00:36:01.400 --> 00:36:03.350\n他最后寄去的一封信中\n\n474\n00:36:03.570 --> 00:36:06.570\n坦承谋杀计程车司机保罗史坦\n\n475\n00:36:06.780 --> 00:36:10.190\n十二宫杀手并扬言威胁说\n他将锁定校车\n\n476\n00:36:10.410 --> 00:36:13.860\n把上面的学童一一的杀死\n\n477\n00:36:17.250 --> 00:36:19.700\n如果您有关于十二宫杀手的线索\n\n478\n00:36:19.920 --> 00:36:24.000\n请拨打旧金山警局的报案专线\n\n479\n00:36:28.050 --> 00:36:31.050\n有潜在同性恋倾向\n\n480\n00:36:32.180 --> 00:36:35.590\n十二小时后 加州 旧金山\n\n481\n00:36:40.820 --> 00:36:42.390\n我们需要警察出动\n\n482\n00:36:47.240 --> 00:36:50.030\n四点钟开记者会，应该给些消息\n\n483\n00:36:50.240 --> 00:36:53.490\n我们和教委会配合\n应该很快就会有线索\n\n484\n00:36:53.710 --> 00:36:55.860\n-有什么线索？\n-接都接不完的电话\n\n485\n00:36:56.080 --> 00:36:58.830\n专线打不进来他们就透过总机\n\n486\n00:36:59.040 --> 00:37:02.830\n-有具体的嫌犯吗？\n-每小时90名， 目前累积到500名\n\n487\n00:37:03.050 --> 00:37:06.080\n不能缩小范围吗？\n我也想，如果我能出去查案\n\n488\n00:37:06.300 --> 00:37:07.540\n重案组，请稍候\n\n489\n00:37:07.760 --> 00:37:11.670\n对啦，等一下\n我们得告诉民众警方动用全力\n\n490\n00:37:11.890 --> 00:37:15.720\n-你能给我多少人力？\n-目前就你和比尔，周一又要上课\n\n491\n00:37:15.940 --> 00:37:17.510\n我知道，我有三个女儿\n\n492\n00:37:17.730 --> 00:37:20.930\n-我知道，阿姆斯壮呢？\n-他正在和瓦列霍警局通话\n\n493\n00:37:21.150 --> 00:37:22.850\n我们需要你们的资料，杰克\n\n494\n00:37:23.070 --> 00:37:25.520\n我想见见生还者，麦克梅休\n\n495\n00:37:25.740 --> 00:37:26.980\n没办法，他走人了\n\n496\n00:37:27.200 --> 00:37:30.150\n唯一看见凶手真面目的人失踪了？\n\n497\n00:37:30.370 --> 00:37:33.240\n在医院我们有整天让他指认\n\n498\n00:37:33.450 --> 00:37:35.570\n-但是他一出院就落跑了\n-是吗，为什么？\n\n499\n00:37:35.790 --> 00:37:38.070\n我猜他不想被拖下水\n\n500\n00:37:38.290 --> 00:37:40.330\n你能寄来手上有的资料吗？\n\n501\n00:37:40.540 --> 00:37:43.290\n这应该是双方面的吧\n\n502\n00:37:43.510 --> 00:37:46.000\n我们需要计程车上采到的指纹\n\n503\n00:37:46.220 --> 00:37:48.500\n还有嫌犯那封信的笔迹\n\n504\n00:37:48.720 --> 00:37:50.710\n抱歉，事情发生得太快\n\n505\n00:37:50.930 --> 00:37:53.510\n那帕那里该跟谁联络配合？\n\n506\n00:37:53.720 --> 00:37:54.920\n找肯恩纳尔罗\n\n507\n00:37:55.140 --> 00:37:57.090\n我们应该拿到嫌犯的笔迹\n\n508\n00:37:57.310 --> 00:37:59.720\n抱歉，事情发生得太快\n\n509\n00:37:59.940 --> 00:38:02.100\n-我们需要犯罪现场的照片\n-办不到\n\n510\n00:38:02.320 --> 00:38:04.430\n肯恩，我不想跟你争管辖权\n\n511\n00:38:04.650 --> 00:38:06.850\n不是啦，是我们没有犯罪现场\n\n512\n00:38:07.070 --> 00:38:10.360\n巡警几乎把现场彻底破坏了\n\n513\n00:38:10.570 --> 00:38:13.190\n-我们只采集到一些鞋印\n-什么？\n\n514\n00:38:13.410 --> 00:38:17.650\n往返犯罪现场十号半男用长靴\n\n515\n00:38:17.870 --> 00:38:20.530\n军用品专卖店才买得到的军靴\n\n516\n00:38:20.750 --> 00:38:22.740\n特别设计用来行走在机翼上用的\n\n517\n00:38:22.960 --> 00:38:25.370\n你得有军用识别证才能购买\n\n518\n00:38:25.590 --> 00:38:27.580\n所以嫌犯有可能是职业军人\n\n519\n00:38:27.800 --> 00:38:30.080\n-你们有因此缩小范围吗？\n-有\n\n520\n00:38:30.300 --> 00:38:31.790\n-瓦列霍警方呢？\n-不知道\n\n521\n00:38:32.010 --> 00:38:33.840\n那不是我的辖区\n\n522\n00:38:34.060 --> 00:38:37.840\n-我需要那些鞋印的照片\n-没问题，你先把那封信寄过来\n\n523\n00:38:38.060 --> 00:38:39.680\n鉴识组不是寄了备份吗？\n\n524\n00:38:39.890 --> 00:38:41.640\n没，瓦列霍警局有收到\n我们没有\n\n525\n00:38:41.860 --> 00:38:45.220\n我会请他们…算了 ，我电传给你\n\n526\n00:38:45.440 --> 00:38:47.020\n我们没有电传机\n\n527\n00:38:47.240 --> 00:38:49.600\n-好，我立刻邮寄过去\n-我们也会寄出资料\n\n528\n00:38:49.820 --> 00:38:52.900\n打给穆拉斯，或许他能给你油印的\n\n529\n00:38:53.120 --> 00:38:55.900\n何不直接要石膏模的照片？\n\n530\n00:38:56.120 --> 00:38:58.400\n还要等，因为他们没有电传机\n\n531\n00:38:58.620 --> 00:39:00.110\n我们也没有\n\n532\n00:39:00.330 --> 00:39:03.410\n-我只希望彼此能互相配合\n-你打给索拉诺的警长办公室了吗？\n\n533\n00:39:03.630 --> 00:39:05.240\n为什么要打到索拉诺？\n\n534\n00:39:05.460 --> 00:39:08.620\n因为去年圣诞节的命案\n隶属索拉诺辖区\n\n535\n00:39:08.840 --> 00:39:11.790\n-我以为他们在瓦列霍的辖区\n-不对，犯罪现场在边界\n\n536\n00:39:12.010 --> 00:39:15.250\n-你必须和双方配合\n-好吧\n\n537\n00:39:15.470 --> 00:39:18.090\n比尔？我能和你说句话吗？\n\n538\n00:39:22.190 --> 00:39:24.180\n你在哪里看到这家伙？\n\n539\n00:39:25.070 --> 00:39:27.430\n我们奉命去那里找一名男性黑人\n\n540\n00:39:27.650 --> 00:39:28.890\n当时他在哪里？\n\n541\n00:39:29.110 --> 00:39:31.980\n杰克森街，往东差不多半条街\n\n542\n00:39:32.200 --> 00:39:34.900\n-枪击案发生后三分钟左右\n-差不多\n\n543\n00:39:35.120 --> 00:39:37.730\n-你们往东还是往西？\n-我们往西\n\n544\n00:39:37.950 --> 00:39:39.570\n你们当时在西向杰克森街\n\n545\n00:39:39.790 --> 00:39:42.450\n计程车在西南方一条街口外\n\n546\n00:39:42.670 --> 00:39:43.660\n是的\n\n547\n00:39:43.880 --> 00:39:46.450\n-你有慢下来吗？\n-我们当然有慢下来\n\n548\n00:39:46.670 --> 00:39:48.790\n勤务中心说嫌犯是男性黑人\n\n549\n00:39:49.010 --> 00:39:50.120\n后来更正了\n\n550\n00:39:50.340 --> 00:39:52.830\n我们发现他时还没更正\n\n551\n00:39:53.050 --> 00:39:56.800\n而且他是白人\n看来不赶时间，步伐又很笨重\n\n552\n00:39:57.010 --> 00:39:59.670\n步伐笨重？什么意思？\n\n553\n00:40:00.980 --> 00:40:03.550\n-拖着脚走路\n-健壮结实，平头吗？\n\n554\n00:40:04.690 --> 00:40:06.100\n对，没有错\n\n555\n00:40:07.440 --> 00:40:10.810\n听着，当时很暗\n他又穿着深色夹克\n\n556\n00:40:11.030 --> 00:40:14.190\n-根本无法…\n-他可能全身沾满了血\n\n557\n00:40:15.870 --> 00:40:17.480\n你有拦下他？\n\n558\n00:40:19.790 --> 00:40:21.320\n有没有问他话？\n\n559\n00:40:21.960 --> 00:40:23.860\n-有？没有？\n-没有\n\n560\n00:40:24.710 --> 00:40:26.490\n去找人划张素描\n\n561\n00:40:26.710 --> 00:40:29.160\n立刻把新的嫌犯划像发布出去\n\n562\n00:40:32.510 --> 00:40:33.500\n两天后 加州 旧金山\n\n563\n00:40:33.720 --> 00:40:37.090\n旧金山目前累计五名被害人，凶手…\n\n564\n00:40:37.300 --> 00:40:39.500\n我要在早上向一辆校车下手\n\n565\n00:40:39.720 --> 00:40:41.760\n旧金山警方\n\n566\n00:40:43.100 --> 00:40:45.680\n本周日滚石乐团举行演唱会\n\n567\n00:40:45.900 --> 00:40:47.850\n《旧金山纪事报》收到\n\n568\n00:40:48.060 --> 00:40:51.100\n来自十二宫杀手的最新信件\n\n569\n00:40:51.610 --> 00:40:54.140\n别在我背后偷瞄\n\n570\n00:40:54.360 --> 00:40:57.150\n-想没想过“水理论” ？\n-什么？\n\n571\n00:40:57.370 --> 00:41:00.610\n犯罪现场不是在水边\n就是死者姓名与水有关\n\n572\n00:41:00.830 --> 00:41:03.780\n-这就是你的水理论\n-贝瑞莎湖、蓝石泉\n\n573\n00:41:04.000 --> 00:41:06.200\n-赫曼湖\n-“滑” 盛顿和樱桃街口？\n\n574\n00:41:08.330 --> 00:41:10.910\n-你觉得呢？\n-不合理\n\n575\n00:41:11.130 --> 00:41:13.410\n我在读这本《谋杀案调查》\n\n576\n00:41:13.630 --> 00:41:15.210\n-李蒙奈史奈德着\n-是李摩\n\n577\n00:41:15.430 --> 00:41:16.750\n他说要从犯案模式着手调查\n\n578\n00:41:16.970 --> 00:41:20.090\n不，这不是件普通的刑事案件\n\n579\n00:41:20.310 --> 00:41:22.550\n-为什么不是？\n-有四个案发现场\n\n580\n00:41:22.770 --> 00:41:25.550\n索拉诺、瓦列霍、贝瑞莎和这里\n\n581\n00:41:25.770 --> 00:41:29.470\n前三个案发地点以及信件\n都没有采到有效的指纹\n\n582\n00:41:29.690 --> 00:41:33.060\n这个犯罪天才为什么会突然跑来\n留下一枚沾血指纹？\n\n583\n00:41:33.280 --> 00:41:35.390\n假设手套是嫌犯的\n\n584\n00:41:35.610 --> 00:41:37.850\n难道他杀了司机后又脱下来？\n\n585\n00:41:38.070 --> 00:41:39.060\n所以那不是他的指纹？\n\n586\n00:41:39.280 --> 00:41:42.280\n或许是或许不是，这不是重点\n重点是第一起谋杀案\n\n587\n00:41:42.490 --> 00:41:45.030\n-大卫法瑞戴和贝蒂珍森\n-双双身亡\n\n588\n00:41:45.250 --> 00:41:47.530\n他之后就只杀害女性\n\n589\n00:41:47.750 --> 00:41:49.950\n-他并不是没尽力\n-并不是\n\n590\n00:41:50.170 --> 00:41:53.700\n梅休存活，费伦死亡\n哈特奈尔生还，薛伯没有\n\n591\n00:41:53.920 --> 00:41:57.000\n他对女人特别投入\n忘了要杀死男人\n\n592\n00:41:57.220 --> 00:41:59.500\n加上他们是在野外约会的情侣\n\n593\n00:41:59.720 --> 00:42:01.380\n-保罗史坦就不是\n-没错\n\n594\n00:42:01.600 --> 00:42:03.710\n单身男性司机不符合这些条件\n\n595\n00:42:03.930 --> 00:42:05.590\n不符合\n\n596\n00:42:06.140 --> 00:42:08.720\n那么十二宫杀手为什么要杀他？\n\n597\n00:42:11.270 --> 00:42:13.350\n他在改变犯案模式\n\n598\n00:42:22.990 --> 00:42:25.070\n-喂？\n-有人自称是十二宫杀手\n\n599\n00:42:25.290 --> 00:42:27.070\n半小时前打给奥克兰警局\n\n600\n00:42:27.290 --> 00:42:28.280\n两天后 加州 旧金山\n1969年10月22日\n\n601\n00:42:28.500 --> 00:42:30.820\n他说三小时后\n会叩应吉姆顿巴的现场谈话节目\n\n602\n00:42:31.040 --> 00:42:33.580\n-在电视上吗？\n-他要梅尔文贝利当他的律师\n\n603\n00:42:33.800 --> 00:42:36.200\n好，快把梅尔文叫醒\n\n604\n00:42:38.800 --> 00:42:40.120\n卡通动物饼干？\n\n605\n00:42:40.340 --> 00:42:41.920\n在置物箱\n\n606\n00:42:42.140 --> 00:42:43.710\n这些是防弹车窗吗？\n\n607\n00:42:43.930 --> 00:42:46.300\n对，梅尔文，你不必躺在下面\n\n608\n00:42:46.520 --> 00:42:50.470\n这家伙是枪神\n随时都能让我一枪毙命\n\n609\n00:42:50.690 --> 00:42:53.970\n-你确定你行吗？\n-不用担心我，警探\n\n610\n00:42:54.190 --> 00:42:56.310\n灯光一亮我就会没事了\n\n611\n00:42:56.530 --> 00:42:58.390\n这个男人向我求救\n\n612\n00:42:58.610 --> 00:43:00.730\n你担心的那个\n随时可能射杀你的男人\n\n613\n00:43:00.950 --> 00:43:04.150\n这些是什么，饼干？\n\n614\n00:43:04.370 --> 00:43:06.400\n老天爷，你有清过车子吗？\n\n615\n00:43:06.620 --> 00:43:10.910\n可恶，其它新闻台得到消息了\n\n616\n00:43:19.920 --> 00:43:22.630\n让他说话，说服他跟你见面\n\n617\n00:43:22.840 --> 00:43:26.710\n如果你有机会\n请他到中国城圣犸利教堂碰面\n\n618\n00:43:26.930 --> 00:43:28.300\n你们会追踪电话？\n\n619\n00:43:28.520 --> 00:43:31.260\n你要让他在线上十五分钟以上\n\n620\n00:43:31.480 --> 00:43:34.300\n应该可以，对吧，吉姆？\n\n621\n00:43:36.360 --> 00:43:39.980\n-十五秒，清空摄影棚\n-清空摄影棚\n\n622\n00:43:44.910 --> 00:43:47.940\n拿去吧，你这个醉鬼\n\n623\n00:43:48.160 --> 00:43:50.610\n我们要中断节目插播一则新闻\n\n624\n00:43:50.830 --> 00:43:55.030\n欢迎收看本集特别节目\n现场邀请十二宫杀手\n\n625\n00:43:55.250 --> 00:43:58.240\n亲自指定的律师\n梅尔文贝利律师\n\n626\n00:43:58.460 --> 00:44:00.410\n快吃完，然后放到水槽\n\n627\n00:44:00.630 --> 00:44:03.370\n-早安，梅尔文\n-早安，吉姆\n\n628\n00:44:03.590 --> 00:44:06.750\n电话线已开放，贝利也在现场\n\n629\n00:44:06.970 --> 00:44:09.880\n-我很乐意帮忙\n-没错，你是来帮忙\n\n630\n00:44:10.100 --> 00:44:15.550\n请民众不要拨打进来占线\n好让十二宫杀手本人可以和我们连线\n\n631\n00:44:23.780 --> 00:44:26.270\n我看了你演出 《星际迷航记》\n演得很棒\n\n632\n00:44:26.490 --> 00:44:30.740\n可惜停播了，工作人员都很好\n\n633\n00:44:30.950 --> 00:44:33.950\n我常常考虑成为全职演员\n\n634\n00:44:34.620 --> 00:44:36.570\n-你的角色叫什么？\n-戈耳冈\n\n635\n00:44:36.790 --> 00:44:38.870\n戈耳冈，没错\n\n636\n00:44:39.920 --> 00:44:44.170\n-快录音，开始录音\n-我们接到电话，准备上现场\n\n637\n00:44:45.760 --> 00:44:47.460\n喂？\n\n638\n00:44:50.470 --> 00:44:53.260\n你好，这是梅尔文贝利\n\n639\n00:44:53.890 --> 00:44:55.760\n请问你是谁？\n\n640\n00:44:55.980 --> 00:44:59.180\n我是十二宫杀手\n\n641\n00:45:01.530 --> 00:45:05.560\n你有没有别的名字？\n比较没这么恐怖的\n\n642\n00:45:07.370 --> 00:45:08.650\n山姆\n\n643\n00:45:08.870 --> 00:45:10.980\n-山姆\n-是的\n\n644\n00:45:11.200 --> 00:45:14.570\n山姆，你觉得你需要治疗么？\n\n645\n00:45:14.790 --> 00:45:16.570\n我是生了病，但不是疯子\n\n646\n00:45:16.790 --> 00:45:18.950\n你的健康出了问题？\n\n647\n00:45:19.170 --> 00:45:20.790\n我病了 ，我头很痛\n\n648\n00:45:21.000 --> 00:45:22.620\n头痛？\n\n649\n00:45:22.840 --> 00:45:26.420\n我也有头痛\n但我的颈椎治疗师把我治好了\n\n650\n00:45:27.010 --> 00:45:29.290\n我认为我能帮助你，山姆\n\n651\n00:45:31.220 --> 00:45:32.510\n山姆？\n\n652\n00:45:34.600 --> 00:45:36.300\n他知道电话会被追踪\n\n653\n00:45:40.570 --> 00:45:44.020\n山姆，我们要让你知道\n我们没有追踪你的电话\n\n654\n00:45:44.240 --> 00:45:49.150\n追踪过程冗长而且复杂\n短时间的通话也无法追踪\n\n655\n00:45:54.500 --> 00:45:55.990\n山姆？\n\n656\n00:45:57.870 --> 00:46:01.330\n我们没有追踪电话，我保证\n\n657\n00:46:01.880 --> 00:46:03.080\n好吧\n\n658\n00:46:03.300 --> 00:46:06.790\n山姆，你得告诉我你的问题\n\n659\n00:46:07.010 --> 00:46:11.250\n我不想进毒气室\n我有头痛，杀了人就不会头痛\n\n660\n00:46:11.470 --> 00:46:12.800\n他头壳坏去了\n\n661\n00:46:13.010 --> 00:46:15.840\n你想活，对吧？\n我就是你的救星\n\n662\n00:46:16.060 --> 00:46:17.880\n你头痛有多久了？\n\n663\n00:46:18.100 --> 00:46:20.550\n从我杀了那小子开始\n\n664\n00:46:21.520 --> 00:46:23.510\n-我不想受伤害\n-他为什么打来？\n\n665\n00:46:23.730 --> 00:46:25.060\n嘿，等等，哥们\n\n666\n00:46:25.280 --> 00:46:27.270\n-你跟我说话就不会受伤\n\n667\n00:46:27.490 --> 00:46:29.690\n你也不会进毒气室\n\n668\n00:46:29.910 --> 00:46:32.520\n我想他们不至于判你死刑\n\n669\n00:46:32.740 --> 00:46:36.690\n我们可以问问检察官\n你要我这么做吗，山姆？\n\n670\n00:46:36.910 --> 00:46:40.070\n你要我问检察官吗？\n\n671\n00:46:43.750 --> 00:46:45.200\n那是什么，山姆？\n\n672\n00:46:46.460 --> 00:46:48.040\n我没有说话\n\n673\n00:46:48.260 --> 00:46:50.790\n我们听到一声尖叫\n\n674\n00:46:51.430 --> 00:46:54.000\n那是我的头痛\n\n675\n00:46:54.220 --> 00:46:57.880\n听起来你的疼痛很剧烈\n\n676\n00:46:58.100 --> 00:47:01.930\n我头很痛，我病的很严重\n\n677\n00:47:02.810 --> 00:47:03.930\n我要杀光他们\n\n678\n00:47:05.070 --> 00:47:07.230\n-好\n-我要杀死那些孩子\n\n679\n00:47:07.440 --> 00:47:09.520\n太棒了\n\n680\n00:47:11.700 --> 00:47:13.060\n山姆？\n\n681\n00:47:14.660 --> 00:47:17.110\n让我们碰面，就我们两个\n\n682\n00:47:17.910 --> 00:47:18.900\n好吧\n\n683\n00:47:19.120 --> 00:47:21.530\n在中国城的圣犸利教堂如何？\n\n684\n00:47:21.750 --> 00:47:26.870\n不，十点半在戴利市\n圣文森慈善商店门口\n\n685\n00:47:27.090 --> 00:47:29.160\n到时候见\n\n686\n00:47:30.590 --> 00:47:32.540\n好好保重，山姆\n\n687\n00:47:41.020 --> 00:47:42.010\n廉价旧货店\n\n688\n00:47:56.870 --> 00:48:01.820\n天啊，你们这群人可真了解\n私下密会的意思\n\n689\n00:48:02.210 --> 00:48:03.490\n贝利，这里\n\n690\n00:48:05.840 --> 00:48:11.080\n我不想进毒气室，我有头痛\n我杀了人就不会头痛\n\n691\n00:48:11.300 --> 00:48:13.580\n不，那不是他\n\n692\n00:48:13.800 --> 00:48:16.670\n这声音偏高，也比较年轻\n\n693\n00:48:16.890 --> 00:48:19.300\n多谢你来一趟，布莱恩\n\n694\n00:48:20.520 --> 00:48:22.630\n没关系，我自己来\n\n695\n00:48:28.610 --> 00:48:32.810\n他们停止追踪了\n这位没来赴约的神经病\n\n696\n00:48:33.030 --> 00:48:37.360\n奥克兰警局接线生很确定\n跟他说话的男人声音更低沉\n\n697\n00:48:37.580 --> 00:48:41.820\n也更冷静\n搞不好真的是这家伙\n\n698\n00:48:48.000 --> 00:48:50.330\n我要改变收藏奴隶的方法\n\n699\n00:48:50.550 --> 00:48:51.790\n两周半后 加州 旧金山\n\n700\n00:48:52.010 --> 00:48:54.830\n我不会再通知任何人我要犯案\n\n701\n00:48:55.050 --> 00:48:58.090\n命案看起来会像一般抢劫、殴斗\n\n702\n00:48:58.300 --> 00:49:01.010\n假造的意外，等等\n\n703\n00:49:01.220 --> 00:49:04.590\n警方永远逮不到我\n因为我远比那些笨蛋聪明\n\n704\n00:49:04.810 --> 00:49:08.470\n警方所公布的嫌犯素描\n是我犯案时的模样\n\n705\n00:49:08.690 --> 00:49:11.430\n其余时间我则是完全不同面貌\n\n706\n00:49:11.650 --> 00:49:16.480\n我不会告诉你们我杀人时的伪装\n\n707\n00:49:16.700 --> 00:49:19.360\n我也没有像警方说的那样\n\n708\n00:49:19.580 --> 00:49:21.980\n留下任何指纹\n\n709\n00:49:22.200 --> 00:49:25.320\n我都戴透明指尖套\n\n710\n00:49:25.540 --> 00:49:30.080\n你们只会采集到我指尖\n涂上的两层模型黏胶\n\n711\n00:49:30.290 --> 00:49:34.370\n恶整那两个巡警很好玩\n猪头，当时我人就在公园\n\n712\n00:49:34.590 --> 00:49:40.040\n你们多叫了几辆消防车\n掩盖巡逻警车的声音\n\n713\n00:49:40.260 --> 00:49:43.880\n猪头，被人戳破这些糗事\n你们一定超不爽吧？\n\n714\n00:49:44.770 --> 00:49:48.050\n警方要是真以为\n我会向校车下手\n\n715\n00:49:48.270 --> 00:49:52.010\n你们真的是头壳坏了\n\n716\n00:49:53.610 --> 00:49:55.730\n你最好看看这玩意儿\n\n717\n00:49:58.450 --> 00:50:00.610\n一袋硝酸氨肥料\n\n718\n00:50:00.830 --> 00:50:04.900\n一加仑沙拉油\n上面再洒上几袋砂砾\n\n719\n00:50:05.120 --> 00:50:06.570\n-好\n-他说的是炸弹\n\n720\n00:50:06.790 --> 00:50:07.990\n我们得打给军方\n\n721\n00:50:08.210 --> 00:50:10.990\n证实这种土制炸药的可行性\n\n722\n00:50:11.670 --> 00:50:13.290\n又有一组密码\n\n723\n00:50:15.300 --> 00:50:18.000\n-这是什么时候来的？\n-今天早上\n\n724\n00:50:18.220 --> 00:50:20.250\n-你打算刊登吗？\n-罗伯\n\n725\n00:50:22.180 --> 00:50:24.000\n我们应该去喝一杯\n\n726\n00:50:28.270 --> 00:50:29.800\n谢谢\n\n727\n00:50:31.480 --> 00:50:34.770\n谈谈你自己，结婚了吗？\n\n728\n00:50:34.980 --> 00:50:38.100\n离婚了 ，两个小孩\n\n729\n00:50:38.490 --> 00:50:40.270\n都做些什么休闲活动？\n\n730\n00:50:41.740 --> 00:50:43.690\n我很喜欢阅读\n\n731\n00:50:44.240 --> 00:50:46.280\n-我喜欢看书\n-那不是一样吗？\n\n732\n00:50:46.500 --> 00:50:49.030\n干嘛翻我的垃圾？\n\n733\n00:50:52.170 --> 00:50:56.160\n待会儿再说好了。\n你怎么知道他还会再寄密码？\n\n734\n00:50:56.380 --> 00:50:57.460\n我猜的\n\n735\n00:50:58.130 --> 00:51:00.420\n-只是猜的\n-第一组似乎过于简单\n\n736\n00:51:00.630 --> 00:51:02.750\n好吧，再也不能视而不见了\n\n737\n00:51:02.970 --> 00:51:04.550\n告诉我，你到底喝什么东西？\n\n738\n00:51:04.760 --> 00:51:06.590\n蓝色刮胡水调酒\n\n739\n00:51:06.810 --> 00:51:08.800\n如果你试了\n就不会开我的玩笑了\n\n740\n00:51:19.200 --> 00:51:21.350\n是谁破解了密码？\n\n741\n00:51:22.360 --> 00:51:26.360\n一对喜欢解谜的夫妻\n这让我们知道十二宫杀手是什么人？\n\n742\n00:51:27.040 --> 00:51:29.950\n-他不是密码专家\n-没错，这就像小时候上童军课\n\n743\n00:51:30.160 --> 00:51:32.320\n会用的替代编码法\n\n744\n00:51:32.540 --> 00:51:36.120\n-A是1 ，B是2\n-不是每个人都上过童军课\n\n745\n00:51:36.340 --> 00:51:39.160\n这并不难，只要先找到关键字\n\n746\n00:51:39.380 --> 00:51:42.330\n-第一组密码\n-你竟然把密码带在身上\n\n747\n00:51:42.550 --> 00:51:45.000\n-怎样？\n-没怎样\n\n748\n00:51:45.260 --> 00:51:48.210\n英文最常用到哪两个子音组合？\n\n749\n00:51:48.930 --> 00:51:50.260\n-子音？\n-双L\n\n750\n00:51:50.480 --> 00:51:52.260\n-双L\n-哪个字…\n\n751\n00:51:52.480 --> 00:51:55.050\n他至少会用上一次？\n\n752\n00:51:55.270 --> 00:51:56.390\n-杀\n-对，杀(KILL)\n\n753\n00:51:56.610 --> 00:52:00.140\n哈顿夫妻先找相同的两个符号\n找到这里、这里、还有这里\n\n754\n00:52:00.360 --> 00:52:02.440\n前面都有一样的两个符号\n\n755\n00:52:02.660 --> 00:52:06.610\n现在他们找到好几个两个一样符号的\n四个字母的字\n\n756\n00:52:06.830 --> 00:52:09.940\n-他们认为这个字串是KILL\n-有了K和I\n\n757\n00:52:10.160 --> 00:52:11.450\n这就是个关键字\n\n758\n00:52:11.660 --> 00:52:15.120\n他们怎么用这两个符号\n解开整个谜？\n\n759\n00:52:15.330 --> 00:52:18.660\n就像我一样，去图书馆查\n\n760\n00:52:21.380 --> 00:52:22.790\n在这本书里\n\n761\n00:52:22.970 --> 00:52:24.250\n《解谜大王》\n\n762\n00:52:24.510 --> 00:52:27.420\n作者在序中提供简单的替代字\n\n763\n00:52:27.640 --> 00:52:30.510\n他提供的26个替代字中\n就有8个在这张密码里找得到\n\n764\n00:52:30.720 --> 00:52:33.510\n但这些都不是字母\n看起来是中世纪符号\n\n765\n00:52:33.730 --> 00:52:35.850\n我也这么觉得\n\n766\n00:52:36.980 --> 00:52:40.640\n后来我意外发现中世纪密码\n猜猜看它叫什么？\n\n767\n00:52:40.860 --> 00:52:42.560\n十二宫杀手字母\n\n768\n00:52:44.530 --> 00:52:46.190\n天\n\n769\n00:52:47.120 --> 00:52:49.280\n-你想得到什么好处？\n-什么？\n\n770\n00:52:49.490 --> 00:52:53.110\n你有什么企图？\n除了你以外别人都能捞到好处\n\n771\n00:52:55.960 --> 00:52:57.910\n你指的好处是什么？\n\n772\n00:53:00.880 --> 00:53:03.120\n上床睡觉吧\n\n773\n00:53:03.340 --> 00:53:06.330\n待会儿再睡，我得打通电话\n\n774\n00:53:18.520 --> 00:53:20.600\n-喂？\n-比尔？\n\n775\n00:53:20.820 --> 00:53:23.100\n加州并没有太多的地下室\n\n776\n00:53:23.320 --> 00:53:24.770\n以后会派上用场的地下室\n\n777\n00:53:25.240 --> 00:53:26.770\n没错\n\n778\n00:53:26.990 --> 00:53:31.610\n我会打给瓦列霍和那帕市\n请城市规划局调查，去睡吧\n\n779\n00:53:31.830 --> 00:53:33.570\n好吧\n\n780\n00:53:42.550 --> 00:53:45.710\n一个半月后 加州 旧金山\n\n781\n00:53:45.930 --> 00:53:48.330\n亲爱的梅尔文，我是十二宫杀手\n\n782\n00:53:48.970 --> 00:53:50.960\n希望你有个愉快的圣诞节\n\n783\n00:53:51.180 --> 00:53:54.630\n我只想请你帮忙，请你帮助我\n\n784\n00:53:54.850 --> 00:53:58.340\n我无法向其他人求助\n因为我心里的声音不肯\n\n785\n00:53:58.560 --> 00:53:59.550\n谢了\n\n786\n00:53:59.770 --> 00:54:02.970\n我发现我就快要失去控制\n\n787\n00:54:03.190 --> 00:54:06.730\n我担心我一旦失去控制\n就会有第九个\n\n788\n00:54:06.950 --> 00:54:08.560\n或第十个受害者出现\n\n789\n00:54:08.780 --> 00:54:10.900\n梅尔文，他在向你求救\n\n790\n00:54:11.120 --> 00:54:15.820\n一点也没错\n警探，这封信直接寄到我家\n\n791\n00:54:16.040 --> 00:54:18.950\n与其说是声明不如说是求救信\n\n792\n00:54:19.170 --> 00:54:21.370\n所以你才通知《旧金山纪事报》\n\n793\n00:54:21.590 --> 00:54:24.450\n民众有权利知道事实，来一杯？\n\n794\n00:54:24.670 --> 00:54:27.620\n-你几时收到信？\n-上礼拜中旬\n\n795\n00:54:27.840 --> 00:54:29.920\n我认为他写下这封信…\n\n796\n00:54:30.140 --> 00:54:32.750\n是因为他无法在会展上或这里找到我\n\n797\n00:54:32.970 --> 00:54:35.340\n-他有试着打电话到你家？\n-好几次，我都不在\n\n798\n00:54:35.560 --> 00:54:37.680\n我出去了，但他和女管家说过话\n\n799\n00:54:37.890 --> 00:54:40.010\n-没留下号码\n-他一向都很狡猾\n\n800\n00:54:40.230 --> 00:54:42.350\n-介意我跟你管家谈谈吗？\n-不介意\n\n801\n00:54:42.560 --> 00:54:44.890\n但是这封信比较重要\n\n802\n00:54:45.110 --> 00:54:46.980\n-我马上回来\n-好\n\n803\n00:54:47.190 --> 00:54:49.940\n-她在这里\n-陶希警探\n\n804\n00:54:50.160 --> 00:54:53.480\n我相信这封信\n是通往他灵魂的窗口\n\n805\n00:54:53.700 --> 00:54:55.400\n他内心有杀戮的冲动\n\n806\n00:54:55.620 --> 00:54:59.280\n他想忽视却无法抵抗\n这是他的本性\n\n807\n00:54:59.500 --> 00:55:02.280\n也许。也许他只是想出风头\n\n808\n00:55:05.090 --> 00:55:08.960\n一个半月后 132号公路\n加州 莫德斯托附近\n\n809\n00:55:09.170 --> 00:55:10.750\n1970年3月22日\n\n810\n00:55:46.000 --> 00:55:51.830\n我不是故意吓你\n你的车子右轮胎松了\n\n811\n00:55:52.050 --> 00:55:53.670\n-真的吗？\n-你要的话\n\n812\n00:55:53.890 --> 00:55:56.250\n我可以帮你锁紧\n\n813\n00:55:58.930 --> 00:56:02.930\n-你不介意的话\n-还是小心一点比较好\n\n814\n00:56:37.140 --> 00:56:39.380\n-搞定了\n-谢谢\n\n815\n00:56:39.600 --> 00:56:42.260\n不客气，祝你愉快\n\n816\n00:56:46.940 --> 00:56:48.510\n没事\n\n817\n00:57:42.450 --> 00:57:43.940\n你没事吗？\n\n818\n00:57:45.660 --> 00:57:47.910\n没事，我们没事\n\n819\n00:57:49.000 --> 00:57:53.370\n一定比我想像的更严重\n我可以载你到加油站修车\n\n820\n00:57:56.760 --> 00:57:58.080\n好啊\n\n821\n00:58:04.270 --> 00:58:06.590\n没关系，来吧\n\n822\n00:58:13.900 --> 00:58:17.060\n我不知道你有小宝宝\n\n823\n00:58:17.740 --> 00:58:19.730\n可以吗？\n\n824\n00:58:20.780 --> 00:58:22.820\n人越多越好\n\n825\n00:58:32.420 --> 00:58:35.120\n你不该抽烟，这是坏习惯\n\n826\n00:58:41.510 --> 00:58:43.920\n我们错过了一间加油站\n\n827\n00:58:44.140 --> 00:58:46.090\n他们打烊了\n\n828\n00:58:50.350 --> 00:58:53.430\n你常在晚上四处帮助别人吗？\n\n829\n00:58:53.650 --> 00:58:56.770\n等我搞定，他们就不太需要帮忙\n\n830\n00:58:59.990 --> 00:59:01.400\n没事的\n\n831\n00:59:01.620 --> 00:59:03.770\n在我杀你之前\n\n832\n00:59:03.990 --> 00:59:06.570\n我得先把你的小宝宝丢出去\n\n833\n00:59:21.720 --> 00:59:25.250\n不要，救命，不要！\n\n834\n00:59:30.390 --> 00:59:31.840\n她人在路边\n\n835\n00:59:32.060 --> 00:59:33.720\n-她把我拦了下来\n-发生什么事？\n\n836\n00:59:33.940 --> 00:59:36.810\n她说她跳车\n我看到她的时候她就是这样\n\n837\n00:59:37.030 --> 00:59:39.980\n-怎么了？\n-求求你，他说\n\n838\n00:59:40.200 --> 00:59:42.230\n-一切都没事了\n-他想要杀我\n\n839\n00:59:42.990 --> 00:59:45.570\n-我的小宝宝！\n-你的小宝宝呢？\n\n840\n00:59:45.780 --> 00:59:47.900\n我停车的时候没看到\n\n841\n00:59:48.120 --> 00:59:49.740\n你的小宝宝呢？\n\n842\n00:59:56.170 --> 00:59:57.790\n老天爷\n\n843\n01:00:05.220 --> 01:00:08.170\n-你藏起来了？\n-以防他再回来\n\n844\n01:00:16.110 --> 01:00:17.720\n《莫德斯托蜜蜂报》\n\n845\n01:00:18.610 --> 01:00:21.140\n女人声称被十二宫杀手绑架\n\n846\n01:00:22.530 --> 01:00:23.850\n我是十二宫杀手\n\n847\n01:00:24.070 --> 01:00:25.060\n三十天后 加州 旧金山\n\n848\n01:00:25.280 --> 01:00:27.730\n对了 ，上个密码破解了吗？\n\n849\n01:00:27.950 --> 01:00:30.860\n我有点好奇我的人头现在值多少\n\n850\n01:00:31.080 --> 01:00:34.320\n希望你没以为我用炸弹\n\n851\n01:00:35.750 --> 01:00:37.450\n在警局炸死那个小气巡警\n\n852\n01:00:37.670 --> 01:00:40.200\n虽然我说过要炸死那些学童\n\n853\n01:00:40.460 --> 01:00:41.750\n我是十二宫杀手\n\n854\n01:00:41.970 --> 01:00:42.960\n八天后 加州 旧金山\n\n855\n01:00:43.180 --> 01:00:45.710\n我很想在街上看到大家\n别上十二宫杀手胸章\n\n856\n01:00:45.930 --> 01:00:47.590\n别人都做了胸章\n\n857\n01:00:47.800 --> 01:00:50.920\n像是和平、黑色力量\n律师吃屎之类的胸章\n\n858\n01:00:51.140 --> 01:00:54.010\n我会很高兴看到每个人\n都别上一枚我的胸章\n\n859\n01:00:54.230 --> 01:00:55.220\n两个月后 加州 旧金山\n\n860\n01:00:55.440 --> 01:00:57.850\n-别把标语写得太贱“\n-”我是十二宫杀手\n\n861\n01:00:58.020 --> 01:00:59.430\n十二宫杀手表示他杀了旧金山警察\n\n862\n01:00:59.570 --> 01:01:03.730\n我用38口径旧金山警用手枪\n射杀一名驾驶\n\n863\n01:01:03.950 --> 01:01:07.060\n地图加密码提供炸弹的地点\n\n864\n01:01:07.280 --> 01:01:10.570\n引爆时间是下一个秋天\n\n865\n01:01:12.950 --> 01:01:14.320\n我是十二宫杀手\n\n866\n01:01:14.540 --> 01:01:18.160\n你们不别十二宫杀手胸章让我很不爽\n\n867\n01:01:18.380 --> 01:01:20.790\n我列出一张名单\n从那女人和她小孩开始\n\n868\n01:01:20.960 --> 01:01:22.250\n四周后 加州 旧金山\n\n869\n01:01:22.380 --> 01:01:24.120\n几个月前，在我烧毁她车子以前\n\n870\n01:01:24.340 --> 01:01:26.790\n我们一同兜风了几个小时\n\n871\n01:01:27.010 --> 01:01:29.040\n我们真的不再刊登这些信件？\n\n872\n01:01:29.260 --> 01:01:33.420\n新策略，警方要我们暂时不理他\n看他会有什么反应\n\n873\n01:01:33.640 --> 01:01:37.590\n三个月来四封信\n这是第一封提到凯萨琳琼斯的\n\n874\n01:01:37.810 --> 01:01:42.470\n-超奇怪的\n-因为他都在讲屁话\n\n875\n01:01:43.530 --> 01:01:44.980\n什么意思？\n\n876\n01:01:46.280 --> 01:01:47.600\n你不知道吗？\n\n877\n01:01:49.240 --> 01:01:53.990\n欢迎，放下你身上的东西\n走到第五排左转\n\n878\n01:01:54.200 --> 01:01:56.530\n找三月份的《莫德斯托蜜蜂报》\n\n879\n01:01:56.750 --> 01:01:59.530\n我会站着试着不吐出来\n\n880\n01:01:59.840 --> 01:02:01.830\n左转\n\n881\n01:02:02.920 --> 01:02:05.250\n-我要找什么？\n-凯萨琳琼斯\n\n882\n01:02:05.470 --> 01:02:10.130\n也许你要找旧的《纪事报》\n算了 ，我自己来找\n\n883\n01:02:10.760 --> 01:02:13.460\n再读这封信，关于凯萨琳\n\n884\n01:02:13.680 --> 01:02:15.300\n告诉我他说的事实\n\n885\n01:02:15.770 --> 01:02:18.260\n-女人与小孩被他绑架\n-没错\n\n886\n01:02:20.810 --> 01:02:23.270\n-车子着火\n-好，那…\n\n887\n01:02:24.610 --> 01:02:26.640\n再看《蜜蜂报》的报导\n\n888\n01:02:27.740 --> 01:02:29.400\n看到了吗？\n\n889\n01:02:29.610 --> 01:02:31.520\n信上写的都是发生过的事\n\n890\n01:02:31.740 --> 01:02:33.360\n他以前也玩过这把戏\n\n891\n01:02:34.790 --> 01:02:36.950\n员警赖理查在车上惨遭射杀\n\n892\n01:02:37.160 --> 01:02:39.410\n十二宫杀手也说他杀了一名驾驶\n\n893\n01:02:39.620 --> 01:02:43.990\n几天后这则新闻出来，嫌犯早就被逮捕\n\n894\n01:02:44.210 --> 01:02:46.000\n十二宫杀手根本没犯案\n\n895\n01:02:46.210 --> 01:02:49.330\n他抢了这些人的功劳\n因为他想当媒体宠儿\n\n896\n01:02:49.550 --> 01:02:51.500\n-他甚至盗用别人的符号\n-什么？\n\n897\n01:02:51.720 --> 01:02:55.340\n我给你看样东西，别告诉别人\n\n898\n01:02:55.560 --> 01:02:59.510\n我能告诉谁？\n对哦，一点也没错\n\n899\n01:03:06.400 --> 01:03:08.350\n我们收到十二宫杀手的信之前\n\n900\n01:03:08.570 --> 01:03:10.520\n符号与名字只同时出现在这里\n\n901\n01:03:10.740 --> 01:03:14.020\n-这家伙盗用手表上的商标\n-他杀了十三人\n\n902\n01:03:14.240 --> 01:03:17.190\n他自称杀了十三人，谁能证明？\n\n903\n01:03:17.410 --> 01:03:20.700\n瓦列霍三人、贝瑞莎一人\n以及计程车司机，就这样\n\n904\n01:03:22.670 --> 01:03:24.990\n小葛，你好像很失望\n\n905\n01:03:26.000 --> 01:03:28.580\n局长撤走调查此案的人员\n\n906\n01:03:29.220 --> 01:03:32.630\n-一切恢复正常\n-他一定会再出声\n\n907\n01:03:32.840 --> 01:03:37.340\n-四个月来一声也没吭\n-起先他不肯住嘴，现在\n\n908\n01:03:37.560 --> 01:03:40.300\n也许他被逼得躲起来了\n\n909\n01:03:40.560 --> 01:03:42.220\n也许他落跑了\n\n910\n01:03:43.060 --> 01:03:46.010\n赫特街582号发生案件\n有一名男子\n\n911\n01:03:46.230 --> 01:03:48.890\n-比尔，生日快乐\n-谢了\n\n912\n01:03:50.530 --> 01:03:56.270\n1970年10月11日 加州 旧金山\n华盛顿街与樱桃街转角\n\n913\n01:03:58.620 --> 01:04:01.110\n你介意别人老是叫你矮子吗？\n\n914\n01:04:01.330 --> 01:04:03.660\n你介意别人老是叫你智障吗？\n\n915\n01:04:03.880 --> 01:04:06.620\n-没人这样叫我啊\n-是啊\n\n916\n01:04:06.840 --> 01:04:09.580\n我当选后将以州长拥有的权限…\n\n917\n01:04:09.800 --> 01:04:11.410\n两周半后 加州 旧金山\n\n918\n01:04:11.630 --> 01:04:14.580\n把害黛琳费伦的凶手绳之以法\n\n919\n01:04:14.800 --> 01:04:19.510\n我相信这起命案有些线索被忽略\n\n920\n01:04:19.720 --> 01:04:21.680\n-我相信这是一起预谋谋杀案\n-那女人是谁？\n\n921\n01:04:21.890 --> 01:04:24.590\n芙伦丝道格拉斯，瓦列霍市长\n她要出来竞选州长\n\n922\n01:04:24.810 --> 01:04:27.430\n我相信警方不是没钱、没时间\n\n923\n01:04:27.650 --> 01:04:29.140\n就是懒得去挖掘真相\n\n924\n01:04:29.360 --> 01:04:33.230\n你竟然敢批评警方\n好样的，小芙\n\n925\n01:04:33.450 --> 01:04:36.610\n有人替我取过外号吗？\n\n926\n01:04:36.910 --> 01:04:40.150\n-你是说智障吗？\n-对\n\n927\n01:04:41.000 --> 01:04:42.400\n没有\n\n928\n01:04:46.630 --> 01:04:51.330\n可恶，我靠，他妈的\n\n929\n01:04:54.680 --> 01:04:58.380\n告诉我那不是一块沾血衬衫\n\n930\n01:04:58.600 --> 01:05:00.960\n我知道你们打心里想知道我名字\n\n931\n01:05:01.180 --> 01:05:04.630\n我就直接告诉你们吧\n不过何必扫兴呢？\n\n932\n01:05:04.850 --> 01:05:06.180\n万圣节快乐\n\n933\n01:05:07.860 --> 01:05:11.640\n保罗，你在至少一篇文章中\n\n934\n01:05:11.860 --> 01:05:16.650\n-说他有潜在性同性恋倾向\n-大卫，我需要一把枪\n\n935\n01:05:18.200 --> 01:05:19.820\n一把枪？\n\n936\n01:05:24.210 --> 01:05:25.820\n专栏作家贺伯肯恩提到你\n\n937\n01:05:26.040 --> 01:05:29.910\n保罗艾瑞的深入调查\n换来十二宫杀手的一句警告\n\n938\n01:05:30.130 --> 01:05:31.410\n“你死定了”\n\n939\n01:05:31.630 --> 01:05:34.920\n结果记者都纷纷别上写着\n\n940\n01:05:35.130 --> 01:05:37.080\n“我不是保罗艾瑞” 的胸章\n\n941\n01:05:37.300 --> 01:05:39.420\n你应该去卖胸章，肯定赚翻天\n\n942\n01:05:39.640 --> 01:05:42.590\n从报社刊登警告信的那天起\n我的确收获不少\n\n943\n01:05:42.810 --> 01:05:46.640\n线索来自四面八方\n有个家伙住在河滨市\n\n944\n01:05:46.850 --> 01:05:48.970\n今晚我会去找他，一起来吗？\n\n945\n01:05:49.190 --> 01:05:52.350\n不了 ，我有个约会\n\n946\n01:05:52.570 --> 01:05:54.890\n-真的假的？\n-河滨市这家伙是谁？\n\n947\n01:05:55.110 --> 01:05:59.020\n他想要匿名，我想要声名狼藉\n\n948\n01:05:59.240 --> 01:06:02.150\n咱们应该会很合得来\n\n949\n01:06:09.790 --> 01:06:12.040\n晚安，我来找梅乐妮\n\n950\n01:06:12.250 --> 01:06:16.210\n-自己一个人坐那边的女生\n-谢谢\n\n951\n01:06:22.140 --> 01:06:23.420\n你应该是梅乐妮\n\n952\n01:06:23.640 --> 01:06:25.420\n-那你就是罗伯啰！\n-是的\n\n953\n01:06:25.640 --> 01:06:28.550\n葛列妮丝说了很多关于你的事\n\n954\n01:06:28.770 --> 01:06:30.680\n-你在喝葡萄酒，很好\n-是啊\n\n955\n01:06:30.900 --> 01:06:33.390\n我迟到多久了？\n\n956\n01:06:34.070 --> 01:06:36.940\n几分钟而已，我也是刚到\n\n957\n01:06:37.150 --> 01:06:39.730\n路上塞车，我刚从靶场过来\n\n958\n01:06:39.950 --> 01:06:42.070\n葛列妮丝说你是个漫画家\n\n959\n01:06:42.280 --> 01:06:43.610\n喔，是啊\n\n960\n01:06:43.830 --> 01:06:46.280\n-你去靶场做什么？\n-看书\n\n961\n01:06:46.500 --> 01:06:50.530\n多拿一些，你需要多点餐巾纸\n\n962\n01:06:51.290 --> 01:06:53.200\n你和葛列妮丝是同事？\n\n963\n01:06:53.420 --> 01:06:55.620\n-其实我是替她工作\n-替她工作？\n\n964\n01:06:55.840 --> 01:06:57.460\n喔，这样\n\n965\n01:06:59.090 --> 01:07:01.040\n我小孩很怕葛列妮丝\n\n966\n01:07:01.260 --> 01:07:02.340\n我也是\n\n967\n01:07:05.890 --> 01:07:08.840\n-你刚才在靶场\n-我们在调查\n\n968\n01:07:09.060 --> 01:07:10.550\n-你知道十二宫杀手？\n-知道\n\n969\n01:07:10.770 --> 01:07:12.890\n我和…\n你知道保罗艾瑞是谁吗？\n\n970\n01:07:13.110 --> 01:07:15.890\n-有点耳熟\n-他就是遭十二宫杀手恐吓的记者\n\n971\n01:07:16.110 --> 01:07:19.770\n-对，我在电视上有看到\n-其实我跟他是同事\n\n972\n01:07:19.990 --> 01:07:24.270\n他今晚要开车到河滨市\n找一位匿名密报者\n\n973\n01:07:25.040 --> 01:07:26.440\n河滨市到底在哪里？\n\n974\n01:07:27.200 --> 01:07:28.570\n洛杉矶附近\n\n975\n01:07:29.330 --> 01:07:32.570\n我猜保罗不知道路程那么远\n\n976\n01:07:34.460 --> 01:07:36.370\n听起来有些危险\n\n977\n01:07:37.670 --> 01:07:40.620\n是啊，怎么说？\n\n978\n01:07:40.840 --> 01:07:43.040\n你不是说对方是个匿名密报者吗？\n\n979\n01:07:43.260 --> 01:07:44.540\n是啊\n\n980\n01:07:44.760 --> 01:07:48.550\n可能是个埋伏，搞不好是十二宫杀手\n\n981\n01:07:49.850 --> 01:07:52.140\n你不觉得这么做有点傻吗？\n\n982\n01:07:52.350 --> 01:07:55.010\n是啊，不过保罗有把枪\n\n983\n01:07:58.690 --> 01:08:02.060\n你知道这里有什么好吃的？\n\n984\n01:08:03.280 --> 01:08:05.150\n我从来没来过这里\n\n985\n01:08:07.410 --> 01:08:09.860\n意大利面？\n\n986\n01:08:11.080 --> 01:08:13.160\n可以点餐了吗？\n\n987\n01:08:14.380 --> 01:08:16.990\n我要点红酱管面\n你能帮我改用白酱煮吗？\n\n988\n01:08:17.210 --> 01:08:18.790\n当然可以\n\n989\n01:08:23.720 --> 01:08:25.380\n再给我们几分钟？\n\n990\n01:08:27.470 --> 01:08:29.010\n你有零钱吗？\n\n991\n01:08:29.220 --> 01:08:31.630\n等等，等一下\n\n992\n01:08:31.850 --> 01:08:34.720\n-没有，我只有一分钱\n-你要打电话吗？\n\n993\n01:08:34.940 --> 01:08:38.720\n刚刚你提到十二宫杀手\n\n994\n01:08:38.940 --> 01:08:42.190\n你说很危险，我在想\n真的很危险，而且…\n\n995\n01:08:42.400 --> 01:08:43.390\n-很蠢？\n-对\n\n996\n01:08:43.610 --> 01:08:48.690\n所以我应该打给他太太\n问问她有没有任何消息\n\n997\n01:08:50.750 --> 01:08:52.240\n我有一些零钱\n\n998\n01:09:11.220 --> 01:09:14.430\n好了 ，她说有消息会再打给我\n\n999\n01:09:14.640 --> 01:09:16.930\n-很好\n-对\n\n1000\n01:09:17.270 --> 01:09:21.720\n梅乐妮，我应该回家等电话\n\n1001\n01:09:24.280 --> 01:09:26.980\n你该不会想骗我跟你回家吧？\n\n1002\n01:09:28.450 --> 01:09:29.940\n什么？不是！\n\n1003\n01:09:32.250 --> 01:09:34.400\n食物就打包好了\n\n1004\n01:09:36.040 --> 01:09:37.320\n喂！\n\n1005\n01:09:53.180 --> 01:09:56.430\n嗨，我约了人在这里见面\n\n1006\n01:10:14.330 --> 01:10:15.950\n有消息吗？\n\n1007\n01:10:19.080 --> 01:10:21.410\n-你不用留下来陪我\n-别开玩笑了\n\n1008\n01:10:22.380 --> 01:10:25.460\n这是我最棒的一次约会\n\n1009\n01:10:29.720 --> 01:10:30.710\n-保罗？\n-罗伯？\n\n1010\n01:10:30.930 --> 01:10:32.380\n-是啊\n-你坐着吗？\n\n1011\n01:10:32.600 --> 01:10:35.550\n-是啊\n-你绝对不会相信\n\n1012\n01:10:35.770 --> 01:10:37.430\n-大卫！\n-离奇的转折\n\n1013\n01:10:37.640 --> 01:10:39.340\n猎物变成猎人\n\n1014\n01:10:39.560 --> 01:10:43.220\n《旧金山纪事报》记者\n也就是十二宫杀手猎杀目标保罗艾瑞\n\n1015\n01:10:43.440 --> 01:10:45.560\n声称找到新的线索\n\n1016\n01:10:45.780 --> 01:10:49.400\n针对河滨市唯一未破的谋杀案\n\n1017\n01:10:49.610 --> 01:10:52.980\n艾瑞深信\n1966年南加州的谋杀案\n\n1018\n01:10:53.200 --> 01:10:56.740\n很可能是十二宫杀手的第一名受害人\n\n1019\n01:10:56.960 --> 01:10:58.240\n-什么？\n-他没告诉你吗？\n\n1020\n01:10:58.460 --> 01:11:00.910\n-等等\n-我把河滨市凶手寄给媒体的信件\n\n1021\n01:11:01.130 --> 01:11:04.160\n亲自拿给鉴识专家进行比对\n\n1022\n01:11:04.380 --> 01:11:06.250\n专家怎么说？\n\n1023\n01:11:06.460 --> 01:11:08.120\n就像我早就知道的答案一样\n\n1024\n01:11:08.340 --> 01:11:10.500\n两封信笔迹相同\n\n1025\n01:11:10.720 --> 01:11:12.710\n他怎么拿到河滨市的证物？\n\n1026\n01:11:12.930 --> 01:11:15.170\n他把证物带到谢吾去了，没告诉我们\n\n1027\n01:11:15.390 --> 01:11:19.050\n-你知道我们有多糗吗？\n-我们怎么确定这条线索是真的\n\n1028\n01:11:19.270 --> 01:11:23.680\n当然是真的，我怎么知道？\n因为是从电视上看到的\n\n1029\n01:11:25.190 --> 01:11:28.520\n1970年11月18日\n\n1030\n01:11:30.070 --> 01:11:32.310\n大卫？嗨\n\n1031\n01:11:32.530 --> 01:11:34.940\n你认识倪梅尔， 司法部调查员\n\n1032\n01:11:35.160 --> 01:11:36.440\n幸会，梅尔\n\n1033\n01:11:36.660 --> 01:11:39.900\n谁能告诉我为何我得透过媒体\n\n1034\n01:11:40.120 --> 01:11:42.070\n才知道这案子有新的线索？\n\n1035\n01:11:42.290 --> 01:11:43.830\n-我们被整了\n-大卫，少来这套\n\n1036\n01:11:44.040 --> 01:11:46.410\n你也常上报\n民众会提供线索\n\n1037\n01:11:46.630 --> 01:11:49.620\n我从来没有公开讨论案情好吧，肯？\n\n1038\n01:11:49.840 --> 01:11:53.170\n大卫吗？\n嘿，嗨！保罗艾瑞\n\n1039\n01:11:53.390 --> 01:11:57.340\n-我可以搭你的便车去？\n-保罗，不行\n\n1040\n01:11:57.560 --> 01:12:01.050\n去同一个地方还要我搭计程车\n\n1041\n01:12:01.270 --> 01:12:03.550\n感谢您搭乘太平洋西南航空\n\n1042\n01:12:03.770 --> 01:12:06.060\n好吧，好吧\n\n1043\n01:12:06.270 --> 01:12:08.730\n请注意，吸烟区在最后六排\n\n1044\n01:12:08.940 --> 01:12:11.020\n祝您旅途愉快\n\n1045\n01:12:14.120 --> 01:12:16.730\n谢利·乔·贝茨\n加入了河滨社区学院\n\n1046\n01:12:16.950 --> 01:12:20.070\n1966年10月30日那晚\n她在图书馆念书\n\n1047\n01:12:20.290 --> 01:12:21.570\n两小时后 加州 河滨市\n\n1048\n01:12:21.790 --> 01:12:24.950\n九点钟关门后她与一名男性离开\n\n1049\n01:12:25.170 --> 01:12:29.080\n隔天她被发现在停车场\n被刺杀身亡\n\n1050\n01:12:29.300 --> 01:12:32.580\n11月29日 ，案发一个月后\n\n1051\n01:12:32.800 --> 01:12:35.250\n《河滨市企业报》收到打字的自白书\n\n1052\n01:12:35.470 --> 01:12:37.090\n报社刊登这封自白书\n\n1053\n01:12:38.890 --> 01:12:41.670\n我没有病，我只是疯了\n但游戏不会终止\n\n1054\n01:12:41.890 --> 01:12:43.930\n这封信应该公开给大众阅读\n\n1055\n01:12:44.150 --> 01:12:47.310\n他要公开，他说这是游戏\n这可能就是十二宫杀手\n\n1056\n01:12:47.520 --> 01:12:50.480\n半年后，警方、父亲和报社\n\n1057\n01:12:50.690 --> 01:12:52.600\n都收到了这些信\n\n1058\n01:12:57.280 --> 01:12:59.280\n双倍邮资，十二宫杀手的习惯\n\n1059\n01:12:59.540 --> 01:13:00.530\n贝茨必须死\n\n1060\n01:13:00.700 --> 01:13:03.530\n这是莫瑞尔用来比对的信？\n\n1061\n01:13:03.750 --> 01:13:05.410\n除了这些还有这块桌面，唐\n\n1062\n01:13:05.630 --> 01:13:10.370\n几个月后工友在校园的仓库\n发现这块桌面\n\n1063\n01:13:15.090 --> 01:13:16.460\n切、清洁、如果血液鲜红/清洁\n\n1064\n01:13:16.680 --> 01:13:19.170\n血液泼洒在她的新洋装\n\n1065\n01:13:19.350 --> 01:13:22.670\n莫瑞尔用桌面比对字迹？\n\n1066\n01:13:23.640 --> 01:13:25.640\n谁会刻上自己的笔迹？\n\n1067\n01:13:25.850 --> 01:13:29.350\n老实说，我看不出笔迹很像\n\n1068\n01:13:29.570 --> 01:13:32.350\n保罗艾瑞怎么拿到信件的拷贝？\n\n1069\n01:13:32.570 --> 01:13:35.560\n是我给他的\n前几天打电话聊了一个钟头\n\n1070\n01:13:35.780 --> 01:13:38.940\n-我告诉他你会来\n-你跟他说我们要碰面？\n\n1071\n01:13:39.160 --> 01:13:41.530\n对，我也说这不是十二宫杀手\n\n1072\n01:13:41.740 --> 01:13:44.610\n等等，你不觉得这是十二宫杀手？\n\n1073\n01:13:44.830 --> 01:13:46.280\n我们另外锁定一名嫌犯\n\n1074\n01:13:46.500 --> 01:13:49.330\n虽然没有足够的证据\n不过我很确定凶手就是他\n\n1075\n01:13:49.540 --> 01:13:52.370\n既然你认为不是十二宫杀手\n那干嘛把证物交给艾瑞？\n\n1076\n01:13:52.590 --> 01:13:55.160\n-我只是想合作\n-你合作的方式是\n\n1077\n01:13:55.380 --> 01:13:57.170\n把证物交给记者？\n\n1078\n01:13:57.390 --> 01:14:00.130\n我不懂笔迹，但莫瑞尔很确定\n\n1079\n01:14:00.350 --> 01:14:03.800\n就假设你的嫌犯杀了贝茨\n他打了一封自白书\n\n1080\n01:14:04.020 --> 01:14:07.220\n十二宫杀手在报纸上看到\n然后再写信抢功劳\n\n1081\n01:14:07.440 --> 01:14:11.430\n-他干过这种事\n-现在你有我们所有的证据\n\n1082\n01:14:11.650 --> 01:14:14.930\n不过我看你们是白跑一趟\n\n1083\n01:14:15.150 --> 01:14:17.190\n完了 ，大家，真的完了\n\n1084\n01:14:17.410 --> 01:14:19.980\n不管怎么说，可能还是十二宫杀手\n\n1085\n01:14:20.200 --> 01:14:23.110\n问题是全加州都这么想吧\n\n1086\n01:14:23.330 --> 01:14:26.360\n跟你的公关说吧\n\n1087\n01:14:29.250 --> 01:14:31.370\n我不是来惹麻烦的\n\n1088\n01:14:31.590 --> 01:14:34.410\n我懒得理你，保罗\n只是尽我的职务\n\n1089\n01:14:34.630 --> 01:14:37.290\n是吗？你害我办不了案\n\n1090\n01:14:37.510 --> 01:14:41.170\n光处理这些线索就够头痛\n现在你又吓坏全加州\n\n1091\n01:14:41.390 --> 01:14:44.590\n那帕、瓦列霍、司法部\n都怀疑我的能力\n\n1092\n01:14:44.810 --> 01:14:47.380\n河滨市则认为我白跑一趟\n\n1093\n01:14:47.600 --> 01:14:49.720\n贝茨是我给你的线索\n\n1094\n01:14:49.940 --> 01:14:51.970\n你们俩根本查不出来\n\n1095\n01:14:52.190 --> 01:14:54.220\n他可能不是十二宫杀手，你在乎吗？\n\n1096\n01:14:54.440 --> 01:14:57.770\n你可能害河滨市无法起诉嫌犯\n\n1097\n01:14:57.990 --> 01:15:00.610\n我费尽工夫引蛇出洞\n\n1098\n01:15:00.820 --> 01:15:03.520\n-我们在同一阵线耶\n-谁跟你同一阵线？\n\n1099\n01:15:03.740 --> 01:15:05.900\n-我没兴趣增加报纸发行量\n-天\n\n1100\n01:15:06.120 --> 01:15:07.860\n他写信给我，威胁我的性命\n\n1101\n01:15:08.080 --> 01:15:11.950\n神探，你查了一年半还抓不到人\n\n1102\n01:15:15.920 --> 01:15:18.080\n-去你的\n-非常乐意接受\n\n1103\n01:15:18.300 --> 01:15:20.250\n你应该先告知我的，保罗\n\n1104\n01:15:25.850 --> 01:15:27.470\n谢谢\n\n1105\n01:15:30.850 --> 01:15:35.810\n十二宫杀手命案获得新证物\n与河滨市命案有关\n\n1106\n01:15:40.360 --> 01:15:41.940\n-你看到吗？\n-看到了\n\n1107\n01:15:42.160 --> 01:15:44.940\n全加州的疯子都来了\n\n1108\n01:15:45.830 --> 01:15:48.650\n-我就是十二宫杀手\n-你是怎么杀害被害人的？\n\n1109\n01:15:48.870 --> 01:15:51.700\n用枪，不，用铁锤\n\n1110\n01:15:51.920 --> 01:15:54.780\n我只能说他仍在政府机构上班\n\n1111\n01:15:55.000 --> 01:15:57.790\n-谁准许你告诉我这些？\n-我只能说这么多\n\n1112\n01:15:58.010 --> 01:16:00.040\n只有安德烈\n\n1113\n01:16:00.260 --> 01:16:02.500\n会切下被害人的手臂\n\n1114\n01:16:02.720 --> 01:16:04.920\n十二宫杀手没有切断任何人的手臂\n\n1115\n01:16:05.140 --> 01:16:06.800\n-你确定吗？\n-是的\n\n1116\n01:16:07.010 --> 01:16:09.550\n我跟崔维斯一起工作快十年\n\n1117\n01:16:09.770 --> 01:16:13.390\n命案是从他的脚被辗断后开始的\n\n1118\n01:16:13.600 --> 01:16:14.720\n这是巧合吗？\n\n1119\n01:16:14.940 --> 01:16:17.310\n-我不知道\n-你是警察耶，想也知道\n\n1120\n01:16:21.820 --> 01:16:25.060\n你有想过凶手或许是保罗艾瑞么？\n\n1121\n01:16:25.280 --> 01:16:26.440\n常常想\n\n1122\n01:16:26.950 --> 01:16:28.730\n当时他在喝啤酒\n\n1123\n01:16:28.950 --> 01:16:32.070\n然后聊到猎杀人类\n就像那本书一样\n\n1124\n01:16:32.290 --> 01:16:36.240\n在枪管绑一支手电筒\n就能在黑暗中行凶\n\n1125\n01:16:36.460 --> 01:16:38.200\n-他这么说吗？\n-是啊\n\n1126\n01:16:38.420 --> 01:16:39.410\n八个月后 加州 托伦斯 1971年7月26日\n\n1127\n01:16:39.630 --> 01:16:41.580\n对啊，所以我就问他\n“你打算如何脱罪？”\n\n1128\n01:16:41.800 --> 01:16:45.500\n然后他说“很简单\n因为我没有杀人动机”\n\n1129\n01:16:45.720 --> 01:16:49.510\n他又说他会写信给警方\n自称十二宫杀手恶整警方\n\n1130\n01:16:49.720 --> 01:16:53.550\n-李喜欢恶整别人\n-你确定他有说“十二宫杀手” ？\n\n1131\n01:16:53.770 --> 01:16:57.350\n对，我跟他说这称号很蠢\n\n1132\n01:16:57.570 --> 01:17:00.350\n他生气的说“我不在乎你怎么想”\n\n1133\n01:17:00.570 --> 01:17:03.690\n我想了很久，我要用这称号\n\n1134\n01:17:03.900 --> 01:17:07.060\n你觉得他想了很久吗？\n\n1135\n01:17:07.280 --> 01:17:10.530\n他丢掉学校的工作很不爽\n\n1136\n01:17:10.750 --> 01:17:13.650\n他说要射破校车的轮胎\n\n1137\n01:17:13.870 --> 01:17:16.120\n对那些 “可爱的小孩” 下手\n\n1138\n01:17:16.330 --> 01:17:19.950\n-他真的说了这些话？\n-就是这些话才让我记忆深刻的\n\n1139\n01:17:20.170 --> 01:17:24.670\n后来我跟老婆说我不想再见到他了\n我就没再见过他\n\n1140\n01:17:24.880 --> 01:17:27.000\n还有一件事，李喜欢潜水\n\n1141\n01:17:27.470 --> 01:17:29.550\n他去过那座湖好几次\n\n1142\n01:17:29.760 --> 01:17:31.920\n瑞莎湖，你跟他去过吗？\n\n1143\n01:17:32.140 --> 01:17:35.680\n几次吧。我们也到附近的布达溪钓鱼\n\n1144\n01:17:35.900 --> 01:17:39.970\n-告诉他你几时想到是他的\n-大约是一年前,在报上…\n\n1145\n01:17:40.190 --> 01:17:42.520\n开始报导十二宫杀手\n\n1146\n01:17:42.740 --> 01:17:45.350\n我就回想起来了\n我试着打给地方警察\n\n1147\n01:17:45.570 --> 01:17:48.520\n-他们不理他，以为他疯了\n-你确定\n\n1148\n01:17:48.740 --> 01:17:51.030\n有关十二宫杀手的谈话\n\n1149\n01:17:51.240 --> 01:17:55.070\n是发生在1968年1月1日？\n\n1150\n01:17:55.290 --> 01:17:56.820\n不可能在那天之后\n\n1151\n01:17:57.040 --> 01:18:01.790\n我1月20日要在洛杉矶开始新工作\n我得搬家\n\n1152\n01:18:02.000 --> 01:18:04.460\n-我觉得不是他，这家伙…\n-亚瑟李艾伦？\n\n1153\n01:18:04.670 --> 01:18:08.630\n这个李先生在元旦那天跟一个钓友\n透露整个犯案计划？\n\n1154\n01:18:08.840 --> 01:18:11.090\n也许他很生气，又喝了点酒\n\n1155\n01:18:11.310 --> 01:18:13.760\n他想了很久，这很合理\n\n1156\n01:18:13.970 --> 01:18:16.180\n那唐钱尼为什么没早点报警？\n\n1157\n01:18:16.390 --> 01:18:17.840\n我查过了，他有\n\n1158\n01:18:18.060 --> 01:18:21.140\n第一起关于李艾伦的报案\n\n1159\n01:18:21.360 --> 01:18:24.890\n来自波蒙纳警局1970年\n1月10日他的报案没被注意\n\n1160\n01:18:25.110 --> 01:18:28.150\n李有惹毛唐吗？\n比如说搞上唐的老婆？\n\n1161\n01:18:28.360 --> 01:18:33.070\n我们会全面调查\n不过我觉得这家伙有嫌疑\n\n1162\n01:18:33.700 --> 01:18:35.820\n那就采集他的字迹吧\n\n1163\n01:18:37.370 --> 01:18:40.620\n嗨，莫瑞尔有样本\n\n1164\n01:18:40.840 --> 01:18:43.200\n-你吃什么？\n-培根生菜蕃茄三明治\n\n1165\n01:18:45.130 --> 01:18:47.920\n支票存根联没用 ，字迹不够多\n\n1166\n01:18:48.130 --> 01:18:50.750\n申请表的字迹不像十二宫杀手\n但是不能证明\n\n1167\n01:18:50.970 --> 01:18:52.590\n他是或不是凶嫌\n\n1168\n01:18:52.810 --> 01:18:56.090\n-这么说很含糊\n-他需要更多笔迹样本\n\n1169\n01:18:56.680 --> 01:19:01.140\n还有，这家伙是个变态\n当梅尔从泉谷镇拿到申请表\n\n1170\n01:19:01.360 --> 01:19:03.970\n他们说李因为乱摸孩童被开除\n\n1171\n01:19:04.190 --> 01:19:07.230\n-乱摸？\n-婉转的说法\n\n1172\n01:19:08.030 --> 01:19:11.230\n-你要怎么做？\n-打几通电话\n\n1173\n01:19:11.450 --> 01:19:13.900\n-薯条不吃了吗？\n-请便\n\n1174\n01:19:14.120 --> 01:19:17.820\n你们看过十二宫杀手的信件拷贝吗？\n\n1175\n01:19:18.040 --> 01:19:20.410\n有，有些内容挺变态的\n\n1176\n01:19:20.620 --> 01:19:23.870\n我是说就像李一样变态\n\n1177\n01:19:24.090 --> 01:19:26.660\n他故意拼错字，觉得很有趣\n\n1178\n01:19:26.880 --> 01:19:28.290\n那么笔迹呢？\n\n1179\n01:19:28.510 --> 01:19:31.250\n我不知道，不是有专家验证吗？\n\n1180\n01:19:31.470 --> 01:19:34.420\n专家说字迹不能证明是同一个人\n\n1181\n01:19:34.640 --> 01:19:36.510\n也许他用另一只手写字\n\n1182\n01:19:36.720 --> 01:19:40.510\n那封信写得太工整\n不像是用另一只手写的字\n\n1183\n01:19:40.730 --> 01:19:43.100\n-但是李就可以，对吧？\n-什么意思？\n\n1184\n01:19:43.310 --> 01:19:47.810\n他能双手并用\n能用双手写字，你们不知道？\n\n1185\n01:19:48.030 --> 01:19:50.310\n平常艾伦都用左手写字\n\n1186\n01:19:50.530 --> 01:19:53.310\n填写工作申请表、写信给朋友\n\n1187\n01:19:53.530 --> 01:19:56.150\n但是他用右手写十二宫杀手的信\n\n1188\n01:19:56.370 --> 01:19:59.950\n写出不同的笔迹让人无法比对\n\n1189\n01:20:00.160 --> 01:20:02.360\n-我们得去见这家伙\n-他在哪里？\n\n1190\n01:20:02.580 --> 01:20:06.290\n瓦列霍，在皮诺尔的油厂工作\n他老哥也在那里工作\n\n1191\n01:20:06.500 --> 01:20:10.210\n两个人都见，记得知会穆拉斯\n那里是他的辖区\n\n1192\n01:20:10.420 --> 01:20:13.420\n是啊，河滨市警局就很合作\n\n1193\n01:20:13.760 --> 01:20:16.210\n咱们不计代价乖乖合作\n\n1194\n01:20:19.060 --> 01:20:23.220\n一天后 加州 罗迪欧 1971年8月4日\n\n1195\n01:20:26.270 --> 01:20:27.850\n你们在这里向他问话\n\n1196\n01:20:28.070 --> 01:20:30.560\n对了 ，贩卖机坏了\n\n1197\n01:20:31.200 --> 01:20:33.100\n我去叫他\n\n1198\n01:20:34.370 --> 01:20:36.610\n你们要怎么进行？\n\n1199\n01:20:36.830 --> 01:20:39.610\n比尔和密告者谈过，他来发问\n\n1200\n01:20:40.450 --> 01:20:42.150\n我没意见\n\n1201\n01:20:55.970 --> 01:20:59.590\n艾伦先生，我是比尔阿姆斯壮警探\n\n1202\n01:20:59.810 --> 01:21:01.420\n大卫陶希警探和杰克穆拉斯警官\n\n1203\n01:21:01.640 --> 01:21:05.760\n我们负责调查发生在旧金山\n以及瓦列霍的十二宫杀手杀人事件\n\n1204\n01:21:06.310 --> 01:21:07.970\n请坐\n\n1205\n01:21:16.660 --> 01:21:19.280\n告密者说你说了一些话\n\n1206\n01:21:19.490 --> 01:21:21.940\n就在十二宫杀手命案的十一个月前\n\n1207\n01:21:22.160 --> 01:21:24.610\n是真的话，对你很不利\n\n1208\n01:21:24.830 --> 01:21:27.780\n-你记得说过关于这些话的吗？\n-没有\n\n1209\n01:21:28.000 --> 01:21:30.580\n听过或看过十二宫杀手的报导吗？\n\n1210\n01:21:30.800 --> 01:21:33.870\n刚上报的时候\n不过之后我就没再注意了\n\n1211\n01:21:34.090 --> 01:21:35.460\n为什么？\n\n1212\n01:21:35.680 --> 01:21:37.420\n太病态了\n\n1213\n01:21:37.640 --> 01:21:39.670\n我跟另外一位警官也这么说\n\n1214\n01:21:40.680 --> 01:21:42.880\n-哪一位警官？\n-瓦列霍来的警官\n\n1215\n01:21:44.270 --> 01:21:45.800\n你记得他的名字吗？\n\n1216\n01:21:46.020 --> 01:21:49.310\n不记得，不过就在湖边命案之后\n\n1217\n01:21:49.520 --> 01:21:51.970\n你跟那位警官说了什么？\n\n1218\n01:21:53.940 --> 01:21:58.610\n我说那周末我去了盐岬潜水\n\n1219\n01:21:58.820 --> 01:22:01.480\n我一个人去，遇见了一对情侣\n\n1220\n01:22:01.990 --> 01:22:04.110\n你们要的话，我家有他们的名字\n\n1221\n01:22:04.330 --> 01:22:07.200\n-那就太好了 ，亚瑟\n-李\n\n1222\n01:22:07.420 --> 01:22:12.080\n-什么？\n-李，没有人叫我亚瑟\n\n1223\n01:22:13.050 --> 01:22:16.170\n而且我那天回家\n邻居有看见我\n\n1224\n01:22:16.380 --> 01:22:20.340\n大约是下午四点吧\n不过我忘了跟那位警察说\n\n1225\n01:22:20.550 --> 01:22:23.170\n-邻居的名字？\n-比利怀特\n\n1226\n01:22:24.390 --> 01:22:26.260\n他在一星期后左右去世\n\n1227\n01:22:26.480 --> 01:22:29.800\n心脏病，所以我没有打给警察\n\n1228\n01:22:31.770 --> 01:22:34.180\n车上沾有血迹的那把刀\n\n1229\n01:22:34.400 --> 01:22:37.190\n是我准备晚餐时杀鸡的血迹\n\n1230\n01:22:40.570 --> 01:22:43.230\n-什么？\n-那个周末我把刀放在车上\n\n1231\n01:22:43.450 --> 01:22:47.740\n也许比尔看到才向警方检举我\n\n1232\n01:22:48.500 --> 01:22:50.870\n我们会调查这件事\n\n1233\n01:22:51.090 --> 01:22:52.910\n我问你另一件事\n\n1234\n01:22:53.130 --> 01:22:57.460\n你在1966年间去过南加州吗？\n\n1235\n01:22:57.680 --> 01:22:59.670\n这是关于河滨市谋杀案吗？\n\n1236\n01:22:59.890 --> 01:23:01.540\n没错\n\n1237\n01:23:01.760 --> 01:23:05.510\n当时我的确去过那里\n我以前常去那里\n\n1238\n01:23:05.720 --> 01:23:08.010\n我喜欢看赛车\n\n1239\n01:23:11.730 --> 01:23:14.100\n告密者说你能双手并用？\n\n1240\n01:23:14.320 --> 01:23:16.020\n假的\n\n1241\n01:23:16.240 --> 01:23:18.560\n你不能用双手写字？\n\n1242\n01:23:19.780 --> 01:23:22.020\n小时候老师有逼我学\n\n1243\n01:23:22.240 --> 01:23:24.860\n但学不来。我是左撇子\n\n1244\n01:23:25.080 --> 01:23:28.450\n他还说你扬言要杀害学童\n\n1245\n01:23:30.000 --> 01:23:32.200\n太可怕了，那真是可怕的说法\n\n1246\n01:23:32.420 --> 01:23:34.790\n真是可怕的说法\n\n1247\n01:23:35.000 --> 01:23:38.080\n你从来没有因为你猥亵学童\n\n1248\n01:23:38.300 --> 01:23:40.210\n而遭到开除的事感到愤怒？\n\n1249\n01:23:49.810 --> 01:23:52.090\n我不是十二宫杀手\n\n1250\n01:23:52.520 --> 01:23:55.680\n就算是，也不会告诉你们\n\n1251\n01:23:58.030 --> 01:24:00.230\n不错的手表\n\n1252\n01:24:01.320 --> 01:24:03.360\n-谢谢\n-我能看吗？\n\n1253\n01:24:05.870 --> 01:24:07.480\n我能看吗？\n\n1254\n01:24:18.760 --> 01:24:19.870\n哪里买的？\n\n1255\n01:24:20.090 --> 01:24:21.080\n十二宫杀手\n\n1256\n01:24:21.260 --> 01:24:23.130\n两年前我妈送我的圣诞礼物\n\n1257\n01:24:23.340 --> 01:24:24.710\n你妈真好\n\n1258\n01:24:25.220 --> 01:24:28.840\n告诉我，亚瑟。你不记得…\n\n1259\n01:24:29.060 --> 01:24:32.680\n和任何人谈过十二宫杀手？\n\n1260\n01:24:34.350 --> 01:24:40.600\n也许和瓦列霍休闲中心的\n泰德或费尔谈过吧\n\n1261\n01:24:40.900 --> 01:24:44.810\n我不能确定，我在那里上过班\n\n1262\n01:24:48.700 --> 01:24:51.240\n《最危险的游戏》\n\n1263\n01:24:52.250 --> 01:24:54.160\n-什么？\n-《最危险的游戏》\n\n1264\n01:24:54.370 --> 01:24:57.830\n你们是为了这件事来的，对吧？\n我高中最喜欢的一本书\n\n1265\n01:24:58.050 --> 01:25:01.500\n描述一个人在孤岛\n等船难的生还者\n\n1266\n01:25:01.720 --> 01:25:05.000\n因为他厌倦猎杀动物\n想挑战猎杀人类看看\n\n1267\n01:25:05.220 --> 01:25:08.500\n所以 “人类比任何猛兽更危险”\n\n1268\n01:25:09.430 --> 01:25:11.510\n这就是整本书的主题\n\n1269\n01:25:12.560 --> 01:25:13.880\n很棒的一本书\n\n1270\n01:25:15.150 --> 01:25:17.760\n至少我是跟费尔这么说的\n\n1271\n01:25:23.400 --> 01:25:25.230\n我能走了吗？\n\n1272\n01:25:28.330 --> 01:25:29.650\n当然\n\n1273\n01:25:34.250 --> 01:25:38.030\n-谢谢你的时间\n-我很乐意协助你们\n\n1274\n01:25:38.630 --> 01:25:40.450\n我很期待有一天\n\n1275\n01:25:40.670 --> 01:25:44.370\n警察能不再被蔑称为“猪头”\n\n1276\n01:25:45.220 --> 01:25:46.880\n谢了\n\n1277\n01:25:47.510 --> 01:25:48.960\n我们再联络\n\n1278\n01:26:00.940 --> 01:26:04.600\n有谁觉得他还需要被调查吗？\n\n1279\n01:26:04.990 --> 01:26:07.940\n这些是十二宫杀手信件的副本\n\n1280\n01:26:08.160 --> 01:26:09.400\n十小时后 加州 瓦列霍\n\n1281\n01:26:09.620 --> 01:26:11.320\n请你们看一看\n\n1282\n01:26:11.870 --> 01:26:13.860\n你们认为我弟弟是十二宫杀手\n\n1283\n01:26:14.080 --> 01:26:17.280\n-我们正在调查他\n-你们会逮捕他吗？\n\n1284\n01:26:17.500 --> 01:26:21.240\n艾伦太太，我们不会因为\n调查一个人而逮捕他\n\n1285\n01:26:21.460 --> 01:26:25.080\n-李一向都有心理问题\n-他猥亵学童的事是真的吗？\n\n1286\n01:26:25.800 --> 01:26:29.670\n很不幸是的\n我们知道后就很少去见他\n\n1287\n01:26:29.890 --> 01:26:32.090\n你们觉得唐钱尼怎样？\n\n1288\n01:26:32.310 --> 01:26:35.550\n唐钱尼？我旧室友？\n是他连络你们的？\n\n1289\n01:26:35.770 --> 01:26:39.010\n-这是机密\n-唐这个人很可靠\n\n1290\n01:26:39.230 --> 01:26:42.350\n他说的话，我会相信是真的\n\n1291\n01:26:42.570 --> 01:26:43.720\n-这个字\n-怎么样？\n\n1292\n01:26:43.940 --> 01:26:45.890\n他用两个S拼圣诞节\n\n1293\n01:26:46.110 --> 01:26:50.110\n两年前我们收到他的圣诞卡\n也是同样的拼法\n\n1294\n01:26:50.320 --> 01:26:52.650\n-“Chr i s t-mass”\n-那张圣诞卡还在吗？\n\n1295\n01:26:52.870 --> 01:26:55.570\n-我可以找找看\n-谢谢，太好了\n\n1296\n01:26:57.160 --> 01:26:59.110\n我们还能帮什么忙？\n\n1297\n01:26:59.330 --> 01:27:02.120\n下次李出门时他老哥会搜他房间\n\n1298\n01:27:02.340 --> 01:27:04.620\n-这样就不必申请搜票\n-就这一次\n\n1299\n01:27:04.840 --> 01:27:06.120\n如果找到什么\n\n1300\n01:27:06.340 --> 01:27:09.750\n穆拉斯会去找瓦列霍检察官\n仔细搜查房子\n\n1301\n01:27:09.970 --> 01:27:13.960\n我去找贝瑞莎命案两天后\n向李问过话的警官\n\n1302\n01:27:14.180 --> 01:27:17.930\n他不记得为什么要问他话\n不过他认为李不像杀人凶手\n\n1303\n01:27:18.140 --> 01:27:20.260\n-所以没有继续追查\n-你认为他是凶手？\n\n1304\n01:27:20.480 --> 01:27:23.680\n-我很想当场就逮捕他\n-别急，大卫\n\n1305\n01:27:23.900 --> 01:27:27.350\n多找些线索给莫瑞尔\n笔迹符合的话就罪证确凿\n\n1306\n01:27:27.570 --> 01:27:30.520\n-艾瑞在二线\n-叫他去死\n\n1307\n01:27:30.740 --> 01:27:34.650\n你要我直接说还是加点料？\n\n1308\n01:27:42.290 --> 01:27:45.160\n真要命\n\n1309\n01:27:46.590 --> 01:27:49.920\n怎么了\n\n1310\n01:27:50.130 --> 01:27:52.250\n-保罗,我在想…\n-噢,上帝保佑\n\n1311\n01:27:52.470 --> 01:27:54.540\n-我们知道他两只手都善用\n-38年了\n\n1312\n01:27:54.760 --> 01:27:56.880\n从来没见过两只手用的这么好的人\n\n1313\n01:27:57.100 --> 01:27:59.010\n一定会有相同之处\n\n1314\n01:28:00.100 --> 01:28:03.510\n抱歉，这论点无法成立\n\n1315\n01:28:05.440 --> 01:28:07.720\n-重案组，我是陶希\n-大卫，我是杰克穆拉斯\n\n1316\n01:28:07.940 --> 01:28:10.060\n对，是穆拉斯，怎么样了？\n\n1317\n01:28:10.280 --> 01:28:13.310\n法官不愿意发出搜索票\n\n1318\n01:28:13.530 --> 01:28:15.150\n-为什么？\n-他说证据不足\n\n1319\n01:28:15.370 --> 01:28:18.110\n除非找到符合的笔迹和证物\n\n1320\n01:28:18.330 --> 01:28:20.200\n没有搜索票怎么找到证物？\n\n1321\n01:28:20.410 --> 01:28:22.070\n不知道\n\n1322\n01:28:22.290 --> 01:28:25.620\n-真的很抱歉\n-不，谢谢你\n\n1323\n01:28:27.170 --> 01:28:29.450\n-你想怎么办？\n-没有瓦列霍的证物就没辙\n\n1324\n01:28:29.670 --> 01:28:32.670\n我们需要李的右手笔迹\n没有就拿不到搜索票\n\n1325\n01:28:32.880 --> 01:28:34.960\n还有其他的嫌犯吗？\n\n1326\n01:28:35.180 --> 01:28:38.380\n-至少还有多少？\n-两千三百个\n\n1327\n01:28:39.060 --> 01:28:40.470\n好吧，就这样了\n\n1328\n01:28:43.770 --> 01:28:45.260\n好吧，就这样了\n\n1329\n01:29:12.800 --> 01:29:15.460\n保罗，你写信给司法部\n\n1330\n01:29:15.680 --> 01:29:19.170\n要求负责调查十二宫杀手命案？\n\n1331\n01:29:19.390 --> 01:29:21.050\n一年后 加州 旧金山\n\n1332\n01:29:21.270 --> 01:29:23.800\n-我只是建议\n-你用报社的信纸？\n\n1333\n01:29:24.020 --> 01:29:27.930\n对案情熟悉的个人或单位\n\n1334\n01:29:28.150 --> 01:29:30.430\n能够聚集在一起交换线索和想法\n\n1335\n01:29:30.650 --> 01:29:33.390\n-然后由你来主导\n-还有谁比我更适合？\n\n1336\n01:29:34.740 --> 01:29:35.940\n我被黄带道盯上\n\n1337\n01:29:36.990 --> 01:29:40.650\n保罗，你想继续在报社工作\n得答应我三件事，第一，戒酒\n\n1338\n01:29:40.870 --> 01:29:43.820\n第二，停止你目前在做的事\n\n1339\n01:29:44.040 --> 01:29:47.240\n第三，忘了你这种荒谬的想法\n\n1340\n01:29:47.460 --> 01:29:50.580\n亲爱的丹波顿，如果你认为\n\n1341\n01:29:50.800 --> 01:29:55.960\n我杰出的工作表现\n在这鬼地方不适用的话\n\n1342\n01:29:56.180 --> 01:29:57.710\n我倒是很乐意\n\n1343\n01:29:57.930 --> 01:30:01.000\n寻求其他的发展\n\n1344\n01:30:01.220 --> 01:30:03.010\n保罗，我是认真的\n\n1345\n01:30:13.190 --> 01:30:15.020\n-保罗？\n-是\n\n1346\n01:30:15.280 --> 01:30:16.690\n刚刚是怎么回事？\n\n1347\n01:30:16.910 --> 01:30:19.230\n编辑部的斗争\n\n1348\n01:30:19.450 --> 01:30:21.570\n-要喝一杯吗？\n-现在是早上十点耶\n\n1349\n01:30:21.790 --> 01:30:26.450\n-也许可以算是早午餐\n-保罗\n\n1350\n01:30:29.210 --> 01:30:30.830\n你还好吗？\n\n1351\n01:30:31.590 --> 01:30:32.870\n不好\n\n1352\n01:30:36.050 --> 01:30:37.830\n多谢你的慰问\n\n1353\n01:30:40.180 --> 01:30:41.290\n-矮子\n-是\n\n1354\n01:30:41.510 --> 01:30:44.380\n-出去喝一杯吧\n-保罗，你要去哪里？\n\n1355\n01:30:46.390 --> 01:30:48.050\n你们停止调查我小叔？\n\n1356\n01:30:48.900 --> 01:30:50.970\n我们申请不到搜索票\n\n1357\n01:30:51.190 --> 01:30:52.560\n1972年9月7日 加州 瓦列霍\n\n1358\n01:30:52.770 --> 01:30:55.850\n去年我们安排李和社工见面\n\n1359\n01:30:56.070 --> 01:31:00.690\n他只去了两次\n\n1360\n01:31:00.910 --> 01:31:03.860\n最近我婆婆带他来看小孩\n这是九个月来第一次见面\n\n1361\n01:31:04.080 --> 01:31:07.030\n后来我就去找社工了解状况\n\n1362\n01:31:07.250 --> 01:31:10.160\n他不能透露病人病情\n我就直接问他\n\n1363\n01:31:10.380 --> 01:31:12.950\n李会不会杀人\n\n1364\n01:31:13.170 --> 01:31:16.450\n-由于病人保密法则…\n-社工说他会杀人\n\n1365\n01:31:18.260 --> 01:31:20.170\n你们为什么九个月没见过他？\n\n1366\n01:31:20.390 --> 01:31:22.250\n他在圣塔罗莎的学校上课\n\n1367\n01:31:22.470 --> 01:31:25.880\n-圣塔罗莎？他住在哪里？\n-他的拖车屋\n\n1368\n01:31:26.100 --> 01:31:27.760\n-在圣塔罗莎？\n-索诺犸郡\n\n1369\n01:31:27.980 --> 01:31:30.140\n我们不用透过瓦列霍检察官\n\n1370\n01:31:30.350 --> 01:31:33.350\n你们有11个月没问过他话\n现在要去搜他的拖车屋？\n\n1371\n01:31:33.570 --> 01:31:35.180\n能找到证物最好\n\n1372\n01:31:35.400 --> 01:31:38.520\n不然也能采到指纹和双手的笔迹\n\n1373\n01:31:38.740 --> 01:31:40.730\n我以为莫瑞尔推翻了你的论点\n\n1374\n01:31:41.950 --> 01:31:44.070\n我想请别人鉴定行不行？\n\n1375\n01:31:45.490 --> 01:31:47.900\n我不想反驳莫瑞尔的鉴定\n我是他一手栽培的\n\n1376\n01:31:48.120 --> 01:31:50.780\n我只想知道嫌犯能不能双手并用\n\n1377\n01:31:51.000 --> 01:31:54.780\n他是不是可能用另一只手写的信？\n\n1378\n01:31:56.130 --> 01:31:57.250\n这话就咱俩听一下\n\n1379\n01:31:57.460 --> 01:32:00.790\n笔迹鉴定有不同的学派\n\n1380\n01:32:02.180 --> 01:32:06.340\n只要拿到他另一只手的笔迹\n如果他是十二宫杀手就会符合\n\n1381\n01:32:06.560 --> 01:32:09.300\n这是泰瑞目前的想法\n\n1382\n01:32:09.520 --> 01:32:12.260\n我也问了愿意作证的心理医师\n\n1383\n01:32:12.480 --> 01:32:15.600\n他说像十二宫杀手这种性格多变的人\n\n1384\n01:32:15.820 --> 01:32:18.600\n生理上也会改变，比如改变笔迹\n\n1385\n01:32:18.820 --> 01:32:22.350\n所以莫瑞尔的笔迹鉴定会不符合\n\n1386\n01:32:22.570 --> 01:32:24.690\n泰瑞、心理医师和钱尼夫妇\n\n1387\n01:32:24.910 --> 01:32:27.570\n有他们就能申请搜索票\n\n1388\n01:32:27.790 --> 01:32:29.070\n请钱尼做正式笔录\n\n1389\n01:32:29.290 --> 01:32:31.780\n“在孩子们欢跃而出的时候射杀他们”\n\n1390\n01:32:32.000 --> 01:32:35.830\n他会自称为十二宫杀手\n\n1391\n01:32:36.040 --> 01:32:38.410\n-是的\n-你愿意在\n\n1392\n01:32:38.630 --> 01:32:40.500\n高等法庭发誓作证？\n\n1393\n01:32:40.720 --> 01:32:42.000\n毫不犹豫\n\n1394\n01:32:42.220 --> 01:32:45.420\n非常感谢你，钱尼先生\n\n1395\n01:32:45.640 --> 01:32:46.960\n谢谢你\n\n1396\n01:32:48.060 --> 01:32:50.920\n看来你们抓到人了\n\n1397\n01:32:52.140 --> 01:32:58.680\n1972年9月14日，加州\n圣塔罗莎日落拖车公园-A7位\n\n1398\n01:33:11.370 --> 01:33:14.320\n艾伦先生？这里是圣塔罗莎警局\n\n1399\n01:33:14.540 --> 01:33:17.160\n我们持有搜查令，现在要搜查你的住所\n\n1400\n01:33:28.560 --> 01:33:29.840\n有人么？\n\n1401\n01:33:38.570 --> 01:33:40.390\n我去问附近的邻居\n\n1402\n01:33:42.070 --> 01:33:43.520\n-关门\n-关门\n\n1403\n01:33:43.740 --> 01:33:45.770\n有鼠类动物跑来跑去\n\n1404\n01:33:58.460 --> 01:34:00.950\n邻居说他半小时前闪人了\n\n1405\n01:34:01.170 --> 01:34:04.620\n-有人向他告密？\n-他回来前我们不会走\n\n1406\n01:34:11.220 --> 01:34:12.510\n我去查后面\n\n1407\n01:34:25.820 --> 01:34:27.520\n-老天\n-什么？\n\n1408\n01:34:27.740 --> 01:34:29.110\n松鼠\n\n1409\n01:34:30.740 --> 01:34:32.190\n这家伙超变态的\n\n1410\n01:34:39.540 --> 01:34:41.700\n不只一件，两件蓝色风衣\n\n1411\n01:34:41.920 --> 01:34:45.410\n-史坦命案现场那件？\n-我们会送去验血比对\n\n1412\n01:34:46.590 --> 01:34:50.250\n还有一对黑色手套\n\n1413\n01:34:50.720 --> 01:34:53.760\n男性七号大小\n跟计程车上那对一样\n\n1414\n01:34:54.430 --> 01:34:56.800\n鞋子和手套的尺寸也符合\n\n1415\n01:34:57.020 --> 01:34:59.010\n搞不好只是巧合\n\n1416\n01:34:59.230 --> 01:35:03.810\n我找到一把枪，你看\n不对，是两把枪\n\n1417\n01:35:04.650 --> 01:35:07.390\n两把点22口径手枪\n一把自动手枪、一把左轮手枪\n\n1418\n01:35:07.610 --> 01:35:08.900\n这倒很有趣\n\n1419\n01:35:09.110 --> 01:35:12.190\n他的衣橱也有一把M1步枪\n\n1420\n01:35:12.410 --> 01:35:14.900\n向那些可爱的学童下手\n\n1421\n01:35:16.500 --> 01:35:17.950\n有人来了\n\n1422\n01:35:25.130 --> 01:35:28.290\n哈啰，亚瑟，记得我们吗？\n\n1423\n01:35:50.070 --> 01:35:52.150\n-没有证据\n-笔迹呢？\n\n1424\n01:35:52.370 --> 01:35:55.360\n弹道、指纹跟笔迹都不符合\n\n1425\n01:35:55.580 --> 01:35:59.490\n双手的笔迹吗？\n双手的笔迹我们都有\n\n1426\n01:35:59.710 --> 01:36:00.990\n双手笔迹都不符合\n\n1427\n01:36:01.210 --> 01:36:04.830\n-别管莫瑞尔，问其他专家的意见\n-两位，他不是凶手\n\n1428\n01:36:11.470 --> 01:36:12.920\n可恶\n\n1429\n01:36:20.020 --> 01:36:21.760\n嘿\n\n1430\n01:36:21.980 --> 01:36:23.510\n你想怎样？\n\n1431\n01:36:23.730 --> 01:36:25.220\n休息一阵子？\n\n1432\n01:36:26.610 --> 01:36:28.140\n抱一下？\n\n1433\n01:36:28.610 --> 01:36:30.560\n你知道最糟的是什么吗？\n\n1434\n01:36:30.780 --> 01:36:34.480\n我不知道我是认为凶手就是艾伦\n\n1435\n01:36:34.700 --> 01:36:36.150\n还是希望案子快点结束\n\n1436\n01:36:36.370 --> 01:36:40.200\n因为你认为是他，我也是啊\n\n1437\n01:36:42.460 --> 01:36:44.120\n这样吧，休息一阵子\n\n1438\n01:36:44.330 --> 01:36:46.870\n陪陪你老婆还有小孩\n\n1439\n01:36:47.300 --> 01:36:50.620\n带他们看球赛或是看电影\n\n1440\n01:36:51.470 --> 01:36:52.920\n特别会议 旧金山警察局\n\n1441\n01:36:53.090 --> 01:36:56.540\n致旧金山市民\n我很乐意每天杀一个人\n\n1442\n01:36:56.760 --> 01:36:59.800\n直到你们付我十万元\n\n1443\n01:37:00.020 --> 01:37:03.300\n同意的话，明天早上回复\n\n1444\n01:37:03.520 --> 01:37:06.390\n刊登在《旧金山纪事报》交友专栏\n\n1445\n01:37:06.610 --> 01:37:08.390\n我就会出面\n\n1446\n01:37:08.610 --> 01:37:10.390\n如果得不到回复\n\n1447\n01:37:10.610 --> 01:37:13.730\n我会先杀死一名天主教神父或者…\n\n1448\n01:37:13.990 --> 01:37:15.060\n一个黑鬼\n\n1449\n01:37:16.700 --> 01:37:18.570\n“天蝎座”\n\n1450\n01:37:20.620 --> 01:37:22.200\n他一定是疯了\n\n1451\n01:37:22.410 --> 01:37:23.780\n我得闪人\n\n1452\n01:37:24.000 --> 01:37:27.030\n我要去哪里生出十万元？\n\n1453\n01:37:27.250 --> 01:37:29.870\n市长，你不会真要付钱吧？\n\n1454\n01:37:30.090 --> 01:37:34.040\n旧金山市政府不会付钱给凶手\n好让他不去杀人\n\n1455\n01:37:36.510 --> 01:37:38.340\n《紧急追捕令》\n\n1456\n01:37:38.510 --> 01:37:43.050\n-长官，是谁负责这一切？\n-是卡拉汉警探，他在外面等\n\n1457\n01:37:57.320 --> 01:38:00.150\n凶手最后胸口被开了一枪\n\n1458\n01:38:00.370 --> 01:38:03.400\n-结局就是这样\n-我认识你吗？\n\n1459\n01:38:03.620 --> 01:38:07.070\n我是罗伯葛雷史密斯\n保罗艾瑞《纪事报》的同事\n\n1460\n01:38:07.290 --> 01:38:08.700\n大卫陶希，幸会\n\n1461\n01:38:08.920 --> 01:38:11.370\n那个卡拉汉对你的案子办得不错\n\n1462\n01:38:11.590 --> 01:38:14.830\n是啊，他才不鸟正规的手续对吧？\n\n1463\n01:38:18.510 --> 01:38:20.550\n-你在报社做什么？\n-我画漫画\n\n1464\n01:38:20.760 --> 01:38:23.050\n-不错啊\n-你会逮到他的\n\n1465\n01:38:25.640 --> 01:38:28.220\n老弟，这案子都拍成电影了\n\n1466\n01:38:41.700 --> 01:38:46.320\n四年后\n\n1467\n01:39:00.140 --> 01:39:04.170\n嗨，初次见面。我是罗伯特·格雷史密斯\n\n1468\n01:39:04.390 --> 01:39:06.220\n我是达菲詹宁\n\n1469\n01:39:06.430 --> 01:39:09.180\n-幸会\n-彼此彼此\n\n1470\n01:39:09.600 --> 01:39:12.850\n这办公桌不错\n前一任记者非常优秀\n\n1471\n01:39:13.070 --> 01:39:16.890\n我猜也是吧\n从《旧金山纪事报》\n\n1472\n01:39:17.110 --> 01:39:19.350\n跳槽到《沙加缅度蜜蜂报》\n\n1473\n01:39:19.570 --> 01:39:21.810\n算是降级了 ，对吧，罗伯特？\n\n1474\n01:39:25.700 --> 01:39:28.240\n-幸会了\n-彼此彼此\n\n1475\n01:39:28.460 --> 01:39:30.740\n我就坐在美工部\n\n1476\n01:39:30.960 --> 01:39:32.700\n需要帮忙就说一声，杜菲\n\n1477\n01:39:36.800 --> 01:39:39.540\n-你确定今晚不用车，比尔？\n-换你开了\n\n1478\n01:39:39.760 --> 01:39:42.790\n送我回家然后把车开走\n\n1479\n01:39:43.010 --> 01:39:44.800\n车子你留着吧\n\n1480\n01:39:45.010 --> 01:39:46.260\n真的吗？\n\n1481\n01:39:47.100 --> 01:39:49.050\n明天我不进警局了\n\n1482\n01:39:51.150 --> 01:39:53.050\n这是怎么回事？\n\n1483\n01:39:54.110 --> 01:39:55.430\n我不玩了\n\n1484\n01:39:56.650 --> 01:39:59.060\n我申请调职\n\n1485\n01:40:04.780 --> 01:40:08.030\n-调去哪里？\n-诈欺组\n\n1486\n01:40:10.160 --> 01:40:12.740\n我不能再随时待命了\n\n1487\n01:40:15.000 --> 01:40:17.870\n我想看着我的孩子长大\n\n1488\n01:40:18.340 --> 01:40:21.250\n这样也好，比尔\n\n1489\n01:40:22.510 --> 01:40:25.460\n-你会没事的\n-是啊，我不会有事\n\n1490\n01:40:27.180 --> 01:40:28.510\n嘿\n\n1491\n01:40:29.430 --> 01:40:33.390\n我没留下烂摊子给你吧\n\n1492\n01:40:34.480 --> 01:40:35.850\n没啦\n\n1493\n01:40:37.940 --> 01:40:39.390\n那就好\n\n1494\n01:40:39.610 --> 01:40:41.060\n知道吗？\n\n1495\n01:40:41.820 --> 01:40:45.770\n也许你可以试试日本料理\n生鱼片之类的\n\n1496\n01:40:46.990 --> 01:40:48.400\n是啊\n\n1497\n01:41:04.680 --> 01:41:08.000\n“我已杀了七人” 十二宫杀手扬言\n\n1498\n01:41:10.270 --> 01:41:11.380\n十二宫杀手命案最新线索\n\n1499\n01:41:11.600 --> 01:41:13.220\n确定和十二宫杀手有关\n\n1500\n01:41:20.490 --> 01:41:22.690\n“我不是保罗艾瑞”\n\n1501\n01:41:24.660 --> 01:41:27.610\n去哄儿子们睡觉\n顺便替宝宝换尿布\n\n1502\n01:41:27.830 --> 01:41:30.860\n-掷硬币决定\n-想得美\n\n1503\n01:41:33.710 --> 01:41:36.660\n没人比你有更多十二宫杀手的资料了\n\n1504\n01:41:44.260 --> 01:41:45.750\n搜寻十二宫杀手四件凶器\n\n1505\n01:41:48.140 --> 01:41:49.300\n十二宫杀手肖像\n\n1506\n01:41:50.140 --> 01:41:51.260\n警方调查十二宫杀手身份仍无进展\n\n1507\n01:42:21.000 --> 01:42:23.370\n-不会吧？\n-嗨，保罗\n\n1508\n01:42:24.760 --> 01:42:27.000\n允许你上船\n\n1509\n01:42:27.220 --> 01:42:30.040\n坐那里，反正你穿着鞋子\n坐那里最好\n\n1510\n01:42:30.260 --> 01:42:32.630\n-就是这里\n-好\n\n1511\n01:42:33.680 --> 01:42:35.380\n看到没，超炫的\n\n1512\n01:42:35.600 --> 01:42:39.640\n我小孩肯定会想要那玩意\n\n1513\n01:42:41.070 --> 01:42:43.520\n-你还好吗？\n-棒呆了\n\n1514\n01:42:43.730 --> 01:42:47.900\n我承认《蜜蜂报》\n没有《纪事报》来得有趣\n\n1515\n01:42:48.110 --> 01:42:50.980\n来一杯吗？我没有蓝色的酒\n\n1516\n01:42:51.200 --> 01:42:53.230\n算了 ，别麻烦了\n\n1517\n01:42:53.450 --> 01:42:56.900\n一点都不麻烦，反正没人来过\n\n1518\n01:42:57.120 --> 01:42:58.320\n干杯\n\n1519\n01:42:58.960 --> 01:43:01.280\n为咱们俩的健康敬一杯\n\n1520\n01:43:03.090 --> 01:43:04.910\n主要是我的啦\n\n1521\n01:43:13.350 --> 01:43:14.630\n有什么新鲜事？\n\n1522\n01:43:16.680 --> 01:43:19.680\n我在想，应该有人写本书\n\n1523\n01:43:19.900 --> 01:43:22.970\n早就该有人写本书\n\n1524\n01:43:23.190 --> 01:43:25.730\n-写什么？\n-十二宫杀手的案子\n\n1525\n01:43:26.690 --> 01:43:28.140\n这不是什么新鲜事\n\n1526\n01:43:28.360 --> 01:43:32.230\n我在想只要把所有线索兜在一块\n\n1527\n01:43:32.450 --> 01:43:35.400\n也许会有什么新发现\n\n1528\n01:43:35.620 --> 01:43:38.490\n-没有人比你更了解整件案子\n-那倒是真的\n\n1529\n01:43:38.710 --> 01:43:41.490\n你有档案，认识每个人\n\n1530\n01:43:41.710 --> 01:43:44.410\n-档案没了\n-你弄丢了？\n\n1531\n01:43:44.630 --> 01:43:48.040\n还是扔了 ，我不知道\n我人都搬到船上了\n\n1532\n01:43:48.260 --> 01:43:51.290\n你应该知道我们是跑每日新闻\n\n1533\n01:43:51.510 --> 01:43:53.750\n干嘛管那老掉牙的新闻？\n\n1534\n01:43:55.510 --> 01:43:58.300\n东湾每三个月死于车祸的人\n\n1535\n01:43:58.520 --> 01:43:59.970\n都比那疯子杀的人多\n\n1536\n01:44:00.190 --> 01:44:04.430\n他杀了几个人，写了几封信\n然后就这样消失了\n\n1537\n01:44:10.400 --> 01:44:14.650\n我又没笨到坐在这里等你来\n\n1538\n01:44:14.870 --> 01:44:17.650\n让我重拾人生意义\n\n1539\n01:44:19.710 --> 01:44:22.280\n那是四年前的事，忘了吧\n\n1540\n01:44:22.670 --> 01:44:25.740\n你错了，这件事很重要\n\n1541\n01:44:26.960 --> 01:44:29.120\n那你到底做了什么？\n\n1542\n01:44:30.220 --> 01:44:32.500\n真的那么重要，你却啥都没做\n\n1543\n01:44:32.720 --> 01:44:35.210\n你搜我的桌子，翻我的垃圾\n\n1544\n01:44:35.430 --> 01:44:37.050\n我有对你翻脸吗？\n\n1545\n01:44:38.220 --> 01:44:42.430\n我忘了 ，你都去图书馆\n\n1546\n01:44:44.400 --> 01:44:46.390\n抱歉打扰你\n\n1547\n01:45:08.300 --> 01:45:10.370\n-嘿，嗨\n-嗨\n\n1548\n01:45:10.590 --> 01:45:13.540\n-你去了哪里？\n-图书馆\n\n1549\n01:45:21.890 --> 01:45:28.010\n1977年10月11日 加州 旧金山\n华盛顿与樱桃街转角处\n\n1550\n01:45:44.710 --> 01:45:46.320\n谢谢你\n\n1551\n01:46:01.770 --> 01:46:05.430\n-陶希警探？\n-请等一下\n\n1552\n01:46:09.480 --> 01:46:11.470\n-嗨\n-嗨\n\n1553\n01:46:12.230 --> 01:46:13.930\n我们在戏院见过面\n\n1554\n01:46:14.570 --> 01:46:16.900\n-那一定是在变魔术\n-我是罗伯葛雷史密斯\n\n1555\n01:46:17.110 --> 01:46:20.400\n在《旧金山纪事报》工作\n能请你吃顿午餐吗？\n\n1556\n01:46:22.290 --> 01:46:23.490\n好啊，有何不可？\n\n1557\n01:46:23.700 --> 01:46:26.570\n你是保罗艾瑞的朋友？\n\n1558\n01:46:26.790 --> 01:46:29.030\n我是为了他来找你的\n\n1559\n01:46:30.670 --> 01:46:32.540\n我想请教十二宫杀手的案子\n\n1560\n01:46:33.460 --> 01:46:36.460\n多谢了 ，不过我们不准讨论案情\n\n1561\n01:46:36.680 --> 01:46:38.920\n那警方每天都在做什么？\n\n1562\n01:46:39.140 --> 01:46:41.380\n积极调查任何线索\n\n1563\n01:46:41.600 --> 01:46:44.510\n案子就剩你一个人在办\n\n1564\n01:46:45.020 --> 01:46:46.680\n葛雷史密斯先生\n\n1565\n01:46:47.310 --> 01:46:49.260\n十二宫杀手有三年没有写过信\n\n1566\n01:46:49.480 --> 01:46:52.220\n你知道之后旧金山发生几起命案？\n\n1567\n01:46:52.440 --> 01:46:53.890\n-不知道\n-200起以上\n\n1568\n01:46:54.110 --> 01:46:57.100\n有很多死者和家属需要帮助\n\n1569\n01:46:57.320 --> 01:46:58.810\n所以已经没有人在乎了\n\n1570\n01:46:59.030 --> 01:47:01.900\n不好意思，我很在乎\n\n1571\n01:47:04.290 --> 01:47:06.490\n我可以给你看样东西吗？\n\n1572\n01:47:09.460 --> 01:47:12.540\n我针对第一张密码做了研究\n\n1573\n01:47:12.750 --> 01:47:17.670\n对解码有兴趣的业余人士\n都能在这些书里找到解答\n\n1574\n01:47:17.880 --> 01:47:21.000\n我在想如果追踪这些书的去向\n\n1575\n01:47:21.220 --> 01:47:23.130\n也许就能找到凶手\n\n1576\n01:47:24.060 --> 01:47:26.760\n你说过十二宫杀手有可能是军人\n\n1577\n01:47:26.980 --> 01:47:30.510\n我跑遍所有的军事基地图书馆\n\n1578\n01:47:30.730 --> 01:47:34.680\n列出借过这些书的人的名字\n最后发现一件事\n\n1579\n01:47:39.570 --> 01:47:42.020\n-遗失\n-表示这些书是被偷走\n\n1580\n01:47:42.660 --> 01:47:46.320\n普西迪图书馆的密码书都被偷走？\n\n1581\n01:47:46.540 --> 01:47:48.570\n还有奥克兰陆军图书馆\n\n1582\n01:47:51.920 --> 01:47:55.620\n有人不想被查到他借了这些书\n\n1583\n01:47:56.510 --> 01:47:58.500\n你是谁？\n\n1584\n01:48:00.260 --> 01:48:02.250\n我只想帮忙\n\n1585\n01:48:05.100 --> 01:48:07.050\n我不能让你帮忙\n\n1586\n01:48:07.270 --> 01:48:10.340\n不能和你讨论案情、提供资料\n\n1587\n01:48:10.560 --> 01:48:14.260\n更不能叫你去那帕找肯恩纳尔罗\n\n1588\n01:48:14.480 --> 01:48:15.760\n纳-尔-罗\n\n1589\n01:48:25.870 --> 01:48:30.700\n很抱歉，葛雷史密斯先生\n我们不跟作家合作\n\n1590\n01:48:30.920 --> 01:48:32.990\n我不是作家，是漫画家\n\n1591\n01:48:34.460 --> 01:48:36.580\n-大卫陶希叫你来\n-对\n\n1592\n01:48:36.800 --> 01:48:38.450\n-为什么？\n-也许他…\n\n1593\n01:48:38.670 --> 01:48:40.790\n也许他认为我帮得上忙\n\n1594\n01:48:42.260 --> 01:48:46.960\n-你是童子军吗？\n-第一级鹰级童子军\n\n1595\n01:48:47.470 --> 01:48:50.380\n你想查就尽管查\n\n1596\n01:48:51.730 --> 01:48:54.050\n先去找瓦列霍的杰克穆拉斯\n\n1597\n01:48:54.860 --> 01:48:57.010\n我知道你想干嘛\n\n1598\n01:48:57.230 --> 01:48:59.430\n但这是警方的公开调查\n\n1599\n01:48:59.650 --> 01:49:01.770\n我是大卫陶希的朋友\n\n1600\n01:49:01.990 --> 01:49:04.940\n他说你能帮助我\n\n1601\n01:49:05.490 --> 01:49:09.030\n案子没进展，凶手早就走人了\n\n1602\n01:49:09.250 --> 01:49:11.450\n他不是新闻了，对吗？\n\n1603\n01:49:12.410 --> 01:49:14.160\n他们是这么说的\n\n1604\n01:49:15.000 --> 01:49:16.910\n所以你有什么损失呢？\n\n1605\n01:49:17.130 --> 01:49:18.620\n不准带纸笔\n\n1606\n01:49:18.840 --> 01:49:21.620\n想知道的就记在脑子里\n\n1607\n01:49:21.840 --> 01:49:23.120\n了解\n\n1608\n01:49:25.180 --> 01:49:27.130\n-好，来吧\n-哪一个？\n\n1609\n01:49:27.350 --> 01:49:29.210\n全部都是。隔壁有更多\n\n1610\n01:49:29.430 --> 01:49:31.130\n全部都有编号\n\n1611\n01:49:31.350 --> 01:49:34.390\n-243-146\n-你不抽烟吧？\n\n1612\n01:49:34.730 --> 01:49:37.720\n高中抽过一次\n\n1613\n01:49:40.280 --> 01:49:41.730\n我看看这个\n\n1614\n01:49:42.570 --> 01:49:44.440\n谢谢\n\n1615\n01:49:45.110 --> 01:49:46.230\n档案243-146\n\n1616\n01:50:05.090 --> 01:50:06.500\n黛琳·伊丽莎白·费伦\n\n1617\n01:50:08.140 --> 01:50:10.170\n与男友在蓝石泉\n\n1618\n01:50:11.930 --> 01:50:13.550\n老兄，你差点吓死我们\n\n1619\n01:50:19.770 --> 01:50:21.390\n9毫米\n\n1620\n01:50:23.570 --> 01:50:26.690\n“一言不发就开枪”\n\n1621\n01:50:31.160 --> 01:50:34.780\n亚瑟李艾伦\n出生日期：12-18-33\n\n1622\n01:50:35.000 --> 01:50:38.450\n不要因为笔迹原因排除掉这名嫌犯\n\n1623\n01:50:41.750 --> 01:50:45.580\n“黛琳的姐姐，琳达\n对方呼吸沉重，乔治”\n\n1624\n01:50:46.970 --> 01:50:49.130\n“那是个怪人。乔治”\n\n1625\n01:50:51.060 --> 01:50:54.170\n感激不尽\n\n1626\n01:50:54.390 --> 01:50:57.050\n公事包，谢啦\n\n1627\n01:50:59.270 --> 01:51:01.510\n-嗨，杰克\n-嗨，巴渥\n\n1628\n01:51:01.730 --> 01:51:03.390\n-那是谁？\n-葛雷史密斯\n\n1629\n01:51:03.610 --> 01:51:06.940\n漫画家，认为他能够破案\n\n1630\n01:51:08.910 --> 01:51:09.900\n很好呀\n\n1631\n01:51:10.410 --> 01:51:12.980\n交通事故应该不会影响\n大部分的开车族\n\n1632\n01:51:13.200 --> 01:51:16.070\n37号高速公路在瓦列霍和\n纳伐洛之间有事故\n\n1633\n01:51:16.290 --> 01:51:19.490\n一辆油罐车在今晚翻车\n\n1634\n01:51:21.000 --> 01:51:22.950\n黛琳被跟踪，害怕乔治瓦特\n\n1635\n01:51:23.170 --> 01:51:24.410\n匿名电话\n\n1636\n01:51:28.800 --> 01:51:30.420\n开枪当晚\n\n1637\n01:51:30.640 --> 01:51:32.420\n丈夫、公公\n\n1638\n01:51:32.640 --> 01:51:34.250\n沉重的呼吸声\n\n1639\n01:51:40.650 --> 01:51:42.890\n-谢谢你跟我见面\n-我不是来跟你见面的\n\n1640\n01:51:43.110 --> 01:51:45.350\n我们只是碰巧一起坐在这里\n\n1641\n01:51:45.570 --> 01:51:48.100\n我只有五分钟，我还得回总部\n\n1642\n01:51:48.320 --> 01:51:51.440\n就你所知，你在进行调查时\n\n1643\n01:51:51.660 --> 01:51:54.230\n有人找过麦克梅休\n让他看嫌犯的照片吗？\n\n1644\n01:51:54.450 --> 01:51:55.440\n为什么？\n\n1645\n01:51:55.660 --> 01:51:58.530\n他是唯一看过十二宫杀手的生还者\n\n1646\n01:51:58.750 --> 01:52:01.120\n你为什么要问我？\n梅休和黛琳案隶属瓦列霍管辖\n\n1647\n01:52:01.330 --> 01:52:03.740\n我只调查保罗史坦，剩四分钟\n\n1648\n01:52:03.960 --> 01:52:06.370\n黛琳费伦曾被跟踪\n\n1649\n01:52:06.590 --> 01:52:08.960\n我知道穆拉斯锁定一名嫌犯\n乔治瓦特\n\n1650\n01:52:09.170 --> 01:52:12.790\n他还说黛琳在餐馆也有很多仰慕者\n\n1651\n01:52:13.010 --> 01:52:14.630\n-她很有人缘\n-的确是\n\n1652\n01:52:14.850 --> 01:52:17.800\n后来她和老公搬到新家\n\n1653\n01:52:18.020 --> 01:52:20.180\n有天晚上他们办了油漆派对\n\n1654\n01:52:20.390 --> 01:52:23.390\n-什么是油漆派对？\n-一堆朋友来帮忙油漆的派对\n\n1655\n01:52:23.610 --> 01:52:26.100\n-听起来很烂\n-假设\n\n1656\n01:52:26.320 --> 01:52:28.480\n来的人并不是瓦特\n\n1657\n01:52:28.690 --> 01:52:30.310\n而且黛琳很怕他\n\n1658\n01:52:30.530 --> 01:52:32.400\n你认为黛琳认识十二宫杀手？\n\n1659\n01:52:32.610 --> 01:52:36.730\n他认识黛琳，或许梅休也认识他\n\n1660\n01:52:36.950 --> 01:52:38.610\n有可能，但是梅休落跑了\n\n1661\n01:52:38.830 --> 01:52:42.160\n你想靠黛琳找到十二宫杀手\n就要用别的方法\n\n1662\n01:52:42.370 --> 01:52:45.200\n我有别的方法\n黛琳被谋杀当晚的通联纪录\n\n1663\n01:52:45.420 --> 01:52:48.500\n-十二宫杀手有打给警方\n-不，大卫，当晚还有四通电话\n\n1664\n01:52:48.710 --> 01:52:52.040\n两通打到黛琳的家\n一通打给黛琳小叔，一通打给她公公\n\n1665\n01:52:52.260 --> 01:52:55.170\n只有沉重的呼吸声\n电话从半夜一点半开始打\n\n1666\n01:52:55.390 --> 01:52:58.880\n当时黛琳家人不知道她已遇害\n\n1667\n01:52:59.100 --> 01:53:01.130\n-这全在瓦列霍的档案\n-是的\n\n1668\n01:53:01.350 --> 01:53:03.430\n-可恶\n-这并非完全是巧合吧？\n\n1669\n01:53:03.650 --> 01:53:07.260\n黛琳被害的九十分钟后\n全家人都接到\n\n1670\n01:53:07.480 --> 01:53:09.270\n同一通恶作剧电话\n\n1671\n01:53:09.490 --> 01:53:12.980\n所以十二宫杀手不是随机杀死那对情侣\n然后才认出黛琳\n\n1672\n01:53:13.200 --> 01:53:15.060\n就是他故意杀死黛琳的\n\n1673\n01:53:15.280 --> 01:53:18.980\n无论如何，十二宫杀手一定认识黛琳\n\n1674\n01:53:20.250 --> 01:53:22.530\n非常好，罗伯\n\n1675\n01:53:22.750 --> 01:53:25.410\n既然找不到梅休\n或许我可以找黛琳的姐姐\n\n1676\n01:53:25.630 --> 01:53:27.780\n也许她知道神秘男子是谁\n\n1677\n01:53:28.000 --> 01:53:31.120\n试试看，我得走了。她很可爱\n\n1678\n01:53:34.590 --> 01:53:38.880\n很有趣，你提到\n十二宫杀手打到被害者家里\n\n1679\n01:53:39.100 --> 01:53:42.050\n-他在旧金山也干过一次\n-什么？他打给谁？\n\n1680\n01:53:42.270 --> 01:53:45.720\n不能说，这是机密\n\n1681\n01:53:46.610 --> 01:53:48.760\n也许梅尔文贝利能告诉你\n\n1682\n01:53:51.780 --> 01:53:55.850\n梅尔文贝利，该怎么联络他？\n\n1683\n01:53:56.490 --> 01:53:58.940\n-他马上就会回家了\n-没关系\n\n1684\n01:53:59.160 --> 01:54:01.530\n我才等了两个小时…\n\n1685\n01:54:01.750 --> 01:54:03.490\n他通常不会这么晚回家\n\n1686\n01:54:03.710 --> 01:54:06.910\n饼干，谢谢，看起来很好吃\n\n1687\n01:54:07.130 --> 01:54:08.950\n你是来谈公事吗？\n\n1688\n01:54:09.170 --> 01:54:11.160\n我在写一本关于十二宫杀手的书\n\n1689\n01:54:11.380 --> 01:54:13.910\n我记得他，我跟他谈过\n\n1690\n01:54:14.130 --> 01:54:18.750\n-你跟贝利先生谈过十二宫杀手案？\n-不是，十二宫杀手打过电话来\n\n1691\n01:54:18.970 --> 01:54:21.960\n他说那天是他的生日，非得杀人不可\n\n1692\n01:54:22.180 --> 01:54:25.220\n等一下，他说那天是他生日？\n\n1693\n01:54:25.440 --> 01:54:28.260\n对，你要喝什么吗？\n\n1694\n01:54:29.650 --> 01:54:31.310\n那是什么时候的事？\n\n1695\n01:54:32.030 --> 01:54:34.270\n好几年前啰\n\n1696\n01:54:34.860 --> 01:54:38.940\n贝利先生圣诞节去渡假一星期\n\n1697\n01:54:39.160 --> 01:54:41.570\n十二宫杀手打来要找贝利先生\n\n1698\n01:54:41.790 --> 01:54:43.070\n我说他人不在家\n\n1699\n01:54:43.290 --> 01:54:45.820\n他说“今天我生日 ，我要杀人”\n\n1700\n01:54:46.040 --> 01:54:48.030\n然后就挂了电话\n\n1701\n01:54:48.250 --> 01:54:49.780\n之后信件就寄来了\n\n1702\n01:54:50.000 --> 01:54:54.080\n电话是12月20日\n信寄来之前打的？\n\n1703\n01:54:54.300 --> 01:54:56.040\n贝利先生去渡假一个星期？\n\n1704\n01:54:56.260 --> 01:54:59.880\n圣诞节当天才回来\n那天不适合工作\n\n1705\n01:55:00.100 --> 01:55:01.670\n那他就是18号离开的\n\n1706\n01:55:03.180 --> 01:55:06.010\n-我有帮到忙吗？\n-她说那天是他的生日\n\n1707\n01:55:06.230 --> 01:55:08.800\n现在你就得去证实了，不是么？\n\n1708\n01:55:09.020 --> 01:55:11.430\n我该怎么做？\n\n1709\n01:55:11.650 --> 01:55:14.520\n我没有问过她话，也许我搭档有\n\n1710\n01:55:14.740 --> 01:55:17.690\n我要怎么联络你搭档？\n没办法，他不想再扯进来\n\n1711\n01:55:17.910 --> 01:55:19.980\n我也觉得他应该抽身\n\n1712\n01:55:20.200 --> 01:55:21.270\n那我该如何确认？\n\n1713\n01:55:21.490 --> 01:55:24.070\n假如我搭档跟司法部提过此事\n\n1714\n01:55:24.290 --> 01:55:27.740\n他们应该有报告，这是正常程序\n\n1715\n01:55:28.250 --> 01:55:30.160\n-好吧\n-是倪梅尔\n\n1716\n01:55:30.380 --> 01:55:32.580\n-谢谢\n-再见\n\n1717\n01:55:32.790 --> 01:55:35.040\n-我只要确认一个日期\n-葛先生\n\n1718\n01:55:35.260 --> 01:55:38.250\n日期是在12月18到20日之间\n\n1719\n01:55:38.470 --> 01:55:41.750\n好吧，我参一脚\n假设真的有这通电话\n\n1720\n01:55:41.970 --> 01:55:46.010\n而且是十二宫杀手本人打的\n他为什么愿意说出自己的生日？\n\n1721\n01:55:46.220 --> 01:55:48.010\n而且12月18日没有人遇害\n\n1722\n01:55:48.230 --> 01:55:51.680\n就像他扬言要在周末\n杀死一打人一样\n\n1723\n01:55:51.900 --> 01:55:53.850\n炸毁校车或射杀学童也没发生\n\n1724\n01:55:54.070 --> 01:55:56.850\n-葛先生，他是个骗子\n-也许他犯了错\n\n1725\n01:55:57.240 --> 01:56:01.480\n如果他没说谎，电话也是他打的\n只是没料到接电话的是个好人\n\n1726\n01:56:01.700 --> 01:56:02.900\n这么多也许？\n\n1727\n01:56:03.120 --> 01:56:06.400\n老实说，比尔查过这条线索\n\n1728\n01:56:06.620 --> 01:56:09.030\n我们很重视这条线索\n\n1729\n01:56:09.250 --> 01:56:12.320\n没有一个嫌犯的生日符合\n\n1730\n01:56:12.540 --> 01:56:14.830\n比尔阿姆斯壮\n\n1731\n01:56:20.220 --> 01:56:24.250\n我给你一个建议\n你的搜查方向错了\n\n1732\n01:56:24.470 --> 01:56:27.300\n笔迹和指纹才是确切的证据\n\n1733\n01:56:27.520 --> 01:56:28.550\n去找这些证据\n\n1734\n01:56:29.810 --> 01:56:31.220\n嘿\n\n1735\n01:56:39.150 --> 01:56:41.350\n今天还好吗？\n\n1736\n01:56:41.570 --> 01:56:43.060\n很累\n\n1737\n01:56:47.620 --> 01:56:48.780\n莫瑞尔是谁？\n\n1738\n01:56:49.000 --> 01:56:51.610\n他是位出色的笔迹鉴定专家\n\n1739\n01:56:51.830 --> 01:56:55.160\n他打来说明天早上七点能见你\n\n1740\n01:56:55.380 --> 01:56:56.660\n太好了\n\n1741\n01:56:56.880 --> 01:56:58.080\n你早上会请假？\n\n1742\n01:56:58.300 --> 01:57:00.370\n一个小时吧\n\n1743\n01:57:01.260 --> 01:57:02.540\n到沙加缅度要两个小时\n\n1744\n01:57:04.680 --> 01:57:06.800\n-真的吗？\n-真的\n\n1745\n01:57:07.010 --> 01:57:08.460\n这是什么？\n\n1746\n01:57:08.680 --> 01:57:11.090\n这是一篇文章\n\n1747\n01:57:11.310 --> 01:57:14.680\n“罗伯葛雷和出版社\n洽谈十二宫杀手一书”\n\n1748\n01:57:14.900 --> 01:57:16.010\n是啊\n\n1749\n01:57:16.230 --> 01:57:20.390\n文章都是你搜集十二宫杀手的资料\n这就是这篇文章的题材\n\n1750\n01:57:20.610 --> 01:57:22.560\n这种事我并不想让人知道\n\n1751\n01:57:22.780 --> 01:57:23.900\n怎么，你觉得很丢脸？\n\n1752\n01:57:24.110 --> 01:57:26.940\n罗伯，我们都知道十二宫杀手会做什么？\n\n1753\n01:57:28.080 --> 01:57:29.570\n他会看《旧金山纪事报》？\n\n1754\n01:57:29.790 --> 01:57:32.530\n但是他从来不看贺伯肯恩的专栏\n\n1755\n01:57:36.500 --> 01:57:38.620\n-喂？\n-葛先生？\n\n1756\n01:57:38.840 --> 01:57:41.290\n你是今天文章里提到的罗伯？\n\n1757\n01:57:41.510 --> 01:57:42.620\n对\n\n1758\n01:57:42.840 --> 01:57:45.630\n我能告诉你谁是十二宫杀手\n\n1759\n01:57:48.390 --> 01:57:49.380\n你是谁？\n\n1760\n01:57:49.600 --> 01:57:51.590\n十二宫杀手对电影很着迷\n\n1761\n01:57:51.810 --> 01:57:54.340\n他会拍下他的犯案过程\n\n1762\n01:57:54.560 --> 01:57:57.680\n我曾经试着告诉警方，但他们不想调查\n\n1763\n01:57:57.900 --> 01:58:01.270\n你要找一个叫鲍伯冯恩的人\n\n1764\n01:58:01.490 --> 01:58:03.730\n-笔，拿笔来\n-冯-恩\n\n1765\n01:58:03.950 --> 01:58:05.730\n他是十二宫杀手的朋友\n\n1766\n01:58:05.950 --> 01:58:08.230\n冯先生不知道他朋友是凶手\n\n1767\n01:58:08.450 --> 01:58:10.730\n他替他保存影片胶卷盒\n\n1768\n01:58:10.950 --> 01:58:12.820\n那些影片就是证据\n\n1769\n01:58:13.040 --> 01:58:16.160\n朋友？这位朋友是谁？\n\n1770\n01:58:16.370 --> 01:58:19.490\n-你有这些资料应该就够了\n-拜托\n\n1771\n01:58:19.710 --> 01:58:24.000\n十二宫杀手的名字是瑞克马修\n\n1772\n01:58:26.720 --> 01:58:28.880\n你的吐司烤焦了\n\n1773\n01:58:29.890 --> 01:58:35.380\n我们在成长的阶段\n会习惯每个字母的写法\n\n1774\n01:58:35.600 --> 01:58:37.680\n我们的脑海会牢记这些写法\n\n1775\n01:58:37.900 --> 01:58:40.180\n笔迹可能会随着岁月改变\n\n1776\n01:58:40.400 --> 01:58:43.730\n但是写字的方法不会变。你懂吗？\n\n1777\n01:58:43.940 --> 01:58:45.350\n我懂\n\n1778\n01:58:46.110 --> 01:58:48.650\n但是十二宫杀手的写法会变\n\n1779\n01:58:49.910 --> 01:58:52.190\n尤其是K这个字母\n\n1780\n01:58:52.910 --> 01:58:55.610\n他第一封信的K用了两笔划\n\n1781\n01:58:55.830 --> 01:58:58.570\n-之后的信却变成三笔划\n-为什么？\n\n1782\n01:58:58.790 --> 01:59:01.620\n我们不知道\n抱歉，我得浇花\n\n1783\n01:59:01.840 --> 01:59:04.870\n几个人因为笔迹被排除嫌疑？\n\n1784\n01:59:05.090 --> 01:59:09.920\n全部，还有计程车上的指纹\n全都不符合任何人\n\n1785\n01:59:10.140 --> 01:59:14.130\n有人能够骗过笔迹检验比对吗？\n\n1786\n01:59:14.350 --> 01:59:19.050\n没有，不管十二宫杀手是谁\n绝对不是我排除嫌疑的那些人\n\n1787\n01:59:19.690 --> 01:59:23.100\n一个月前有个男人找到我家\n他看来很烦恼\n\n1788\n01:59:23.440 --> 01:59:25.890\n他叫瓦勒斯佩尼\n\n1789\n01:59:26.110 --> 01:59:30.400\n他说他认识十二宫杀手，还给了名字\n\n1790\n01:59:30.620 --> 01:59:33.280\n-瑞克，瑞克什么的\n-瑞克马修？\n\n1791\n01:59:34.790 --> 01:59:37.740\n-是啊\n-同一个人也打了电话给我\n\n1792\n01:59:37.960 --> 01:59:42.530\n他一走我就查我的档案\n我没排除瑞克马修的嫌疑\n\n1793\n01:59:49.720 --> 01:59:51.170\n喂？\n\n1794\n01:59:55.970 --> 01:59:57.760\n你是谁？\n\n1795\n02:00:07.690 --> 02:00:09.440\n打错了\n\n1796\n02:00:15.870 --> 02:00:18.820\n你听过瑞克马修这名字吗？\n\n1797\n02:00:19.870 --> 02:00:23.030\n-你想找什么？\n-你有什么？\n\n1798\n02:00:23.250 --> 02:00:28.040\n其实你说出了我最爱的嫌犯名字\n\n1799\n02:00:28.630 --> 02:00:32.420\n这些话不能公开\n几年前我想采马修的指纹\n\n1800\n02:00:32.640 --> 02:00:34.790\n我给他一张照片\n他看了一下\n\n1801\n02:00:35.010 --> 02:00:36.800\n还给我的时候说\n\n1802\n02:00:37.020 --> 02:00:39.380\n“天啊，上面都是我的指纹”\n\n1803\n02:00:39.600 --> 02:00:41.890\n然后就把指纹擦掉\n\n1804\n02:00:42.100 --> 02:00:43.930\n你为什么没有比对他的笔迹？\n\n1805\n02:00:44.150 --> 02:00:46.350\n因为后来采到他的指纹\n\n1806\n02:00:46.570 --> 02:00:48.930\n不符合计程车上那枚指纹\n\n1807\n02:00:49.150 --> 02:00:50.980\n-凶手就不是他\n-也许是，也许不是\n\n1808\n02:00:51.200 --> 02:00:53.190\n什么意思？\n\n1809\n02:00:53.410 --> 02:00:55.440\n十二宫杀手在现场留下一对手套\n\n1810\n02:00:55.660 --> 02:00:57.610\n如果他知道要戴手套犯案\n\n1811\n02:00:57.830 --> 02:01:00.280\n怎么会不小心留下指纹？\n\n1812\n02:01:00.500 --> 02:01:02.030\n指纹印在死者的血迹上面\n\n1813\n02:01:02.250 --> 02:01:06.200\n也许是旁观者的指纹\n或是刑警不小心留下的指纹\n\n1814\n02:01:06.420 --> 02:01:08.500\n这枚指纹排除了2500名嫌犯\n\n1815\n02:01:08.710 --> 02:01:11.410\n-所以才同时比对笔迹\n-除了瑞克马修\n\n1816\n02:01:11.630 --> 02:01:14.420\n旧金山刑警在他家窗户看到字迹\n\n1817\n02:01:14.640 --> 02:01:17.710\n觉得不像十二宫杀手的笔迹\n于是就不去管他了\n\n1818\n02:01:17.930 --> 02:01:20.380\n他们怎么知道那是瑞克的字迹?\n\n1819\n02:01:20.600 --> 02:01:22.800\n我也这么想\n\n1820\n02:01:23.020 --> 02:01:25.050\n瑞克马修是个海军\n\n1821\n02:01:25.270 --> 02:01:29.180\n接受过编码训练\n他也在一家电影院当放映师\n\n1822\n02:01:29.400 --> 02:01:31.520\n那我该怎么拿到瑞克的笔迹？\n\n1823\n02:01:31.740 --> 02:01:36.400\n三种方法\n一，申请搜索票，你拿不到\n\n1824\n02:01:36.620 --> 02:01:38.230\n-第二是他自愿提供，不可能\n-第三种方法呢？\n\n1825\n02:01:39.740 --> 02:01:41.440\n你自己想办法啰\n\n1826\n02:01:41.660 --> 02:01:44.360\n我没有好建议，你拿到我就比对\n\n1827\n02:01:44.580 --> 02:01:48.120\n-其它的就要靠你自己\n-那个去找你的人?\n\n1828\n02:01:48.340 --> 02:01:49.620\n打给我的那个人？\n\n1829\n02:01:49.840 --> 02:01:52.290\n你是说瓦勒斯佩尼？\n\n1830\n02:01:52.510 --> 02:01:54.790\n他有留下电话号码吗？\n\n1831\n02:02:03.730 --> 02:02:07.050\n-喂？\n-嗨，我是罗伯葛雷史密斯\n\n1832\n02:02:07.270 --> 02:02:10.310\n-你怎么找到我？\n-我需要瑞克马修的笔迹样本\n\n1833\n02:02:10.530 --> 02:02:11.810\n我说过，冯恩\n\n1834\n02:02:12.030 --> 02:02:14.640\n佩尼先生，如果瑞克是十二宫杀手\n\n1835\n02:02:14.860 --> 02:02:17.310\n我就需要他的笔迹当证据\n\n1836\n02:02:17.530 --> 02:02:19.610\n你到底能不能帮忙？\n\n1837\n02:02:20.870 --> 02:02:25.320\n瑞克替冯恩工作的电影院\n\n1838\n02:02:25.620 --> 02:02:27.450\n-划过一些海报，我会寄一张给你\n-谢谢\n\n1839\n02:02:37.550 --> 02:02:38.590\n我需要更多样本\n\n1840\n02:02:38.800 --> 02:02:41.250\n-好，但他是吗？\n-这是我目前看过最接近的\n\n1841\n02:02:41.470 --> 02:02:45.050\n我们必须小心行事\n我们要指认的这个人是十二宫杀手\n\n1842\n02:02:45.270 --> 02:02:48.180\n我能拿到更多样本\n只要找到冯恩就能找到琳达\n\n1843\n02:02:48.400 --> 02:02:51.720\n我是说，琳达是黛琳的姐姐\n我去过监理处\n\n1844\n02:02:51.940 --> 02:02:56.100\n跟她父母谈过\n不过没有人知道她在哪里\n\n1845\n02:02:56.320 --> 02:03:00.730\n葛先生\n大部分的字迹都符合\n\n1846\n02:03:00.950 --> 02:03:03.940\n不过我最怕的是不符合的部分\n\n1847\n02:03:04.160 --> 02:03:06.200\n-什么意思？\n-海报上…\n\n1848\n02:03:06.410 --> 02:03:09.700\n唯一不符合的字母…\n\n1849\n02:03:09.920 --> 02:03:11.700\n就是K\n\n1850\n02:03:13.340 --> 02:03:16.620\n你没有卡通动物饼干吧？\n\n1851\n02:03:17.510 --> 02:03:21.250\n第五小组，请陶希打回总部\n\n1852\n02:03:29.020 --> 02:03:32.640\n1978年4月25日 加州 旧金山\n\n1853\n02:03:32.860 --> 02:03:35.140\n-勤务中心\n-大卫陶希\n\n1854\n02:03:35.360 --> 02:03:37.060\n我帮你接\n\n1855\n02:03:37.700 --> 02:03:39.230\n-大卫\n-什么事？\n\n1856\n02:03:39.450 --> 02:03:41.310\n《旧金山纪事报》的达菲詹宁在总部\n\n1857\n02:03:41.530 --> 02:03:43.610\n早上寄来的，你最好看看\n\n1858\n02:03:43.830 --> 02:03:44.820\n看什么？\n\n1859\n02:03:45.040 --> 02:03:47.570\n十二宫杀手的信，上面提到你\n\n1860\n02:03:47.790 --> 02:03:49.700\n好吧，好吧\n\n1861\n02:03:51.040 --> 02:03:55.250\n糟糕。好吧，快点啊，法院\n\n1862\n02:03:55.550 --> 02:03:59.460\n快点，快，快\n\n1863\n02:04:04.970 --> 02:04:06.170\n大卫\n\n1864\n02:04:06.810 --> 02:04:08.800\n你有带在身上吗？\n\n1865\n02:04:12.400 --> 02:04:14.680\n我是十二宫杀手，我回来了\n\n1866\n02:04:14.900 --> 02:04:17.770\n告诉贺伯我还在，一直都在\n\n1867\n02:04:17.990 --> 02:04:20.770\n城市里的猪头警察陶希\n很有一套，不过我更聪明\n\n1868\n02:04:20.990 --> 02:04:23.940\n他迟早会累了，然后放过我\n\n1869\n02:04:24.160 --> 02:04:26.780\n我等着有人把我拍成电影\n谁会饰演我呢？\n\n1870\n02:04:27.000 --> 02:04:29.400\n现在由我掌控局面\n\n1871\n02:04:29.620 --> 02:04:32.160\n他们来自风纪组\n\n1872\n02:04:34.000 --> 02:04:35.830\n我们得谈谈\n\n1873\n02:04:36.050 --> 02:04:37.330\n晚上好。新闻头条\n\n1874\n02:04:37.550 --> 02:04:39.910\n旧金山警局证实\n\n1875\n02:04:40.130 --> 02:04:44.170\n自称十二宫杀手并吓坏湾区的凶手\n\n1876\n02:04:44.390 --> 02:04:47.010\n51个月后打破沉默\n\n1877\n02:04:47.220 --> 02:04:49.720\n他在信中提到 “我回来了”\n\n1878\n02:04:49.930 --> 02:04:53.640\n但是并没有刻意威胁市民\n\n1879\n02:04:53.860 --> 02:04:56.470\n反而想把他的故事拍成电影\n\n1880\n02:04:56.690 --> 02:04:58.730\n红萝卜很好吃\n\n1881\n02:04:59.360 --> 02:05:01.140\n-去看吧\n-信中还提到《旧金山纪事报》\n\n1882\n02:05:01.360 --> 02:05:03.730\n专栏作家贺伯\n\n1883\n02:05:03.950 --> 02:05:06.730\n和大卫陶希警探\n\n1884\n02:05:06.950 --> 02:05:07.940\n我也可以去吗？\n\n1885\n02:05:08.160 --> 02:05:10.860\n好，不过你得回来吃完一半晚餐\n\n1886\n02:05:11.080 --> 02:05:13.700\n我们有更多密码杀手的报导\n\n1887\n02:05:13.920 --> 02:05:16.330\n镜头交给艾伦佛列曼\n\n1888\n02:05:16.540 --> 02:05:19.750\n谢谢你，艾瑞克\n《旧金山纪事报》专栏作家莫宝\n\n1889\n02:05:19.960 --> 02:05:22.750\n认为这封信是伪造的\n\n1890\n02:05:22.970 --> 02:05:27.090\n而伪造这封信的人\n就是长年追捕十二宫杀手的警探\n\n1891\n02:05:27.310 --> 02:05:30.720\n大卫陶希\n莫宝这位非常受尊重的作家\n\n1892\n02:05:30.930 --> 02:05:35.010\n公开表示他相信陶希伪造这封信\n\n1893\n02:05:35.230 --> 02:05:37.100\n是为了引人注意\n\n1894\n02:05:37.320 --> 02:05:40.350\n莫宝把大卫写成他专栏的角色\n\n1895\n02:05:40.570 --> 02:05:43.850\n大卫觉得很过瘾\n于是匿名写信\n\n1896\n02:05:44.070 --> 02:05:46.190\n请莫宝继续写这个角色\n\n1897\n02:05:46.410 --> 02:05:49.530\n就像假装粉丝写信给自己而已\n\n1898\n02:05:49.740 --> 02:05:51.860\n不过那封信不是大卫写的\n\n1899\n02:05:52.080 --> 02:05:55.030\n我相信不是他\n应该也不会有什么影响\n\n1900\n02:05:55.250 --> 02:05:56.370\n不会有影响？\n\n1901\n02:05:56.580 --> 02:05:58.620\n他被踢出重案组\n\n1902\n02:05:58.840 --> 02:06:02.040\n他们甚至逼他像罪犯一样留下笔迹\n\n1903\n02:06:02.260 --> 02:06:05.580\n-我能跟他谈谈吗？\n-不行\n\n1904\n02:06:05.800 --> 02:06:09.090\n请你问他有没有调查过\n一个叫瑞克马修的人\n\n1905\n02:06:09.310 --> 02:06:11.260\n你满脑子只有这个案子吗？\n\n1906\n02:06:11.470 --> 02:06:15.010\n葛先生，莫宝在你的报社工作\n\n1907\n02:06:20.730 --> 02:06:24.440\n-这女孩想要修音乐课？\n-大卫，大卫\n\n1908\n02:06:25.780 --> 02:06:28.060\n-好，待会儿见\n-我待会儿再找你\n\n1909\n02:06:28.280 --> 02:06:30.400\n别再打到我家，懂吗？\n\n1910\n02:06:30.620 --> 02:06:32.190\n我只要你帮我找到琳达\n\n1911\n02:06:32.410 --> 02:06:35.070\n-老天爷\n-一下子就好\n\n1912\n02:06:36.460 --> 02:06:38.830\n听着，我们做过一些笔迹比对\n\n1913\n02:06:39.040 --> 02:06:41.120\n-“我们” 是谁？\n-我和莫瑞尔\n\n1914\n02:06:41.340 --> 02:06:44.500\n莫瑞尔？\n他被鉴识组开除后\n\n1915\n02:06:44.720 --> 02:06:47.290\n-他和保罗一样变成酒鬼\n-他退休了\n\n1916\n02:06:47.510 --> 02:06:48.960\n他这么跟你说吗？\n\n1917\n02:06:49.180 --> 02:06:53.090\n-你是说他错了吗？\n-我是说别再打到我家\n\n1918\n02:06:53.890 --> 02:06:55.680\n-我们比对瑞克马修的笔迹\n-不，罗伯\n\n1919\n02:06:55.890 --> 02:06:59.470\n-我知道你认为不是他\n-我只知道我不想再说下去\n\n1920\n02:06:59.690 --> 02:07:01.890\n我找不到梅休或琳达\n\n1921\n02:07:02.110 --> 02:07:03.600\n-罗伯，闭嘴\n-什么？什么？\n\n1922\n02:07:03.820 --> 02:07:07.440\n你再调查下去会筋疲力尽\n也会走进死胡同\n\n1923\n02:07:07.660 --> 02:07:10.610\n十二宫杀手说他不会公布他的对象\n他只会直接杀人\n\n1924\n02:07:10.830 --> 02:07:13.650\n你知道逮到他的机率有多小？\n\n1925\n02:07:13.870 --> 02:07:17.820\n而且时间过了这么久\n很多证物都遗失了\n\n1926\n02:07:18.040 --> 02:07:20.870\n证人也老了，忘记很多事\n\n1927\n02:07:21.340 --> 02:07:25.330\n我当了25年警察， 12年\n凶案警探\n\n1928\n02:07:25.550 --> 02:07:27.290\n-你靠什么维生？\n-你明明知道\n\n1929\n02:07:27.510 --> 02:07:30.040\n-你是个漫画家\n-你想说什么？\n\n1930\n02:07:30.260 --> 02:07:34.340\n逮捕十二宫杀手是我的工作\n不是你的\n\n1931\n02:07:36.600 --> 02:07:38.970\n-他还在逍遥法外，大卫\n-我不管这个案子了\n\n1932\n02:07:39.190 --> 02:07:41.220\n也跟你没关系了\n\n1933\n02:07:47.360 --> 02:07:49.980\n1970年9月24日呢？\n\n1934\n02:07:50.200 --> 02:07:54.150\n-那是哪一起命案？\n-太浩湖护士失踪\n\n1935\n02:07:56.450 --> 02:07:59.780\n-春分点的前一天，爸？\n-划个记号\n\n1936\n02:08:00.000 --> 02:08:03.280\n还有1971年6月19日\n\n1937\n02:08:03.500 --> 02:08:06.580\n一定很接近夏至\n\n1938\n02:08:08.760 --> 02:08:13.210\n大伙儿，别告诉妈妈这件事哦\n\n1939\n02:08:13.890 --> 02:08:17.220\n你跟妈为什么不一起睡？\n\n1940\n02:08:21.440 --> 02:08:24.010\n葛先生，我是那帕警局的肯恩\n\n1941\n02:08:24.230 --> 02:08:28.180\n你好，警官，谢谢你回电\n\n1942\n02:08:28.400 --> 02:08:30.020\n我能帮什么忙？\n\n1943\n02:08:30.240 --> 02:08:33.060\n我们交叉比对月亮周期\n\n1944\n02:08:33.280 --> 02:08:34.730\n和十二宫杀手凶杀案的时间表\n\n1945\n02:08:34.950 --> 02:08:38.440\n1969年以后，月亮周期一开始\n就有一起命案\n\n1946\n02:08:38.660 --> 02:08:41.860\n和一封信\n或是未破解的谋杀案\n\n1947\n02:08:42.080 --> 02:08:44.910\n-谁跟你调查这件事？\n-我的同事\n\n1948\n02:08:45.130 --> 02:08:46.290\n爸？\n\n1949\n02:08:47.300 --> 02:08:49.660\n-请你稍等一下\n-爸？\n\n1950\n02:08:50.170 --> 02:08:52.130\n-什么事？\n-这是什么？\n\n1951\n02:08:55.930 --> 02:08:59.090\n收到十二宫杀手最后信件的十年间\n\n1952\n02:08:59.310 --> 02:09:02.430\n每个联邦单位都想破解密码\n\n1953\n02:09:02.650 --> 02:09:03.850\n1979年8月9日 加州 旧金山\n\n1954\n02:09:04.060 --> 02:09:07.970\n在这些单位都失败之后\n一名漫画家却成功破解密码\n\n1955\n02:09:08.190 --> 02:09:10.440\n你是怎么办到的？\n\n1956\n02:09:10.650 --> 02:09:13.690\n参考图书馆的大量书籍\n\n1957\n02:09:13.910 --> 02:09:17.530\n我也喜欢解码，我只是…\n\n1958\n02:09:17.740 --> 02:09:19.900\n臭图书馆\n\n1959\n02:09:20.120 --> 02:09:22.910\n只要努力就一定能成功\n\n1960\n02:09:25.790 --> 02:09:29.540\nJ字开头？女子监狱？\n\n1961\n02:09:30.380 --> 02:09:32.210\n谢谢你\n\n1962\n02:09:33.800 --> 02:09:36.500\n找到琳达了 ，她在坐牢。很棒吧？\n\n1963\n02:09:36.720 --> 02:09:38.670\n-你为什么要这样？\n-她会指认瑞克\n\n1964\n02:09:38.890 --> 02:09:42.180\n-你在说什么？\n-你上了电视\n\n1965\n02:09:42.390 --> 02:09:44.340\n你让他认得你的长相\n\n1966\n02:09:44.560 --> 02:09:45.600\n老婆，你太紧张了\n\n1967\n02:09:45.810 --> 02:09:48.770\n那是谁每周半夜打到家里来的？\n\n1968\n02:09:48.980 --> 02:09:51.060\n谁也不是\n\n1969\n02:09:51.900 --> 02:09:55.020\n-你要怎样才肯罢休？\n-现在不能谈\n\n1970\n02:09:55.240 --> 02:09:56.520\n我得去见鲍伯冯恩\n\n1971\n02:09:56.740 --> 02:09:59.820\n不行，我们现在就要谈\n\n1972\n02:10:00.040 --> 02:10:04.160\n你几时才会罢手？\n等你找到他，逮捕他？\n\n1973\n02:10:04.370 --> 02:10:06.780\n-严肃一点\n-我是很严肃\n\n1974\n02:10:08.800 --> 02:10:13.080\n我得知道他究竟是谁\n\n1975\n02:10:13.760 --> 02:10:17.340\n我得站在他面前，看着他的眼睛\n\n1976\n02:10:17.550 --> 02:10:20.460\n知道他就是十二宫杀手\n\n1977\n02:10:21.140 --> 02:10:23.470\n这比你家人的安危更重要？\n\n1978\n02:10:23.680 --> 02:10:25.760\n当然不是\n\n1979\n02:10:27.190 --> 02:10:30.100\n为什么？你为什么要这么做？\n\n1980\n02:10:31.190 --> 02:10:32.560\n为什么？\n\n1981\n02:10:34.450 --> 02:10:36.060\n因为没有人肯做\n\n1982\n02:10:36.280 --> 02:10:37.730\n这理由不够好\n\n1983\n02:10:38.570 --> 02:10:40.020\n说完了吗？我能走了吗？\n\n1984\n02:10:55.840 --> 02:10:57.830\n-冯先生？\n-葛先生？\n\n1985\n02:10:58.050 --> 02:11:00.340\n-嗯\n-你要找我谈？\n\n1986\n02:11:00.560 --> 02:11:02.760\n对，街角有一家咖啡馆\n\n1987\n02:11:02.970 --> 02:11:06.010\n-不如到我家\n-我不想麻烦你\n\n1988\n02:11:06.230 --> 02:11:08.930\n一点也不会，你停在哪儿？\n\n1989\n02:11:09.150 --> 02:11:10.180\n就在那里\n\n1990\n02:11:10.400 --> 02:11:12.010\n跟着我的车\n\n1991\n02:11:13.570 --> 02:11:14.770\n好吧\n\n1992\n02:11:32.630 --> 02:11:34.250\n小心脚下\n\n1993\n02:11:38.840 --> 02:11:42.040\n-很棒的房子\n-谢谢\n\n1994\n02:11:42.260 --> 02:11:43.960\n感觉很简朴\n\n1995\n02:11:44.180 --> 02:11:47.050\n-夹克可以给我吗？\n-不用 ，谢谢，我很好\n\n1996\n02:11:47.270 --> 02:11:50.140\n那就这边请\n\n1997\n02:11:52.190 --> 02:11:53.810\n-请坐\n-谢谢\n\n1998\n02:11:54.030 --> 02:11:56.390\n-喝点茶吗？\n-不用了\n\n1999\n02:11:56.610 --> 02:11:58.810\n-你确定？\n-确定\n\n2000\n02:11:59.030 --> 02:12:02.650\n我想问你关于一部电影\n\n2001\n02:12:02.870 --> 02:12:06.940\n你在电影院当琴师时放过的电影\n《最危险的游戏》\n\n2002\n02:12:07.160 --> 02:12:10.410\n那是经典电影，1932年\n\n2003\n02:12:10.630 --> 02:12:15.120\n费芮、乔麦克雷、莱斯里班克斯\n我们放映了很多次\n\n2004\n02:12:15.340 --> 02:12:17.000\n是68还是69年？\n\n2005\n02:12:18.630 --> 02:12:20.540\n我得查查记录，怎么了？\n\n2006\n02:12:20.760 --> 02:12:22.630\n你记得十二宫杀手吗？\n\n2007\n02:12:25.140 --> 02:12:27.340\n你想问瑞克马修，是吧？\n\n2008\n02:12:27.560 --> 02:12:31.260\n-他曾是那里的放映师，对吗？\n-有一段时间\n\n2009\n02:12:31.480 --> 02:12:35.180\n但是我没跟他保持连络\n\n2010\n02:12:35.400 --> 02:12:37.600\n好，十二宫杀手有一次\n\n2011\n02:12:37.820 --> 02:12:40.350\n杀人时\n跟那部电影有关联\n\n2012\n02:12:40.570 --> 02:12:42.270\n你是说那个符号？\n\n2013\n02:12:43.700 --> 02:12:45.360\n等等\n\n2014\n02:12:45.580 --> 02:12:50.530\n十二宫杀手的符号\n出现在片头的倒数胶卷\n\n2015\n02:12:53.420 --> 02:12:56.080\n每次放映前都会剪掉\n\n2016\n02:12:56.300 --> 02:12:58.290\n不过影片送来的时候都会在\n\n2017\n02:12:58.510 --> 02:13:00.460\n就在这里\n\n2018\n02:13:01.010 --> 02:13:04.750\n我第一次在报上看到时就想到了\n\n2019\n02:13:05.300 --> 02:13:06.380\n我们收到线报\n\n2020\n02:13:06.600 --> 02:13:10.970\n瑞克留了一个胶卷盒给你\n还交代你不要打开\n\n2021\n02:13:11.190 --> 02:13:13.970\n关于神秘的影片胶卷盒线报\n\n2022\n02:13:15.020 --> 02:13:16.470\n是真的吗？\n\n2023\n02:13:18.280 --> 02:13:19.430\n是真的\n\n2024\n02:13:19.940 --> 02:13:22.350\n-你有打开过吗？\n-没有\n\n2025\n02:13:22.570 --> 02:13:28.070\n-我能看看吗？\n-瑞克在1972年拿回去了\n\n2026\n02:13:28.700 --> 02:13:33.240\n这条线报让你联想到\n瑞克就是十二宫杀手？\n\n2027\n02:13:33.460 --> 02:13:34.990\n胶卷盒以及海报\n\n2028\n02:13:35.210 --> 02:13:37.370\n海报？\n\n2029\n02:13:38.550 --> 02:13:40.080\n瑞克画的那张海报\n\n2030\n02:13:40.300 --> 02:13:43.250\n上面的笔迹是最接近嫌犯的笔迹\n\n2031\n02:13:43.470 --> 02:13:45.250\n海报不是瑞克画的\n\n2032\n02:13:45.470 --> 02:13:46.880\n不，他画了这张\n\n2033\n02:13:47.100 --> 02:13:51.380\n葛先生，海报是我亲笔画的\n\n2034\n02:13:51.600 --> 02:13:53.930\n那是我的笔迹\n\n2035\n02:14:01.990 --> 02:14:04.810\n我不想再占用你的时间了\n\n2036\n02:14:05.030 --> 02:14:10.320\n我去看是哪一年放映这部电影的\n\n2037\n02:14:10.540 --> 02:14:11.860\n不用了\n\n2038\n02:14:12.080 --> 02:14:16.120\n没关系，就在地下室\n\n2039\n02:14:17.250 --> 02:14:20.290\n加州不是每个人都有地下室\n\n2040\n02:14:23.010 --> 02:14:24.460\n我就有\n\n2041\n02:14:26.010 --> 02:14:28.290\n你要来吗，葛先生？\n\n2042\n02:14:39.520 --> 02:14:44.060\n原版的海报我全都自己保留\n\n2043\n02:14:45.070 --> 02:14:48.060\n你带来的那张便宜货\n\n2044\n02:14:48.280 --> 02:14:50.690\n我会糅成一团丢到后巷\n\n2045\n02:15:05.130 --> 02:15:07.250\n69年\n\n2046\n02:15:12.600 --> 02:15:13.670\n你一个人住吗？\n\n2047\n02:15:13.890 --> 02:15:19.760\n《最危险的游戏》\n1969年5月放映\n\n2048\n02:15:19.980 --> 02:15:26.270\n那大概是十二宫杀手\n寄出第一封信九星期前，对吧？\n\n2049\n02:15:29.320 --> 02:15:30.940\n对\n\n2050\n02:15:34.790 --> 02:15:38.820\n你认为他在戏院中看过那部电影后\n受到启发？\n\n2051\n02:15:45.170 --> 02:15:47.580\n你确定屋里没有别人？\n\n2052\n02:15:49.590 --> 02:15:51.750\n你想上楼去看吗？\n\n2053\n02:15:53.060 --> 02:15:54.710\n不了\n\n2054\n02:15:57.180 --> 02:16:00.510\n谢谢，非常谢谢你\n\n2055\n02:16:00.730 --> 02:16:02.390\n不用客气\n\n2056\n02:16:23.500 --> 02:16:25.120\n大门锁住了\n\n2057\n02:16:35.680 --> 02:16:36.920\n谢谢你\n\n2058\n02:16:40.060 --> 02:16:42.680\n晚安，葛先生\n\n2059\n02:17:03.000 --> 02:17:07.620\n一定有两个凶手，其中\n一个有地图，另一个杀人\n\n2060\n02:17:13.680 --> 02:17:15.130\n孩子们？\n\n2061\n02:17:34.280 --> 02:17:36.150\n我带孩子到我妈家，别打来\n\n2062\n02:17:44.250 --> 02:17:46.240\n琳达 戴布诺 桑瓦昆监狱\n\n2063\n02:17:48.500 --> 02:17:50.620\n你有五分钟的时间\n\n2064\n02:17:58.390 --> 02:18:00.010\n琳达？\n\n2065\n02:18:00.600 --> 02:18:02.470\n我是罗伯\n\n2066\n02:18:06.270 --> 02:18:08.510\n你收到我的信吗？\n\n2067\n02:18:08.730 --> 02:18:10.720\n-是什么事？\n-十二宫杀手\n\n2068\n02:18:12.400 --> 02:18:14.100\n我猜也是\n\n2069\n02:18:14.780 --> 02:18:17.230\n-你看起来有那种样子\n-什么样子？\n\n2070\n02:18:17.910 --> 02:18:20.190\n我没别的意思\n\n2071\n02:18:21.120 --> 02:18:23.780\n告诉我关于那场油漆派对\n\n2072\n02:18:24.460 --> 02:18:27.490\n我很久前就跟条子说过\n\n2073\n02:18:30.590 --> 02:18:34.290\n男人总是围绕着黛琳\n就算是婚后也一样\n\n2074\n02:18:34.510 --> 02:18:37.170\n其中有一个很怪\n\n2075\n02:18:37.390 --> 02:18:41.170\n他常从提华纳带礼物给她\n\n2076\n02:18:41.390 --> 02:18:43.920\n我也不知道她干嘛跟他交朋友\n\n2077\n02:18:44.140 --> 02:18:46.340\n不过她说他杀过人\n\n2078\n02:18:46.560 --> 02:18:47.890\n真的吗？\n\n2079\n02:18:48.110 --> 02:18:50.390\n好像是他在当兵的时候\n\n2080\n02:18:50.610 --> 02:18:52.520\n-海军？\n-应该是吧\n\n2081\n02:18:52.740 --> 02:18:54.690\n他喜欢电影？他是影痴吗？\n\n2082\n02:18:54.900 --> 02:18:57.310\n我只知道他对人没兴趣\n\n2083\n02:18:57.530 --> 02:19:00.570\n黛琳办的那个派对\n只是请大家来喝酒\n\n2084\n02:19:00.780 --> 02:19:02.230\n喝啤酒，帮忙刷漆\n\n2085\n02:19:02.450 --> 02:19:04.400\n这家伙却穿了套西装\n\n2086\n02:19:04.620 --> 02:19:07.410\n一个人整晚坐在椅子上\n\n2087\n02:19:07.620 --> 02:19:09.160\n也没跟任何人讲话\n\n2088\n02:19:09.380 --> 02:19:13.080\n黛琳叫我离他远一点。她很怕他\n\n2089\n02:19:15.470 --> 02:19:17.620\n几星期后她就死了\n\n2090\n02:19:17.840 --> 02:19:20.460\n很遗憾，你知道他的名字吗？\n\n2091\n02:19:21.390 --> 02:19:25.010\n有点像绰号，好像是史丹\n\n2092\n02:19:25.310 --> 02:19:28.260\n-瑞克？\n-不，我想不是\n\n2093\n02:19:28.480 --> 02:19:30.550\n-你确定吗？\n-确定\n\n2094\n02:19:30.770 --> 02:19:33.220\n那么久了 ，你怎么能确定？用力想\n\n2095\n02:19:33.440 --> 02:19:34.770\n我很用力在想\n\n2096\n02:19:35.530 --> 02:19:37.600\n是瑞克\n\n2097\n02:19:37.820 --> 02:19:40.730\n-不，不是\n-是瑞克，瑞克马修\n\n2098\n02:19:40.950 --> 02:19:43.280\n-不是\n-快说\n\n2099\n02:19:43.490 --> 02:19:46.280\n他不是瑞克\n\n2100\n02:19:53.050 --> 02:19:54.330\n是李\n\n2101\n02:19:57.670 --> 02:20:00.790\n-李？\n-是啊，李\n\n2102\n02:20:01.510 --> 02:20:02.800\n听起来没错\n\n2103\n02:20:07.560 --> 02:20:08.840\n警官！\n\n2104\n02:20:09.060 --> 02:20:11.430\n-你得让我进去\n-是紧急事件吗？\n\n2105\n02:20:11.650 --> 02:20:13.180\n我只要看一份档案\n\n2106\n02:20:13.400 --> 02:20:16.560\n-明早再来\n-一份档案，只要一下子\n\n2107\n02:20:16.780 --> 02:20:18.350\n穆拉斯队长！\n\n2108\n02:20:18.570 --> 02:20:21.860\n警长，我只要看一份档案！五分钟就好\n\n2109\n02:20:22.070 --> 02:20:24.270\n我知道档案在哪里\n\n2110\n02:20:25.490 --> 02:20:26.900\n拜托了\n\n2111\n02:20:40.010 --> 02:20:41.710\n我不应该跟你说话\n\n2112\n02:20:41.930 --> 02:20:44.170\n-你只有五分钟\n-好\n\n2113\n02:20:46.010 --> 02:20:47.300\n就是这里\n\n2114\n02:20:47.520 --> 02:20:51.050\n琳达说她的好朋友包括李\n\n2115\n02:20:51.270 --> 02:20:54.180\n常从提华纳带礼物给她\n\n2116\n02:20:54.400 --> 02:20:56.060\n-又怎样？\n-他认识她\n\n2117\n02:20:56.280 --> 02:20:57.890\n琳达提到李\n\n2118\n02:20:58.110 --> 02:21:02.060\n-这只是几百个名字的其中一个\n-不算什么\n\n2119\n02:21:02.570 --> 02:21:05.480\n-大卫陶希\n-他也同意我说的\n\n2120\n02:21:05.700 --> 02:21:08.650\n这项调查到此为止\n\n2121\n02:21:11.500 --> 02:21:12.950\n很抱歉\n\n2122\n02:21:21.930 --> 02:21:23.380\n喂？\n\n2123\n02:21:38.230 --> 02:21:39.520\n谁在那里？\n\n2124\n02:21:43.110 --> 02:21:45.730\n-你没回我电话\n-我有点忙\n\n2125\n02:21:46.700 --> 02:21:49.110\n是啊，看得出来\n\n2126\n02:21:50.790 --> 02:21:52.240\n书写得怎样？\n\n2127\n02:21:55.630 --> 02:21:58.040\n我试着寄这些给你\n\n2128\n02:21:58.670 --> 02:22:00.410\n我打给了报社\n\n2129\n02:22:00.630 --> 02:22:04.920\n我不再是那里的漫画家了\n\n2130\n02:22:05.140 --> 02:22:06.750\n我听说了\n\n2131\n02:22:11.390 --> 02:22:13.680\n你最后一次吃过东西是在什么时候？\n\n2132\n02:22:16.560 --> 02:22:18.220\n一切都没有意义了\n\n2133\n02:22:21.280 --> 02:22:22.730\n有过意义吗？\n\n2134\n02:22:22.950 --> 02:22:24.980\n有，曾经有\n\n2135\n02:22:25.200 --> 02:22:27.520\n罗伯，那只是一次约会\n并没有结束\n\n2136\n02:22:28.580 --> 02:22:30.190\n你真的这么想？\n\n2137\n02:22:31.580 --> 02:22:33.110\n有一点\n\n2138\n02:22:35.710 --> 02:22:37.450\n孩子们很想你\n\n2139\n02:22:37.670 --> 02:22:39.490\n我不能让他们看到我这样\n\n2140\n02:22:39.710 --> 02:22:43.790\n我也不想。做一切必要的事情\n\n2141\n02:22:44.470 --> 02:22:46.170\n了结这件事\n\n2142\n02:22:58.230 --> 02:22:59.680\n葛雷的副本\n\n2143\n02:23:03.320 --> 02:23:05.890\n亚瑟李艾伦 生日12-18-33\n\n2144\n02:23:13.660 --> 02:23:15.360\n大卫\n\n2145\n02:23:15.580 --> 02:23:17.660\n大卫，是我罗伯\n\n2146\n02:23:19.500 --> 02:23:20.910\n-大卫\n-他真跑来了？\n\n2147\n02:23:21.130 --> 02:23:22.830\n我要杀了他\n\n2148\n02:23:23.340 --> 02:23:26.330\n-大卫\n-我要报警。我的枪呢？\n\n2149\n02:23:28.340 --> 02:23:31.210\n-大卫\n-罗伯，快滚开\n\n2150\n02:23:31.430 --> 02:23:34.090\n-大卫，他犯了一个错\n-离开窗户\n\n2151\n02:23:34.310 --> 02:23:37.340\n-我到前门\n-不行\n\n2152\n02:23:38.350 --> 02:23:40.430\n-你得听听这个\n-不，我不听\n\n2153\n02:23:40.650 --> 02:23:43.060\n他只有在生日那天最脆弱\n\n2154\n02:23:43.280 --> 02:23:46.100\n-也是唯一一次泄漏身分\n-罗伯，我要报警了\n\n2155\n02:23:46.320 --> 02:23:48.150\n是亚瑟李艾伦！\n\n2156\n02:23:53.330 --> 02:23:54.690\n你那名字哪里来的？\n\n2157\n02:23:55.660 --> 02:23:57.900\n他打到贝利家， 69年12月 ，说\n“今天我生日 ，我非得杀人不可”\n\n2158\n02:23:58.120 --> 02:24:01.530\n那天是他的生日\n\n2159\n02:24:01.750 --> 02:24:04.750\n亚瑟李艾伦的生日是12月18日\n\n2160\n02:24:07.720 --> 02:24:09.330\n进来\n\n2161\n02:24:11.220 --> 02:24:14.090\n-拿去\n-谢了\n\n2162\n02:24:16.430 --> 02:24:18.260\n他写信给我，你知道吗？\n\n2163\n02:24:18.890 --> 02:24:22.930\n2500名嫌犯\n唯一写信给我的就是李艾伦\n\n2164\n02:24:24.690 --> 02:24:28.060\n-有时候嫌犯想帮忙\n-我知道，罗伯\n\n2165\n02:24:29.450 --> 02:24:32.060\n他在1975年1月因性骚扰被捕\n\n2166\n02:24:32.280 --> 02:24:33.900\n一出狱就寄信给我\n\n2167\n02:24:34.120 --> 02:24:36.780\n亲爱的大卫，需要帮忙就告诉我\n\n2168\n02:24:37.000 --> 02:24:40.360\n抱歉我不是凶手\n而信件是用打的\n\n2169\n02:24:40.580 --> 02:24:43.200\n打字并不算犯法\n\n2170\n02:24:44.500 --> 02:24:46.620\n他也认识黛琳\n\n2171\n02:24:47.590 --> 02:24:49.830\n这是瓦列霍的档案\n\n2172\n02:24:54.810 --> 02:24:58.220\n穆拉斯说他是你的头号嫌犯\n\n2173\n02:24:58.430 --> 02:25:02.970\n你花两年时间调查他\n而且没人比你更接近破案\n\n2174\n02:25:05.320 --> 02:25:07.430\n所有的证据都说不是他\n\n2175\n02:25:08.530 --> 02:25:10.640\n莫瑞尔说他的笔迹不符合\n\n2176\n02:25:10.860 --> 02:25:13.980\n那个和保罗一样满嘴酒味的莫瑞尔？\n\n2177\n02:25:15.120 --> 02:25:18.900\n是的，莫瑞尔写说这不是嫌犯的笔迹\n泰瑞也能鉴定\n\n2178\n02:25:19.120 --> 02:25:20.570\n-他的徒弟\n-就算他只是徒弟\n\n2179\n02:25:20.790 --> 02:25:22.490\n好歹他也是专家，他说\n\n2180\n02:25:22.710 --> 02:25:24.990\n“别以笔迹排除掉这名嫌犯”\n\n2181\n02:25:25.210 --> 02:25:26.830\n所以两名专家意见不同\n\n2182\n02:25:27.050 --> 02:25:30.710\n不，这是莫瑞尔的案子\n他也曾是鉴识组组长\n\n2183\n02:25:30.920 --> 02:25:35.130\n假如案子上了法庭\n辩方会让莫瑞尔证明李艾伦没罪\n\n2184\n02:25:35.350 --> 02:25:39.210\n我们也没办法把艾伦告上法庭\n因为根本没有证据\n\n2185\n02:25:39.430 --> 02:25:41.720\n怎么会没有证据？\n你看过他的密码\n\n2186\n02:25:41.940 --> 02:25:44.090\n军用长靴和手套的尺寸符合\n\n2187\n02:25:44.310 --> 02:25:47.760\n《最危险的游戏》 、十二宫杀手手表\n他当过小学老师\n\n2188\n02:25:47.980 --> 02:25:49.850\n圣诞节拼错、沾血凶刀\n\n2189\n02:25:50.070 --> 02:25:51.480\n这些都是间接证据\n\n2190\n02:25:51.700 --> 02:25:54.440\n保罗史坦的衬衫、钱包、钥匙\n\n2191\n02:25:54.660 --> 02:25:58.110\n在拖车屋里都没有找到\n\n2192\n02:26:00.700 --> 02:26:04.490\n凯萨琳说李星期五下班后\n\n2193\n02:26:04.710 --> 02:26:08.490\n就把拖车屋清空搬到圣塔罗莎\n1971年8月7日 ，星期六\n\n2194\n02:26:08.710 --> 02:26:12.120\n你是在8月4日\n到炼油厂问他话的\n\n2195\n02:26:12.340 --> 02:26:15.830\n然后48小时之后\n他就匆匆搬到另一个城市？\n\n2196\n02:26:18.050 --> 02:26:19.170\n好吧，好吧\n\n2197\n02:26:19.390 --> 02:26:21.880\n-让我们一对一比对他们的行踪\n-好\n\n2198\n02:26:22.100 --> 02:26:24.800\n亚瑟李艾伦和十二宫杀手的行踪\n\n2199\n02:26:25.020 --> 02:26:27.640\n-第一起瓦列霍命案是几时？\n-1968年圣诞节\n\n2200\n02:26:27.860 --> 02:26:30.600\n8个月前艾伦\n因骚扰学童被开除\n\n2201\n02:26:30.820 --> 02:26:32.600\n家人发现他有恋童癖\n\n2202\n02:26:32.820 --> 02:26:34.940\n-第一封信几时寄到？\n-69年7月\n\n2203\n02:26:35.160 --> 02:26:37.110\n那是在黛琳费伦的命案之后\n\n2204\n02:26:37.320 --> 02:26:39.690\n他一直寄信\n直到你去上班的地方找他\n\n2205\n02:26:39.910 --> 02:26:43.200\n后来的信\n还有没有史坦的沾血衬衫？\n\n2206\n02:26:43.410 --> 02:26:46.360\n没有，因为他害怕，把衬衫丢了\n他知道你盯上他\n\n2207\n02:26:46.580 --> 02:26:48.450\n十二宫杀手的下一封信几时出现？\n\n2208\n02:26:48.670 --> 02:26:50.830\n一直等到1974年1月\n\n2209\n02:26:51.050 --> 02:26:54.160\n他整整沉默了三年。到了74年他才安心\n\n2210\n02:26:54.380 --> 02:26:56.170\n因为大家都排除艾伦的嫌疑\n\n2211\n02:26:56.380 --> 02:27:00.840\n接着我们陆续收到十二宫杀手的三封信\n74年1月 、5月 、7月\n\n2212\n02:27:01.560 --> 02:27:04.010\n-然后又没再收到信了\n-艾伦发生什么事？\n\n2213\n02:27:08.270 --> 02:27:10.390\n他被逮捕了\n\n2214\n02:27:10.610 --> 02:27:13.810\n1975年1月\n他被送到阿塔斯卡戴罗监狱\n\n2215\n02:27:14.030 --> 02:27:16.690\n那段期间十二宫杀手没有寄一封信\n\n2216\n02:27:16.910 --> 02:27:19.520\n他几时被放出来的？\n1977年8月\n\n2217\n02:27:19.740 --> 02:27:23.360\n艾伦出狱，打了一封抱歉信\n然后呢？\n\n2218\n02:27:23.580 --> 02:27:26.610\n四年来首次接到十二宫杀手的信件\n\n2219\n02:27:32.500 --> 02:27:35.620\n所以，十二宫杀手应该认识黛琳，对吧？\n\n2220\n02:27:35.840 --> 02:27:38.120\n对，她被杀那天晚上的通话纪录\n\n2221\n02:27:38.340 --> 02:27:42.880\n因为透过瓦列霍档案纪录\n我们知道黛琳认识一名男子叫李\n\n2222\n02:27:43.100 --> 02:27:45.880\n-没错\n-因此撇开所有的巧合，罗伯\n\n2223\n02:27:46.100 --> 02:27:48.930\n你如何确定这两人是同一个李？\n\n2224\n02:27:49.150 --> 02:27:52.680\n瓦列霍虽然是小镇，但也不太小\n你怎么把这两个人凑在一块？\n\n2225\n02:27:52.900 --> 02:27:55.520\n这是一个涵盖南北加州的案件\n\n2226\n02:27:55.740 --> 02:27:58.560\n嫌犯与被害人相隔一百英里\n\n2227\n02:27:58.780 --> 02:28:00.940\n-这你同意吧？\n-同意\n\n2228\n02:28:01.870 --> 02:28:04.320\n黛琳在瓦列霍一家煎饼店工作\n\n2229\n02:28:04.540 --> 02:28:06.530\n就在田纳西和凯罗街口\n\n2230\n02:28:10.040 --> 02:28:14.240\n亚瑟李艾伦\n住在费斯诺街母亲家的地下室\n\n2231\n02:28:16.550 --> 02:28:21.080\n两栋房子距离不到50码\n\n2232\n02:28:23.350 --> 02:28:24.630\n真的么？\n\n2233\n02:28:25.930 --> 02:28:27.630\n我实际走过\n\n2234\n02:28:31.190 --> 02:28:33.140\n老天爷\n\n2235\n02:28:39.360 --> 02:28:40.980\n所以呢？\n\n2236\n02:28:44.280 --> 02:28:47.190\n-指纹、笔迹…\n-我不是在以警察的身份问你\n\n2237\n02:28:47.410 --> 02:28:49.360\n但我是个警察啊\n\n2238\n02:28:51.830 --> 02:28:53.530\n我无法证实\n\n2239\n02:28:53.750 --> 02:28:56.830\n你无法证实不表示不是真的\n\n2240\n02:28:57.050 --> 02:28:59.080\n别冲动，辣手神探\n\n2241\n02:29:02.220 --> 02:29:03.960\n完成你的书\n\n2242\n02:29:12.690 --> 02:29:15.930\n谢谢，谢谢你的早餐\n\n2243\n02:29:39.840 --> 02:29:44.580\n1983年12月20日 加州 瓦列霍\n\n2244\n02:30:23.380 --> 02:30:25.000\n我能效劳吗？\n\n2245\n02:30:26.640 --> 02:30:28.000\n不用\n\n2246\n02:30:58.840 --> 02:31:04.120\n七年半后 加州 安大略 1991年8月16日\n\n2247\n02:31:11.720 --> 02:31:13.340\n畅销书\n\n2248\n02:31:48.720 --> 02:31:50.340\n梅休先生\n\n2249\n02:31:51.010 --> 02:31:54.510\n-感谢你抽空过来\n-你就是电话中的那个人？\n\n2250\n02:31:54.720 --> 02:31:59.050\n瓦列霍警局，我是乔治巴渥\n我接手杰克穆拉斯的案子\n\n2251\n02:31:59.270 --> 02:32:02.180\n都22年了，我不确定帮得上忙\n\n2252\n02:32:02.400 --> 02:32:05.060\n这是警方的正常程序\n我要让你看一些照片\n\n2253\n02:32:05.280 --> 02:32:08.690\n射伤你的人也许在这些人当中\n\n2254\n02:32:09.450 --> 02:32:12.900\n你不一定要指出任何人，懂吗？\n\n2255\n02:32:13.120 --> 02:32:15.030\n我懂，警官\n\n2256\n02:32:15.250 --> 02:32:17.030\n好吧\n\n2257\n02:32:17.660 --> 02:32:19.360\n慢慢来\n\n2258\n02:32:19.620 --> 02:32:22.160\n你认不出任何人也没关系\n\n2259\n02:32:33.930 --> 02:32:35.550\n是他\n\n2260\n02:32:36.850 --> 02:32:38.470\n你有多确定？\n\n2261\n02:32:38.770 --> 02:32:40.390\n非常确定\n\n2262\n02:32:43.520 --> 02:32:45.520\n-他像这家伙有张圆脸\n-等等\n\n2263\n02:32:45.730 --> 02:32:47.850\n你又指认第二张照片吗？\n\n2264\n02:32:48.070 --> 02:32:51.350\n不，我只是说他也有一张圆脸\n\n2265\n02:32:52.990 --> 02:32:54.150\n就是这个人\n\n2266\n02:32:55.240 --> 02:32:56.860\n好吧\n\n2267\n02:32:58.450 --> 02:33:02.240\n1到10分， 10分是最确定\n\n2268\n02:33:05.590 --> 02:33:07.450\n你有多确定？\n\n2269\n02:33:10.970 --> 02:33:12.580\n至少有8分\n\n2270\n02:33:15.390 --> 02:33:20.260\n我最后一次看到这张脸\n是1969年7月4日\n\n2271\n02:33:22.520 --> 02:33:26.430\n我很确定他是向我开枪的家伙\n\n2272\n02:33:30.650 --> 02:33:33.560\n麦克梅休指认亚瑟李艾伦之后\n\n2273\n02:33:33.780 --> 02:33:37.280\n警方安排了一次会议，\n打算以多重谋杀罪起诉他\n\n2274\n02:33:37.490 --> 02:33:40.860\n艾伦在会议进行以前因为心脏病发身亡\n\n2275\n02:33:42.210 --> 02:33:44.910\n2002年艾伦的DNA不符合\n\n2276\n02:33:45.130 --> 02:33:47.490\n33年前十二宫杀手信件采到的样本\n\n2277\n02:33:47.710 --> 02:33:49.830\n旧金山及瓦列霍警方\n\n2278\n02:33:50.050 --> 02:33:53.120\n拒绝根据DNA检验报告排除艾伦的涉案嫌疑\n\n2279\n02:33:53.340 --> 02:33:55.420\n2004年，旧金山警局\n\n2280\n02:33:55.640 --> 02:33:57.500\n撤销对于十二宫杀手的调查\n\n2281\n02:33:57.720 --> 02:33:59.630\n至今本案在那帕市、索拉诺郡\n\n2282\n02:33:59.850 --> 02:34:00.840\n以及瓦列霍市仍然开放调查\n\n2283\n02:34:01.060 --> 02:34:04.010\n亚瑟李艾伦仍是唯一的主嫌\n\n2284\n02:34:05.650 --> 02:34:09.430\n陶希警探于1989年从旧金山警局退休\n\n2285\n02:34:09.650 --> 02:34:12.940\n他于1978年被控伪造十二宫\n杀手信件一案也被撤销\n\n2286\n02:34:13.150 --> 02:34:16.270\n保罗艾瑞于2000年12月10日\n因肺气肿去世，享年66岁\n\n2287\n02:34:16.490 --> 02:34:20.110\n他的骨灰由他的家人撒在旧金山湾\n\n2288\n02:34:20.330 --> 02:34:22.320\n罗伯葛雷史密斯定居旧金山\n\n2289\n02:34:22.540 --> 02:34:25.160\n和他的小孩维持良好关系\n\n2290\n02:34:25.380 --> 02:34:28.830\n他声称亚瑟李艾伦去世之后\n就没再接到匿名电话\n" }); }
